PRINT N'Creating Procedure [dbo].[sp_SellerGetDashboard]...';


GO
CREATE PROCEDURE [dbo].[sp_SellerGetDashboard]
    @SellerId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalProducts INT = 0;
    DECLARE @ActiveProducts INT = 0;
    DECLARE @LowStockCount INT = 0;
    DECLARE @TotalOrders INT = 0;
    DECLARE @TotalSales DECIMAL(18,2) = 0;

    -- Total products for this seller
    SELECT @TotalProducts = COUNT(*)
    FROM [dbo].[Products]
    WHERE [SellerId] = @SellerId AND [IsDeleted] = 0;

    -- Active products (IsActive = 1 and ApprovalStatus = 2 for approved)
    SELECT @ActiveProducts = COUNT(*)
    FROM [dbo].[Products]
    WHERE [SellerId] = @SellerId AND [IsActive] = 1 AND [ApprovalStatus] = 2 AND [IsDeleted] = 0;

    -- Low stock products (any variant with StockQuantity < LowStockThreshold)
    SELECT @LowStockCount = COUNT(DISTINCT p.[ProductId])
    FROM [dbo].[Products] p
    INNER JOIN [dbo].[ProductVariants] pv ON pv.[ProductId] = p.[ProductId]
    WHERE p.[SellerId] = @SellerId
      AND p.[IsDeleted] = 0
      AND pv.[StockQuantity] < ISNULL(pv.[LowStockThreshold], 10)
      AND pv.[IsDeleted] = 0;

    -- Total orders from this seller's items
    SELECT @TotalOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0;

    -- Total sales from this seller
    SELECT @TotalSales = ISNULL(SUM(oi.[UnitPrice] * oi.[Quantity]), 0)
    FROM [dbo].[OrderItems] oi
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0;

    -- Return dashboard metrics
    SELECT
        @TotalProducts AS [TotalProducts],
        @ActiveProducts AS [ActiveProducts],
        @LowStockCount AS [LowStockCount],
        @TotalOrders AS [TotalOrders],
        @TotalSales AS [TotalSales];
END;
GO
PRINT N'Creating Procedure [dbo].[sp_SellerGetOrderDetail]...';


GO
-- ============================================================
-- Get Order Detail for Seller (Multiple Result Sets)
-- ============================================================
-- Purpose: Retrieve complete order information including items and address
-- Returns: 3 result sets (Order, Items, Address)
-- ============================================================

CREATE PROCEDURE [dbo].[sp_SellerGetOrderDetail]
    @SellerId   INT,
    @OrderId    INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Result Set 1: Order Header
    SELECT
        o.[OrderId],
        o.[OrderNumber],
        o.[UserId],
        o.[OrderStatus] AS [Status],
        o.[PaymentMode] AS [PaymentMethod],
        o.[PaymentStatus],
        o.[SubTotal] AS [TotalMRP],
        o.[DiscountAmount],
        o.[CouponDiscount],
        ISNULL('', '') AS [CouponCode],
        o.[TaxAmount],
        o.[ShippingCharge],
        o.[TotalAmount],
        CAST(o.[CreatedAt] AS DATE) AS [OrderDate],
        o.[CreatedAt],
        ISNULL(CONCAT(u.[FirstName], ' ', u.[LastName]), '') AS [ShipToName],
        ISNULL(u.[Mobile], '') AS [ShipToMobile],
        ISNULL(ua.[AddressLine1], '') AS [AddressLine1],
        ISNULL(ua.[AddressLine2], '') AS [AddressLine2],
        ISNULL(ua.[City], '') AS [City],
        ISNULL(ua.[State], '') AS [State],
        ISNULL(ua.[PinCode], '') AS [Pincode]
    FROM [dbo].[Orders] o
    INNER JOIN [dbo].[Users] u ON o.[UserId] = u.[UserId]
    LEFT JOIN [dbo].[UserAddresses] ua ON o.[ShippingAddressId] = ua.[AddressId]
    WHERE o.[OrderId] = @OrderId
      AND o.[IsDeleted] = 0
      AND EXISTS (
          SELECT 1 FROM [dbo].[OrderItems] oi
          WHERE oi.[OrderId] = o.[OrderId]
            AND oi.[SellerId] = @SellerId
            AND oi.[IsDeleted] = 0
      );

    -- Result Set 2: Order Items
    SELECT
        oi.[OrderItemId],
        oi.[ProductId],
        oi.[OrderId],
        oi.[Quantity],
        oi.[UnitPrice],
        oi.[DiscountAmount],
        oi.[TaxAmount],
        oi.[TotalPrice],
        o.[OrderStatus] AS [Status],
        oi.[ProductName],
        b.[BrandName],
        ISNULL(pi.[ImageUrl], '') AS [ImageUrl],
        oi.[CreatedAt]
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    INNER JOIN [dbo].[Brands] b ON oi.[BrandId] = b.[BrandId]
    LEFT JOIN [dbo].[ProductImages] pi ON oi.[ProductId] = pi.[ProductId] AND pi.[IsPrimary] = 1
    WHERE oi.[OrderId] = @OrderId
      AND oi.[SellerId] = @SellerId
      AND oi.[IsDeleted] = 0
    ORDER BY oi.[OrderItemId];

    -- Result Set 3: Address (structured)
    SELECT
        ISNULL(CONCAT(u.[FirstName], ' ', u.[LastName]), '') AS [Name],
        ISNULL(u.[Mobile], '') AS [Mobile],
        ISNULL(ua.[AddressLine1], '') AS [Line1],
        ISNULL(ua.[AddressLine2], '') AS [Line2],
        ISNULL(ua.[City], '') AS [City],
        ISNULL(ua.[State], '') AS [State],
        ISNULL(ua.[PinCode], '') AS [Pincode],
        ISNULL(ua.[Country], 'India') AS [Country]
    FROM [dbo].[Orders] o
    INNER JOIN [dbo].[Users] u ON o.[UserId] = u.[UserId]
    LEFT JOIN [dbo].[UserAddresses] ua ON o.[ShippingAddressId] = ua.[AddressId]
    WHERE o.[OrderId] = @OrderId
      AND o.[IsDeleted] = 0;
END;
GO
