CREATE PROCEDURE [dbo].[sp_SellerGetProfile]
    @SellerId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        s.[SellerId]                                                     AS [Id],
        NULLIF(s.[BusinessName], N'')                                    AS [BusinessName],
        s.[OwnerName],
        u.[Email],
        u.[Mobile]                                                       AS [PhoneNumber],
        s.[GstNumber]                                                    AS [GSTNumber],
        s.[Address],
        s.[City],
        s.[State],
        s.[Pincode],
        s.[DisplayName],
        s.[StoreDescription],
        s.[BannerUrl],
        s.[LogoUrl],
        s.[SupportEmail],
        s.[SupportPhone],
        s.[Description],
        u.[IsMobileVerified]                                             AS [IsPhoneVerified],
        u.[IsEmailVerified],
        s.[IsIdVerified],
        s.[OnboardingCompleted],
        s.[PickupAddressLine1],
        s.[PickupAddressLine2],
        s.[PickupCity],
        s.[PickupState],
        s.[PickupPincode],
        s.[PickupLandmark],
