PRINT N'Creating Procedure [dbo].[sp_SellerLogin]...';


GO
CREATE PROCEDURE [dbo].[sp_SellerLogin]
    @Email NVARCHAR(256)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @UserId INT;
        DECLARE @RoleId INT;

        -- First check if user exists and get their role
        SELECT @UserId = [UserId], @RoleId = [RoleId]
        FROM   [dbo].[Users]
        WHERE  [Email]     = @Email
          AND  [IsDeleted] = 0
          AND  [IsActive]  = 1;

        IF @UserId IS NULL
            THROW 50003, N'User not found or account is inactive.', 1;

        -- Validate that user is a Seller (RoleId = 3)
        IF @RoleId != 3
            THROW 50005, N'This account is not a seller account. Please use the appropriate login page.', 1;

        -- Check if seller profile exists
        DECLARE @SellerId INT;
        SELECT @SellerId = [SellerId]
        FROM [dbo].[Sellers]
        WHERE [UserId] = @UserId
          AND [IsDeleted] = 0;

        IF @SellerId IS NULL
            THROW 50006, N'Seller profile not found. Please complete your seller registration.', 1;

        SELECT
            s.[SellerId]                                                     AS [Id],
            NULLIF(s.[BusinessName], N'')                                    AS [BusinessName],
            s.[OwnerName],
            u.[Email],
            u.[Mobile]                                                       AS [PhoneNumber],
            s.[GstNumber]                                                    AS [GSTNumber],
            s.[Address],
            s.[City],
            s.[State],
            s.[Pincode],
            s.[DisplayName],
            s.[StoreDescription],
            s.[BannerUrl],
            s.[LogoUrl],
            s.[SupportEmail],
            s.[SupportPhone],
            s.[Description],
            u.[IsMobileVerified]                                             AS [IsPhoneVerified],
            u.[IsEmailVerified],
            s.[IsIdVerified],
            s.[OnboardingCompleted],
            s.[PickupAddressLine1],
            s.[PickupAddressLine2],
            s.[PickupCity],
            s.[PickupState],
            s.[PickupPincode],
            s.[PickupLandmark],
            s.[SelectedCategories],
            s.[IsActive],
            CAST(CASE WHEN s.[ApprovalStatus] = 2 THEN 1 ELSE 0 END AS BIT) AS [IsApproved],
            s.[CreatedAt],
            s.[UpdatedAt],
            u.[PasswordHash]
        FROM [dbo].[Sellers] s
        INNER JOIN [dbo].[Users] u ON u.[UserId] = s.[UserId]
        WHERE u.[Email]     = @Email
          AND u.[IsDeleted] = 0
          AND s.[IsDeleted] = 0;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[sp_SellerSignup]...';


GO
CREATE PROCEDURE [dbo].[sp_SellerSignup]
    @Email        NVARCHAR(256),
    @PhoneNumber  NVARCHAR(15),
    @PasswordHash NVARCHAR(500),
    @SellerId     INT          OUTPUT,
    @ErrorCode    NVARCHAR(50) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @SellerId  = 0;
    SET @ErrorCode = NULL;

    BEGIN TRY
        -- Duplicate email check
        IF EXISTS (SELECT 1 FROM [dbo].[Users] WHERE [Email] = @Email AND [IsDeleted] = 0)
        BEGIN
            SET @ErrorCode = 'EMAIL_EXISTS';
            RETURN;
        END;

        BEGIN TRANSACTION;

            DECLARE @NewUserId INT;

            INSERT INTO [dbo].[Users]
                ([Email], [PasswordHash], [Mobile], [RoleId], [IsApproved], [ReferralCode])
            VALUES
                (@Email, @PasswordHash, @PhoneNumber, 3, 0,
                 UPPER(LEFT(REPLACE(CAST(NEWID() AS NVARCHAR(36)), N'-', N''), 8)));

            SET @NewUserId = SCOPE_IDENTITY();

            INSERT INTO [dbo].[Sellers]
                ([UserId], [BusinessName], [ApprovalStatus], [CreatedBy], [UpdatedBy])
            VALUES
                (@NewUserId, N'', 1, @NewUserId, @NewUserId);

            SET @SellerId = SCOPE_IDENTITY();

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[sp_SellerUpdateProfile]...';


GO
CREATE PROCEDURE [dbo].[sp_SellerUpdateProfile]
    @SellerId     INT,
    @BusinessName NVARCHAR(300) = NULL,
    @OwnerName    NVARCHAR(200) = NULL,
    @PhoneNumber  NVARCHAR(15)  = NULL,
    @GSTNumber    NVARCHAR(20)  = NULL,
    @Address      NVARCHAR(300) = NULL,
    @City         NVARCHAR(100) = NULL,
    @State        NVARCHAR(100) = NULL,
    @Pincode      NVARCHAR(10)  = NULL,
    @BannerUrl    NVARCHAR(500) = NULL,
    @LogoUrl      NVARCHAR(500) = NULL,
    @SupportEmail NVARCHAR(256) = NULL,
    @SupportPhone NVARCHAR(20)  = NULL,
    @Description  NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @UserId INT;
        SELECT @UserId = [UserId]
        FROM   [dbo].[Sellers]
        WHERE  [SellerId] = @SellerId AND [IsDeleted] = 0;

        IF @UserId IS NULL
            THROW 50095, N'Seller not found.', 1;

        BEGIN TRANSACTION;

            UPDATE [dbo].[Sellers]
            SET
                [BusinessName] = ISNULL(@BusinessName, [BusinessName]),
                [OwnerName]    = ISNULL(@OwnerName,    [OwnerName]),
                [GstNumber]    = ISNULL(@GSTNumber,    [GstNumber]),
                [Address]      = ISNULL(@Address,      [Address]),
                [City]         = ISNULL(@City,         [City]),
                [State]        = ISNULL(@State,        [State]),
                [Pincode]      = ISNULL(@Pincode,      [Pincode]),
                [BannerUrl]    = ISNULL(@BannerUrl,    [BannerUrl]),
                [LogoUrl]      = ISNULL(@LogoUrl,      [LogoUrl]),
                [SupportEmail] = ISNULL(@SupportEmail, [SupportEmail]),
                [SupportPhone] = ISNULL(@SupportPhone, [SupportPhone]),
                [Description]  = ISNULL(@Description,  [Description]),
                [UpdatedAt]    = GETUTCDATE(),
                [UpdatedBy]    = @SellerId
            WHERE [SellerId] = @SellerId;

            IF @PhoneNumber IS NOT NULL
                UPDATE [dbo].[Users]
                SET    [Mobile]    = @PhoneNumber,
                       [UpdatedAt] = GETUTCDATE()
                WHERE  [UserId] = @UserId;

        COMMIT TRANSACTION;

        -- Return updated profile
        SELECT
            s.[SellerId]                                                     AS [Id],
            NULLIF(s.[BusinessName], N'')                                    AS [BusinessName],
            s.[OwnerName],
            u.[Email],
            u.[Mobile]                                                       AS [PhoneNumber],
            s.[GstNumber]                                                    AS [GSTNumber],
            s.[Address],
            s.[City],
            s.[State],
            s.[Pincode],
            s.[DisplayName],
            s.[StoreDescription],
            s.[BannerUrl],
            s.[LogoUrl],
            s.[SupportEmail],
            s.[SupportPhone],
            s.[Description],
            u.[IsMobileVerified]                                             AS [IsPhoneVerified],
            u.[IsEmailVerified],
            s.[IsIdVerified],
            s.[OnboardingCompleted],
            s.[PickupAddressLine1],
            s.[PickupAddressLine2],
            s.[PickupCity],
            s.[PickupState],
            s.[PickupPincode],
            s.[PickupLandmark],
            s.[SelectedCategories],
            s.[IsActive],
            CAST(CASE WHEN s.[ApprovalStatus] = 2 THEN 1 ELSE 0 END AS BIT) AS [IsApproved],
            s.[CreatedAt],
            s.[UpdatedAt]
        FROM [dbo].[Sellers] s
        INNER JOIN [dbo].[Users] u ON u.[UserId] = s.[UserId]
        WHERE s.[SellerId] = @SellerId;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_AuditTrail_Log]...';


GO
-- Append-only write into AuditLogs from admin actions.
-- Action is constrained to INSERT/UPDATE/DELETE by CK on AuditLogs; the
-- richer verb (APPROVE, REJECT, SUSPEND, FORCE_CANCEL, REFUND, ...) is
-- embedded in @NewValues as a JSON envelope: { "verb": "...", "data": {...} }.
CREATE PROCEDURE [dbo].[usp_Admin_AuditTrail_Log]
    @TableName  NVARCHAR(100),
    @RecordId   INT,
    @Action     NVARCHAR(10),
    @OldValues  NVARCHAR(MAX) = NULL,
    @NewValues  NVARCHAR(MAX) = NULL,
    @ChangedBy  INT           = NULL,
    @IpAddress  NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    INSERT INTO [dbo].[AuditLogs]
        ([TableName], [RecordId], [Action], [OldValues], [NewValues], [ChangedBy], [IpAddress])
    VALUES
        (@TableName, @RecordId, @Action, @OldValues, @NewValues, @ChangedBy, @IpAddress);

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS [AuditId];
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_AuditTrail_Query]...';


GO
-- Paginated audit query with optional filters. Always orders by ChangedAt DESC.
CREATE PROCEDURE [dbo].[usp_Admin_AuditTrail_Query]
    @TableName  NVARCHAR(100) = NULL,
    @RecordId   INT           = NULL,
    @ChangedBy  INT           = NULL,
    @FromDate   DATETIME2(0)  = NULL,
    @ToDate     DATETIME2(0)  = NULL,
    @PageNumber INT           = 1,
    @PageSize   INT           = 20
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize   < 1 SET @PageSize   = 20;
    IF @PageSize   > 200 SET @PageSize = 200;

    ;WITH filtered AS (
        SELECT
            a.[AuditId],
            a.[TableName],
            a.[RecordId],
            a.[Action],
            a.[OldValues],
            a.[NewValues],
            a.[ChangedBy],
            a.[ChangedAt],
            a.[IpAddress],
            u.[Email]      AS [ChangedByEmail],
            u.[FirstName]  AS [ChangedByFirstName],
            u.[LastName]   AS [ChangedByLastName]
        FROM [dbo].[AuditLogs] a
        LEFT JOIN [dbo].[Users] u ON u.[UserId] = a.[ChangedBy]
        WHERE (@TableName IS NULL OR a.[TableName] = @TableName)
          AND (@RecordId  IS NULL OR a.[RecordId]  = @RecordId)
          AND (@ChangedBy IS NULL OR a.[ChangedBy] = @ChangedBy)
          AND (@FromDate  IS NULL OR a.[ChangedAt] >= @FromDate)
          AND (@ToDate    IS NULL OR a.[ChangedAt] <= @ToDate)
    )
    SELECT
        *,
        COUNT(1) OVER () AS [TotalCount]
    FROM filtered
    ORDER BY [ChangedAt] DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Category_Delete]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Category_Delete]
    @CategoryId   INT,
    @AdminUserId  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF EXISTS (
            SELECT 1 FROM [dbo].[Products]
            WHERE [CategoryId] = @CategoryId AND [IsDeleted] = 0
        )
            THROW 50201, 'Cannot delete category: products are still assigned to it. Reassign or delete those products first.', 1;

        UPDATE [dbo].[SubCategories]
        SET [IsDeleted] = 1,
            [UpdatedBy] = @AdminUserId,
            [UpdatedAt] = GETUTCDATE()
        WHERE [CategoryId] = @CategoryId
          AND [IsDeleted]  = 0;

        UPDATE [dbo].[Categories]
        SET [IsDeleted] = 1,
            [IsActive]  = 0,
            [UpdatedBy] = @AdminUserId,
            [UpdatedAt] = GETUTCDATE()
        WHERE [CategoryId] = @CategoryId
          AND [IsDeleted]  = 0;

        IF @@ROWCOUNT = 0
            THROW 50200, 'Category not found.', 1;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Category_Reorder]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Category_Reorder]
    @OrderJson    NVARCHAR(MAX),    -- JSON array: [{"categoryId":1,"sortOrder":0},...]
    @AdminUserId  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        WITH Incoming AS (
            SELECT [CategoryId], [SortOrder]
            FROM OPENJSON(@OrderJson)
            WITH (
                [CategoryId] INT '$.categoryId',
                [SortOrder]  INT '$.sortOrder'
            )
        )
        UPDATE c
        SET [SortOrder] = i.[SortOrder],
            [UpdatedBy] = @AdminUserId,
            [UpdatedAt] = GETUTCDATE()
        FROM [dbo].[Categories] c
        INNER JOIN Incoming i ON i.[CategoryId] = c.[CategoryId]
        WHERE c.[IsDeleted] = 0;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Category_ToggleVisibility]...';


