PRINT N'Creating Procedure [dbo].[usp_Admin_Category_Upsert]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Category_Upsert]
    @CategoryId       INT             = NULL,    -- NULL = insert
    @MenuId           INT,
    @CategoryName     NVARCHAR(200),
    @SlugUrl          NVARCHAR(300),
    @IconUrl          NVARCHAR(500)   = NULL,
    @BannerUrl        NVARCHAR(500)   = NULL,
    @SortOrder        INT             = 0,
    @IsFeatured       BIT             = 0,
    @ShowInMegaMenu   BIT             = 1,
    @MetaTitle        NVARCHAR(200)   = NULL,
    @MetaDescription  NVARCHAR(500)   = NULL,
    @AdminUserId      INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @CategoryId IS NULL OR @CategoryId = 0
        BEGIN
            INSERT INTO [dbo].[Categories]
                ([MenuId], [CategoryName], [SlugUrl], [IconUrl], [BannerUrl],
                 [SortOrder], [IsFeatured], [ShowInMegaMenu],
                 [MetaTitle], [MetaDescription],
                 [CreatedBy], [UpdatedBy], [CreatedAt], [UpdatedAt])
            VALUES
                (@MenuId, @CategoryName, @SlugUrl, @IconUrl, @BannerUrl,
                 @SortOrder, @IsFeatured, @ShowInMegaMenu,
                 @MetaTitle, @MetaDescription,
                 @AdminUserId, @AdminUserId, GETUTCDATE(), GETUTCDATE());

            SELECT CAST(SCOPE_IDENTITY() AS INT) AS [CategoryId];
        END
        ELSE
        BEGIN
            UPDATE [dbo].[Categories]
            SET
                [MenuId]           = @MenuId,
                [CategoryName]     = @CategoryName,
                [SlugUrl]          = @SlugUrl,
                [IconUrl]          = @IconUrl,
                [BannerUrl]        = @BannerUrl,
                [SortOrder]        = @SortOrder,
                [IsFeatured]       = @IsFeatured,
                [ShowInMegaMenu]   = @ShowInMegaMenu,
                [MetaTitle]        = @MetaTitle,
                [MetaDescription]  = @MetaDescription,
                [UpdatedBy]        = @AdminUserId,
                [UpdatedAt]        = GETUTCDATE()
            WHERE [CategoryId] = @CategoryId
              AND [IsDeleted]  = 0;

            IF @@ROWCOUNT = 0
                THROW 50200, 'Category not found.', 1;

            SELECT @CategoryId AS [CategoryId];
        END
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Complaint_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Complaint_GetAll]
    @Status      TINYINT       = NULL,
    @Category    NVARCHAR(50)  = NULL,
    @SearchTerm  NVARCHAR(200) = NULL,
    @Page        INT = 1,
    @PageSize    INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@Page - 1) * @PageSize;

        SELECT
            c.[ComplaintId],
            c.[UserId],
            u.[FirstName] + N' ' + ISNULL(u.[LastName], N'') AS [UserName],
            u.[Email]      AS [UserEmail],
            c.[OrderId],
            o.[OrderNumber],
            c.[Category],
            c.[Subject],
            c.[Body],
            c.[Status],
            c.[AdminNote],
            c.[Source],
            c.[CreatedAt],
            c.[UpdatedAt],
            COUNT(*) OVER() AS [TotalCount]
        FROM   [dbo].[Complaints] c
        INNER JOIN [dbo].[Users]    u ON u.[UserId]  = c.[UserId]
        LEFT  JOIN [dbo].[Orders]   o ON o.[OrderId] = c.[OrderId]
        WHERE  c.[IsDeleted] = 0
          AND  (@Status   IS NULL OR c.[Status]   = @Status)
          AND  (@Category IS NULL OR c.[Category] = @Category)
          AND  (@SearchTerm IS NULL
                OR c.[Subject] LIKE N'%' + @SearchTerm + N'%'
                OR c.[Body]    LIKE N'%' + @SearchTerm + N'%'
                OR u.[Email]   LIKE N'%' + @SearchTerm + N'%'
                OR u.[FirstName] LIKE N'%' + @SearchTerm + N'%'
                OR u.[LastName]  LIKE N'%' + @SearchTerm + N'%')
        ORDER BY c.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Complaint_UpdateStatus]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Complaint_UpdateStatus]
    @ComplaintId  INT,
    @Status       TINYINT,            -- 1 Open, 2 InProgress, 3 Resolved, 4 Closed
    @AdminNote    NVARCHAR(MAX) = NULL,
    @AdminUserId  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Status NOT IN (1, 2, 3, 4)
            THROW 50410, N'Invalid status code.', 1;

        DECLARE @UserId INT, @OldStatus TINYINT;
        SELECT @UserId = [UserId], @OldStatus = [Status]
        FROM   [dbo].[Complaints]
        WHERE  [ComplaintId] = @ComplaintId AND [IsDeleted] = 0;

        IF @UserId IS NULL
            THROW 50411, N'Complaint not found.', 1;

        UPDATE [dbo].[Complaints]
        SET    [Status]    = @Status,
               [AdminNote] = COALESCE(@AdminNote, [AdminNote]),
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @AdminUserId
        WHERE  [ComplaintId] = @ComplaintId;

        -- Buyer notification when status changes meaningfully.
        IF @Status <> @OldStatus
        BEGIN
            DECLARE @Label NVARCHAR(20) =
                CASE @Status WHEN 1 THEN N'reopened'
                             WHEN 2 THEN N'in progress'
                             WHEN 3 THEN N'resolved'
                             WHEN 4 THEN N'closed'
                             ELSE       N'updated'
                END;

            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@UserId,
                 N'Complaint ' + @Label,
                 N'Your complaint #' + CAST(@ComplaintId AS NVARCHAR(20)) + N' has been ' + @Label + N'.',
                 4, N'Complaint', @ComplaintId, 1);
        END
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Coupon_Create]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Coupon_Create]
    @CouponCode      NVARCHAR(50),
    @OfferName       NVARCHAR(300),
    @OfferType       TINYINT,           -- 1=Flat, 2=Percentage
    @DiscountValue   DECIMAL(18,2),
    @MinOrderValue   DECIMAL(18,2) = 0,
    @MaxDiscountCap  DECIMAL(18,2) = NULL,
    @StartDate       DATETIME2(0),
    @EndDate         DATETIME2(0),
    @ApplicableOn    TINYINT = 4,       -- 1=Product, 2=Brand, 3=Category, 4=Cart
    @EntityId        INT = NULL,
    @UsageLimitPerUser TINYINT = 1,
    @AdminUserId     INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF EXISTS (SELECT 1 FROM [dbo].[Coupons] WHERE [CouponCode] = @CouponCode AND [IsDeleted] = 0)
            THROW 50080, N'A coupon with this code already exists.', 1;

        IF @ApplicableOn = 2 AND @EntityId IS NULL
            THROW 50081, N'Brand-specific coupons require a brand id.', 1;

        BEGIN TRANSACTION;

        INSERT INTO [dbo].[Offers]
            ([OfferName], [OfferType], [DiscountValue], [MinOrderValue], [MaxDiscountCap],
             [StartDate], [EndDate], [ApplicableOn], [EntityId], [UsageLimitPerUser], [CreatedBy])
        VALUES
            (@OfferName, @OfferType, @DiscountValue, @MinOrderValue, @MaxDiscountCap,
             @StartDate, @EndDate, @ApplicableOn, @EntityId, @UsageLimitPerUser, @AdminUserId);

        DECLARE @NewOfferId INT = SCOPE_IDENTITY();

        INSERT INTO [dbo].[Coupons] ([CouponCode], [OfferId], [CreatedBy])
        VALUES (@CouponCode, @NewOfferId, @AdminUserId);

        DECLARE @NewCouponId INT = SCOPE_IDENTITY();

        COMMIT TRANSACTION;

        SELECT @NewCouponId AS [CouponId];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Coupon_Delete]...';


GO
-- Soft-delete a coupon and its parent Offer in one shot.
CREATE PROCEDURE [dbo].[usp_Admin_Coupon_Delete]
    @CouponId    INT,
    @AdminUserId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @OfferId INT;
        SELECT @OfferId = [OfferId]
        FROM   [dbo].[Coupons]
        WHERE  [CouponId] = @CouponId AND [IsDeleted] = 0;

        IF @OfferId IS NULL
            THROW 50095, N'Coupon not found.', 1;

        BEGIN TRANSACTION;

        UPDATE [dbo].[Coupons]
        SET    [IsDeleted] = 1,
               [IsActive]  = 0,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @AdminUserId
        WHERE  [CouponId]  = @CouponId;

        UPDATE [dbo].[Offers]
        SET    [IsDeleted] = 1,
               [IsActive]  = 0,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @AdminUserId
        WHERE  [OfferId]   = @OfferId;

        COMMIT TRANSACTION;

        SELECT 1 AS [Success];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Coupon_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Coupon_GetAll]
    @Page     INT = 1,
    @PageSize INT = 50
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@Page - 1) * @PageSize;

        SELECT
            cp.[CouponId],
            cp.[CouponCode],
            cp.[IsActive],
            o.[OfferId],
            o.[OfferName],
            o.[OfferType],         -- 1=Flat, 2=Percentage
            o.[DiscountValue],
            o.[MinOrderValue],
            o.[MaxDiscountCap],
            o.[StartDate],
            o.[EndDate],
            o.[ApplicableOn],      -- 1=Product, 2=Brand, 3=Category, 4=Cart
            o.[EntityId],
            b.[BrandName],
            o.[UsageLimitPerUser],
            o.[CurrentUsageCount],
            cp.[CreatedAt],
            COUNT(*) OVER() AS [TotalCount]
        FROM [dbo].[Coupons] cp
        INNER JOIN [dbo].[Offers] o ON o.[OfferId] = cp.[OfferId]
        LEFT  JOIN [dbo].[Brands] b ON o.[ApplicableOn] = 2 AND b.[BrandId] = o.[EntityId]
        WHERE cp.[IsDeleted] = 0
        ORDER BY cp.[CouponId] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
