PRINT N'Creating Procedure [dbo].[usp_Admin_Dashboard_GetStats]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Dashboard_GetStats]
    @FromDate DATE = NULL,
    @ToDate   DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SET @FromDate = COALESCE(@FromDate, DATEADD(DAY, -29, CAST(GETUTCDATE() AS DATE)));
        SET @ToDate   = COALESCE(@ToDate,   CAST(GETUTCDATE() AS DATE));

        -- Platform summary
        SELECT
            (SELECT COUNT(*) FROM [dbo].[Users]    WHERE [IsDeleted] = 0 AND [RoleId] = 2) AS [TotalBuyers],
            (SELECT COUNT(*) FROM [dbo].[Sellers]  WHERE [IsDeleted] = 0)                  AS [TotalSellers],
            (SELECT COUNT(*) FROM [dbo].[Sellers]  WHERE [IsDeleted] = 0 AND [ApprovalStatus] = 1) AS [PendingSellerApprovals],
            (SELECT COUNT(*) FROM [dbo].[Products] WHERE [IsDeleted] = 0)                  AS [TotalProducts],
            (SELECT COUNT(*) FROM [dbo].[Products] WHERE [IsDeleted] = 0 AND [ApprovalStatus] = 1) AS [PendingProductApprovals],
            (SELECT COUNT(*) FROM [dbo].[Orders]   WHERE [IsDeleted] = 0
              AND CAST([CreatedAt] AS DATE) BETWEEN @FromDate AND @ToDate) AS [TotalOrders],
            (SELECT ISNULL(SUM([TotalAmount]), 0)
             FROM [dbo].[Orders]
             WHERE [IsDeleted] = 0 AND [OrderStatus] NOT IN (6, 7)
               AND CAST([CreatedAt] AS DATE) BETWEEN @FromDate AND @ToDate) AS [TotalRevenue],
            -- Orders with at least one line still awaiting seller confirmation.
            (SELECT COUNT(DISTINCT oi.[OrderId])
             FROM   [dbo].[OrderItems] oi
             INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
             WHERE  oi.[IsDeleted]   = 0
               AND  o.[IsDeleted]    = 0
               AND  oi.[OrderStatus] = 1) AS [UnfulfilledOrders],
            (SELECT COUNT(*)
             FROM   [dbo].[OrderItems]
             WHERE  [IsDeleted]   = 0
               AND  [OrderStatus] = 8) AS [RejectedOrderItems];

        -- Daily order trend
        SELECT
            CAST(o.[CreatedAt] AS DATE)        AS [OrderDate],
            COUNT(*)                           AS [OrderCount],
            ISNULL(SUM(o.[TotalAmount]), 0)    AS [DailyRevenue]
        FROM [dbo].[Orders] o
        WHERE o.[IsDeleted] = 0
          AND o.[OrderStatus] NOT IN (6, 7)
          AND CAST(o.[CreatedAt] AS DATE) BETWEEN @FromDate AND @ToDate
        GROUP BY CAST(o.[CreatedAt] AS DATE)
        ORDER BY CAST(o.[CreatedAt] AS DATE) ASC;

        -- Top 5 sellers by revenue
        SELECT TOP 5
            s.[SellerId],
            s.[BusinessName],
            u.[Email],
            SUM(oi.[SellerEarning]) AS [TotalEarnings],
            COUNT(DISTINCT o.[OrderId]) AS [TotalOrders]
        FROM [dbo].[OrderItems]  oi
        INNER JOIN [dbo].[Orders]   o  ON o.[OrderId]  = oi.[OrderId]
        INNER JOIN [dbo].[Sellers]  s  ON s.[SellerId] = oi.[SellerId]
        INNER JOIN [dbo].[Users]    u  ON u.[UserId]   = s.[UserId]
        WHERE oi.[IsDeleted] = 0 AND o.[IsDeleted] = 0
          AND o.[OrderStatus] NOT IN (6, 7)
          AND CAST(o.[CreatedAt] AS DATE) BETWEEN @FromDate AND @ToDate
        GROUP BY s.[SellerId], s.[BusinessName], u.[Email]
        ORDER BY SUM(oi.[SellerEarning]) DESC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_MegaMenu_GetTree]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_MegaMenu_GetTree]
    @IncludeInactive  BIT = 1     -- admin view defaults to showing all
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Result set 1: categories
        SELECT
            c.[CategoryId],
            c.[MenuId],
            m.[MenuName],
            c.[CategoryName],
            c.[SlugUrl],
            c.[IconUrl],
            c.[BannerUrl],
            c.[SortOrder],
            c.[IsFeatured],
            c.[ShowInMegaMenu],
            c.[IsActive],
            c.[MetaTitle],
            c.[MetaDescription],
            (SELECT COUNT(*)
                 FROM [dbo].[SubCategories] sc
                WHERE sc.[CategoryId] = c.[CategoryId]
                  AND sc.[IsDeleted]  = 0) AS [SubCategoryCount],
            (SELECT COUNT(*)
                 FROM [dbo].[Products] p
                WHERE p.[CategoryId] = c.[CategoryId]
                  AND p.[IsDeleted]  = 0) AS [ProductCount]
        FROM [dbo].[Categories] c
        LEFT JOIN [dbo].[Menus] m ON m.[MenuId] = c.[MenuId]
        WHERE c.[IsDeleted] = 0
          AND (@IncludeInactive = 1 OR c.[IsActive] = 1)
        ORDER BY c.[MenuId], c.[SortOrder], c.[CategoryName];

        -- Result set 2: subcategories
        SELECT
            sc.[SubCategoryId],
            sc.[CategoryId],
            sc.[SubCategoryName],
            sc.[SlugUrl],
            sc.[IconUrl],
            sc.[SortOrder],
            sc.[IsFeatured],
            sc.[ShowInMegaMenu],
            sc.[IsActive],
            sc.[MetaTitle],
            sc.[MetaDescription],
            (SELECT COUNT(*)
                 FROM [dbo].[Products] p
                WHERE p.[SubCategoryId] = sc.[SubCategoryId]
                  AND p.[IsDeleted]     = 0) AS [ProductCount]
        FROM [dbo].[SubCategories] sc
        INNER JOIN [dbo].[Categories] c ON c.[CategoryId] = sc.[CategoryId]
        WHERE sc.[IsDeleted] = 0
          AND c.[IsDeleted]  = 0
          AND (@IncludeInactive = 1 OR sc.[IsActive] = 1)
        ORDER BY sc.[CategoryId], sc.[SortOrder], sc.[SubCategoryName];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Order_ForceCancel]...';


GO
-- Admin-driven order cancellation. Unlike buyer cancel, this bypasses the
-- "only PLACED/CONFIRMED may cancel" guard but still refuses terminal states.
CREATE PROCEDURE [dbo].[usp_Admin_Order_ForceCancel]
    @OrderId     INT,
    @AdminUserId INT,
    @Reason      NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @CurrentStatus TINYINT;
        SELECT @CurrentStatus = [OrderStatus]
        FROM   [dbo].[Orders]
        WHERE  [OrderId] = @OrderId AND [IsDeleted] = 0;

        IF @CurrentStatus IS NULL
            THROW 50150, N'Order not found.', 1;

        IF @CurrentStatus IN (5, 6, 7)  -- Delivered / Cancelled / Returned
            THROW 50151, N'Order is in a terminal state and cannot be force-cancelled.', 1;

        UPDATE [dbo].[Orders]
        SET    [OrderStatus]        = 6,
               [CancelledAt]        = GETUTCDATE(),
               [CancellationReason] = @Reason,
               [UpdatedAt]          = GETUTCDATE(),
               [UpdatedBy]          = @AdminUserId
        WHERE  [OrderId] = @OrderId;

        SELECT 1 AS [Success];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Order_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_Order_GetAll]
    @OrderStatus         TINYINT       = NULL,
    @FromDate            DATE          = NULL,
    @ToDate              DATE          = NULL,
    @SearchTerm          NVARCHAR(200) = NULL,
    @LineStatusFilter    TINYINT       = NULL,   -- only include orders with at least one OrderItem at this status (1=Placed → Unfulfilled, 8=Rejected)
    @PaymentStatusFilter TINYINT       = NULL,   -- 2 = Paid
    @PageNumber          INT           = 1,
    @PageSize            INT           = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            o.[OrderId],
            o.[OrderNumber],
            o.[OrderStatus],
            o.[TotalAmount],
            o.[PaymentMode],
            o.[PaymentStatus],
            o.[CreatedAt]  AS [OrderDate],
            u.[FirstName],
            u.[LastName],
            u.[Email],
            COUNT(oi.[OrderItemId]) AS [ItemCount],
            COUNT(*)        OVER()  AS [TotalCount]
        FROM [dbo].[Orders]      o
        INNER JOIN [dbo].[Users]      u  ON u.[UserId]  = o.[UserId]
        INNER JOIN [dbo].[OrderItems] oi ON oi.[OrderId] = o.[OrderId] AND oi.[IsDeleted] = 0
        WHERE o.[IsDeleted] = 0
          AND (@OrderStatus IS NULL OR o.[OrderStatus]                 = @OrderStatus)
          AND (@FromDate    IS NULL OR CAST(o.[CreatedAt] AS DATE)    >= @FromDate)
          AND (@ToDate      IS NULL OR CAST(o.[CreatedAt] AS DATE)    <= @ToDate)
          AND (@SearchTerm  IS NULL  OR o.[OrderNumber] LIKE N'%' + @SearchTerm + N'%'
                                    OR u.[Email]        LIKE N'%' + @SearchTerm + N'%'
                                    OR u.[FirstName]    LIKE N'%' + @SearchTerm + N'%'
                                    OR u.[LastName]     LIKE N'%' + @SearchTerm + N'%')
          AND (@PaymentStatusFilter IS NULL OR o.[PaymentStatus] = @PaymentStatusFilter)
          AND (@LineStatusFilter    IS NULL
               OR EXISTS (
                   SELECT 1 FROM [dbo].[OrderItems] x
                   WHERE x.[OrderId]     = o.[OrderId]
                     AND x.[IsDeleted]   = 0
                     AND x.[OrderStatus] = @LineStatusFilter
               ))
        GROUP BY
            o.[OrderId], o.[OrderNumber], o.[OrderStatus], o.[TotalAmount],
            o.[PaymentMode], o.[PaymentStatus], o.[CreatedAt],
            u.[FirstName], u.[LastName], u.[Email]
        ORDER BY o.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_Order_ManualRefund]...';


GO
-- Mark an order's payment as refunded. Does NOT call any payment gateway —
-- gateway interaction is the caller's responsibility; this SP records the
-- post-condition once the gateway confirms.
CREATE PROCEDURE [dbo].[usp_Admin_Order_ManualRefund]
    @OrderId      INT,
    @AdminUserId  INT,
    @RefundAmount DECIMAL(18,2),
    @Reason       NVARCHAR(500),
    @GatewayRef   NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @PaymentStatus TINYINT, @TotalAmount DECIMAL(18,2);
        SELECT @PaymentStatus = [PaymentStatus],
               @TotalAmount   = [TotalAmount]
        FROM   [dbo].[Orders]
        WHERE  [OrderId] = @OrderId AND [IsDeleted] = 0;

        IF @PaymentStatus IS NULL
            THROW 50160, N'Order not found.', 1;

        IF @PaymentStatus = 4
            THROW 50161, N'Order is already refunded.', 1;

        IF @PaymentStatus <> 2
            THROW 50162, N'Only paid orders can be refunded.', 1;

        IF @RefundAmount <= 0 OR @RefundAmount > @TotalAmount
            THROW 50163, N'Refund amount must be positive and not exceed order total.', 1;

        UPDATE [dbo].[Orders]
        SET    [PaymentStatus]          = 4,
               [PaymentGatewayResponse] = CONCAT(
                    N'{"refund":{"amount":', @RefundAmount,
                    N',"reason":"', REPLACE(ISNULL(@Reason, N''), N'"', N'\"'),
                    N'","gatewayRef":"', ISNULL(@GatewayRef, N''),
                    N'","adminUserId":', @AdminUserId,
                    N',"at":"', CONVERT(NVARCHAR(33), SYSUTCDATETIME(), 127), N'"}}'),
               [UpdatedAt]              = GETUTCDATE(),
               [UpdatedBy]              = @AdminUserId
        WHERE  [OrderId] = @OrderId;

        SELECT 1 AS [Success];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
