PRINT N'Creating Procedure [dbo].[usp_Admin_SubCategory_Upsert]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_SubCategory_Upsert]
    @SubCategoryId    INT             = NULL,    -- NULL = insert
    @CategoryId       INT,
    @SubCategoryName  NVARCHAR(200),
    @SlugUrl          NVARCHAR(300),
    @IconUrl          NVARCHAR(500)   = NULL,
    @SortOrder        INT             = 0,
    @IsFeatured       BIT             = 0,
    @ShowInMegaMenu   BIT             = 1,
    @MetaTitle        NVARCHAR(200)   = NULL,
    @MetaDescription  NVARCHAR(500)   = NULL,
    @AdminUserId      INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[Categories]
            WHERE [CategoryId] = @CategoryId AND [IsDeleted] = 0
        )
            THROW 50202, 'Parent category not found.', 1;

        IF @SubCategoryId IS NULL OR @SubCategoryId = 0
        BEGIN
            INSERT INTO [dbo].[SubCategories]
                ([CategoryId], [SubCategoryName], [SlugUrl], [IconUrl],
                 [SortOrder], [IsFeatured], [ShowInMegaMenu],
                 [MetaTitle], [MetaDescription],
                 [CreatedBy], [UpdatedBy], [CreatedAt], [UpdatedAt])
            VALUES
                (@CategoryId, @SubCategoryName, @SlugUrl, @IconUrl,
                 @SortOrder, @IsFeatured, @ShowInMegaMenu,
                 @MetaTitle, @MetaDescription,
                 @AdminUserId, @AdminUserId, GETUTCDATE(), GETUTCDATE());

            SELECT CAST(SCOPE_IDENTITY() AS INT) AS [SubCategoryId];
        END
        ELSE
        BEGIN
            UPDATE [dbo].[SubCategories]
            SET
                [CategoryId]       = @CategoryId,
                [SubCategoryName]  = @SubCategoryName,
                [SlugUrl]          = @SlugUrl,
                [IconUrl]          = @IconUrl,
                [SortOrder]        = @SortOrder,
                [IsFeatured]       = @IsFeatured,
                [ShowInMegaMenu]   = @ShowInMegaMenu,
                [MetaTitle]        = @MetaTitle,
                [MetaDescription]  = @MetaDescription,
                [UpdatedBy]        = @AdminUserId,
                [UpdatedAt]        = GETUTCDATE()
            WHERE [SubCategoryId] = @SubCategoryId
              AND [IsDeleted]     = 0;

            IF @@ROWCOUNT = 0
                THROW 50203, 'Subcategory not found.', 1;

            SELECT @SubCategoryId AS [SubCategoryId];
        END
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_SubCategoryOption_BulkSet]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_SubCategoryOption_BulkSet]
    @SubCategoryId  INT,
    @AttributeId    INT,
    @OptionsJson    NVARCHAR(MAX),    -- [{"optionValue":"XL","optionMetadata":null,"sortOrder":4},...]
    @AdminUserId    INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Stage incoming values
        DECLARE @Incoming TABLE (
            [OptionValue]     NVARCHAR(100) NOT NULL,
            [OptionMetadata]  NVARCHAR(200) NULL,
            [SortOrder]       INT           NOT NULL
        );

        INSERT INTO @Incoming ([OptionValue], [OptionMetadata], [SortOrder])
        SELECT [OptionValue], [OptionMetadata], [SortOrder]
        FROM OPENJSON(@OptionsJson)
        WITH (
            [OptionValue]    NVARCHAR(100) '$.optionValue',
            [OptionMetadata] NVARCHAR(200) '$.optionMetadata',
            [SortOrder]      INT           '$.sortOrder'
        );

        -- Reactivate + update matches
        UPDATE existing
        SET [OptionMetadata] = i.[OptionMetadata],
            [SortOrder]      = i.[SortOrder],
            [IsActive]       = 1,
            [UpdatedBy]      = @AdminUserId,
            [UpdatedAt]      = GETUTCDATE()
        FROM [dbo].[SubCategoryVariantOptions] existing
        INNER JOIN @Incoming i ON i.[OptionValue] = existing.[OptionValue]
        WHERE existing.[SubCategoryId] = @SubCategoryId
          AND existing.[AttributeId]   = @AttributeId;

        -- Insert brand-new
        INSERT INTO [dbo].[SubCategoryVariantOptions]
            ([SubCategoryId], [AttributeId], [OptionValue], [OptionMetadata],
             [SortOrder], [CreatedBy], [UpdatedBy])
        SELECT @SubCategoryId, @AttributeId, i.[OptionValue], i.[OptionMetadata],
               i.[SortOrder], @AdminUserId, @AdminUserId
        FROM @Incoming i
        WHERE NOT EXISTS (
            SELECT 1 FROM [dbo].[SubCategoryVariantOptions] existing
            WHERE existing.[SubCategoryId] = @SubCategoryId
              AND existing.[AttributeId]   = @AttributeId
              AND existing.[OptionValue]   = i.[OptionValue]
        );

        -- Deactivate values that were removed (don't hard-delete — products may still reference)
        UPDATE [dbo].[SubCategoryVariantOptions]
        SET [IsActive]  = 0,
            [UpdatedBy] = @AdminUserId,
            [UpdatedAt] = GETUTCDATE()
        WHERE [SubCategoryId] = @SubCategoryId
          AND [AttributeId]   = @AttributeId
          AND [OptionValue] NOT IN (SELECT [OptionValue] FROM @Incoming);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_SubCategoryOption_Delete]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_SubCategoryOption_Delete]
    @OptionId    INT,
    @AdminUserId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Soft-delete = mark inactive. Hard delete blocked if any product references it.
        IF EXISTS (
            SELECT 1 FROM [dbo].[ProductDisabledVariantOptions]
            WHERE [OptionId] = @OptionId
        )
        BEGIN
            UPDATE [dbo].[SubCategoryVariantOptions]
            SET [IsActive]  = 0,
                [UpdatedBy] = @AdminUserId,
                [UpdatedAt] = GETUTCDATE()
            WHERE [OptionId] = @OptionId;
        END
        ELSE
        BEGIN
            DELETE FROM [dbo].[SubCategoryVariantOptions]
            WHERE [OptionId] = @OptionId;
        END

        IF @@ROWCOUNT = 0
            THROW 50220, 'Variant option not found.', 1;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Admin_SubCategoryOption_GetBySubCategory]...';


GO
CREATE PROCEDURE [dbo].[usp_Admin_SubCategoryOption_GetBySubCategory]
    @SubCategoryId   INT,
    @IncludeInactive BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT
            o.[OptionId],
            o.[SubCategoryId],
            o.[AttributeId],
            a.[AttributeKey],
            a.[DisplayName]   AS [AttributeName],
            a.[InputType],
            o.[OptionValue],
            o.[OptionMetadata],
            o.[SortOrder],
            o.[IsActive]
        FROM [dbo].[SubCategoryVariantOptions] o
        INNER JOIN [dbo].[VariantAttributes]   a ON a.[AttributeId] = o.[AttributeId]
        WHERE o.[SubCategoryId] = @SubCategoryId
          AND (@IncludeInactive = 1 OR o.[IsActive] = 1)
          AND a.[IsActive] = 1
        ORDER BY a.[SortOrder], a.[DisplayName], o.[SortOrder], o.[OptionValue];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
