GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_Create]
    @SellerId         INT,
    @BrandId          INT,
    @CategoryId       INT,
    @SubCategoryId    INT,
    @ProductName      NVARCHAR(300),
    @SlugUrl          NVARCHAR(400),
    @ShortDescription NVARCHAR(500) = NULL,
    @LongDescription  NVARCHAR(MAX) = NULL,
    @MRP              DECIMAL(18,2),
    @SellingPrice     DECIMAL(18,2),
    @CostPrice        DECIMAL(18,2) = NULL,
    @GstRate          DECIMAL(5,2)  = 0,
    @Sku              NVARCHAR(100) = NULL,
    @GenderTypeId     TINYINT       = NULL,
    @IsReturnable     BIT           = 1,
    @ReturnWindowDays TINYINT       = 7,
    @IsCODAvailable   BIT           = 1,
    @Tags             NVARCHAR(1000) = NULL,
    @MetaTitle        NVARCHAR(200)  = NULL,
    @MetaDescription  NVARCHAR(500)  = NULL,
    @MetaKeywords     NVARCHAR(500)  = NULL,
    @LengthCm         DECIMAL(8,2)   = NULL,
    @WidthCm          DECIMAL(8,2)   = NULL,
    @HeightCm         DECIMAL(8,2)   = NULL,
    @WeightGm         DECIMAL(10,2)  = NULL,
    @CreatedBy        INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SlugUrl] = @SlugUrl AND [IsDeleted] = 0)
            THROW 50030, N'A product with this slug URL already exists.', 1;

        IF @Sku IS NOT NULL AND EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [Sku] = @Sku AND [IsDeleted] = 0)
            THROW 50031, N'A product with this SKU already exists.', 1;

        IF @SellingPrice > @MRP
            THROW 50032, N'Selling price cannot exceed MRP.', 1;

        -- Verify seller-brand mapping is approved
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[SellerBrandMappings]
            WHERE [SellerId] = @SellerId AND [BrandId] = @BrandId AND [IsApproved] = 1 AND [IsDeleted] = 0
        )
            THROW 50033, N'Seller is not authorised to list products under this brand.', 1;

        INSERT INTO [dbo].[Products]
            ([SellerId], [BrandId], [CategoryId], [SubCategoryId], [ProductName], [SlugUrl],
             [ShortDescription], [LongDescription], [MRP], [SellingPrice], [CostPrice], [GstRate],
             [Sku], [GenderTypeId], [IsReturnable], [ReturnWindowDays], [IsCODAvailable],
             [Tags], [MetaTitle], [MetaDescription], [MetaKeywords],
             [LengthCm], [WidthCm], [HeightCm], [WeightGm],
             [ApprovalStatus], [CreatedBy], [UpdatedBy])
        VALUES
            (@SellerId, @BrandId, @CategoryId, @SubCategoryId, @ProductName, @SlugUrl,
             @ShortDescription, @LongDescription, @MRP, @SellingPrice, @CostPrice, @GstRate,
             @Sku, @GenderTypeId, @IsReturnable, @ReturnWindowDays, @IsCODAvailable,
             @Tags, @MetaTitle, @MetaDescription, @MetaKeywords,
             @LengthCm, @WidthCm, @HeightCm, @WeightGm,
             1, @CreatedBy, @CreatedBy);

        DECLARE @NewProductId INT = SCOPE_IDENTITY();

        SELECT @NewProductId AS [ProductId];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_GetById]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_GetById]
    @ProductId INT  = NULL,
    @SlugUrl   NVARCHAR(400) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT
            p.[ProductId],
            p.[SellerId],
            p.[BrandId],
            p.[CategoryId],
            p.[SubCategoryId],
            p.[ProductName],
            p.[SlugUrl],
            p.[ShortDescription],
            p.[LongDescription],
            p.[MRP],
            p.[SellingPrice],
            p.[CostPrice],
            p.[GstRate],
            p.[Sku],
            p.[GenderTypeId],
            p.[IsReturnable],
            p.[ReturnWindowDays],
            p.[IsCODAvailable],
            p.[Tags],
            p.[IsFeatured],
            p.[ApprovalStatus],
            p.[PublishedAt],
            p.[MetaTitle],
            p.[MetaDescription],
            p.[MetaKeywords],

            -- Extended product details (nullable)
            p.[Material],
            p.[CareInstructions],
            p.[FitType],
            p.[CountryOfOrigin],
            p.[WarrantyInfo],
            p.[DeliveryInfo],

            b.[BrandName],
            b.[SlugUrl]    AS [BrandSlug],
            b.[LogoUrl]    AS [BrandLogoUrl],

            c.[CategoryName],
            sc.[SubCategoryName],

            gt.[Name]      AS [GenderType],

            s.[BusinessName] AS [SellerName]

        FROM [dbo].[Products]       p
        INNER JOIN [dbo].[Brands]       b   ON b.[BrandId]       = p.[BrandId]
        INNER JOIN [dbo].[Categories]   c   ON c.[CategoryId]    = p.[CategoryId]
        LEFT  JOIN [dbo].[SubCategories] sc ON sc.[SubCategoryId] = p.[SubCategoryId]
        INNER JOIN [dbo].[Sellers]      s   ON s.[SellerId]       = p.[SellerId]
        LEFT  JOIN [dbo].[GenderTypes]  gt  ON gt.[GenderTypeId]  = p.[GenderTypeId]

        WHERE p.[IsDeleted] = 0
          AND (p.[ProductId] = @ProductId OR @ProductId IS NULL)
          AND (p.[SlugUrl]   = @SlugUrl   OR @SlugUrl   IS NULL);

        -- Return variants
        SELECT
            [VariantId], [ProductId], [Color], [ColorHexCode], [Size],
            [Material], [Pattern], [FitType], [VariantSku],
            [AdditionalPrice], [StockQuantity], [LowStockThreshold],
            [Weight], [Dimensions], [BarCode], [IsActive]
        FROM [dbo].[ProductVariants]
        WHERE [ProductId] = COALESCE(@ProductId,
            (SELECT [ProductId] FROM [dbo].[Products] WHERE [SlugUrl] = @SlugUrl AND [IsDeleted] = 0))
          AND [IsDeleted] = 0;

        -- Return images
        SELECT [ImageId], [VariantId], [ImageUrl], [AltText], [SortOrder], [IsPrimary]
        FROM [dbo].[ProductImages]
        WHERE [ProductId] = COALESCE(@ProductId,
            (SELECT [ProductId] FROM [dbo].[Products] WHERE [SlugUrl] = @SlugUrl AND [IsDeleted] = 0))
          AND [IsDeleted] = 0
        ORDER BY [SortOrder] ASC;

        -- Return specifications
        SELECT [SpecId], [SpecKey], [SpecValue], [SortOrder]
        FROM [dbo].[ProductSpecifications]
        WHERE [ProductId] = COALESCE(@ProductId,
            (SELECT [ProductId] FROM [dbo].[Products] WHERE [SlugUrl] = @SlugUrl AND [IsDeleted] = 0))
          AND [IsDeleted] = 0
        ORDER BY [SortOrder] ASC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_GetFeatured]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_GetFeatured]
    @GenderTypeId TINYINT = NULL,
    @Limit        INT = 12
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT TOP (@Limit)
            p.[ProductId], p.[ProductName], p.[SlugUrl],
            p.[MRP], p.[SellingPrice], p.[SortOrder],
            b.[BrandName],
            c.[CategoryName],
            gt.[Name]          AS [GenderType],
            pi_.[ImageUrl]     AS [PrimaryImageUrl]
        FROM [dbo].[Products]       p
        INNER JOIN [dbo].[Brands]       b   ON b.[BrandId]      = p.[BrandId]
        INNER JOIN [dbo].[Categories]   c   ON c.[CategoryId]   = p.[CategoryId]
        LEFT  JOIN [dbo].[GenderTypes]  gt  ON gt.[GenderTypeId] = p.[GenderTypeId]
        LEFT  JOIN [dbo].[ProductImages] pi_ ON pi_.[ProductId] = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        WHERE p.[IsDeleted]      = 0
          AND p.[IsActive]       = 1
          AND p.[ApprovalStatus] = 2
          AND p.[IsFeatured]     = 1
          AND (p.[GenderTypeId]  = @GenderTypeId OR @GenderTypeId IS NULL)
        ORDER BY p.[SortOrder] ASC, p.[PublishedAt] DESC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_GetTrending]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_GetTrending]
    @WindowDays INT = 7,
    @Limit      INT = 12
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- "Trending right now" — rolling-window view count from ProductViewLogs joined to
    -- the product card payload. Falls back to featured if there's no view activity yet
    -- so the home page never renders an empty rail in fresh installs.
    BEGIN TRY
        DECLARE @Since DATETIME2(0) = DATEADD(DAY, -@WindowDays, GETUTCDATE());

        ;WITH ViewCounts AS (
            SELECT
                vl.[ProductId],
                COUNT_BIG(1) AS [ViewCount]
            FROM [dbo].[ProductViewLogs] vl
            WHERE vl.[ViewedAt] >= @Since
            GROUP BY vl.[ProductId]
        )
        SELECT TOP (@Limit)
            p.[ProductId]                                        AS [Id],
            p.[ProductName]                                      AS [Name],
            p.[SlugUrl],
            p.[MRP],
            p.[SellingPrice],
            CASE
                WHEN p.[MRP] > 0
                THEN CAST(ROUND((p.[MRP] - p.[SellingPrice]) * 100.0 / p.[MRP], 0) AS INT)
                ELSE 0
            END                                                   AS [DiscountPercent],
            b.[BrandName],
            p.[CategoryId],
            ISNULL(p.[SubCategoryId], 0)                          AS [SubCategoryId],
            pi_.[ImageUrl]                                       AS [PrimaryImage],
            0                                                     AS [OfferCount],
            ISNULL(vc.[ViewCount], 0)                             AS [TrendingScore]
        FROM [dbo].[Products]       p
        INNER JOIN [dbo].[Brands]       b   ON b.[BrandId]    = p.[BrandId]
        LEFT  JOIN [dbo].[ProductImages] pi_
                ON pi_.[ProductId] = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN ViewCounts vc
                ON vc.[ProductId] = p.[ProductId]
        WHERE p.[IsDeleted]      = 0
          AND p.[IsActive]       = 1
          AND p.[ApprovalStatus] = 2
        ORDER BY
            -- Real trending data wins; if no views yet, featured rank takes over.
            CASE WHEN vc.[ViewCount] IS NULL THEN 1 ELSE 0 END ASC,
            ISNULL(vc.[ViewCount], 0)                          DESC,
            p.[IsFeatured]                                     DESC,
            p.[PublishedAt]                                    DESC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_ListByBrand]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_ListByBrand]
    @BrandId      INT,
    @CategoryId   INT    = NULL,
    @GenderTypeId TINYINT = NULL,
    @SortBy       NVARCHAR(50) = N'Newest',
    @PageNumber   INT = 1,
    @PageSize     INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            p.[ProductId], p.[ProductName], p.[SlugUrl],
            p.[MRP], p.[SellingPrice], p.[IsFeatured],
            b.[BrandName],
            c.[CategoryName],
            gt.[Name]         AS [GenderType],
            pi_.[ImageUrl]    AS [PrimaryImageUrl],
            ISNULL(pv.[MinStock], 0) AS [MinStock],
            COUNT(*) OVER()   AS [TotalCount]
        FROM [dbo].[Products]       p
        INNER JOIN [dbo].[Brands]       b   ON b.[BrandId]       = p.[BrandId]
        INNER JOIN [dbo].[Categories]   c   ON c.[CategoryId]    = p.[CategoryId]
        LEFT  JOIN [dbo].[GenderTypes]  gt  ON gt.[GenderTypeId] = p.[GenderTypeId]
        LEFT  JOIN [dbo].[ProductImages] pi_ ON pi_.[ProductId]  = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN (
            SELECT [ProductId], MIN([StockQuantity]) AS [MinStock]
            FROM [dbo].[ProductVariants] WHERE [IsDeleted] = 0 AND [IsActive] = 1
            GROUP BY [ProductId]
        ) pv ON pv.[ProductId] = p.[ProductId]
        WHERE p.[IsDeleted]      = 0
          AND p.[IsActive]       = 1
          AND p.[ApprovalStatus] = 2
          AND p.[BrandId]        = @BrandId
          AND (p.[CategoryId]    = @CategoryId   OR @CategoryId   IS NULL)
          AND (p.[GenderTypeId]  = @GenderTypeId OR @GenderTypeId IS NULL)
        ORDER BY
            CASE WHEN @SortBy = N'PriceLow'  THEN p.[SellingPrice] END ASC,
            CASE WHEN @SortBy = N'PriceHigh' THEN p.[SellingPrice] END DESC,
            CASE WHEN @SortBy = N'Newest'    THEN p.[PublishedAt]  END DESC,
            p.[SortOrder] ASC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_ListByCategory]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_ListByCategory]
    @CategoryId    INT,
    @SubCategoryId INT    = NULL,
    @BrandId       INT    = NULL,
    @GenderTypeId  TINYINT = NULL,
    @MinPrice      DECIMAL(18,2) = NULL,
    @MaxPrice      DECIMAL(18,2) = NULL,
    @SortBy        NVARCHAR(50)  = N'Newest',
    @PageNumber    INT = 1,
    @PageSize      INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            p.[ProductId], p.[ProductName], p.[SlugUrl],
            p.[MRP], p.[SellingPrice], p.[IsFeatured],
            b.[BrandId], b.[BrandName],
            c.[CategoryName],
            sc.[SubCategoryName],
            gt.[Name]           AS [GenderType],
            pi_.[ImageUrl]      AS [PrimaryImageUrl],
            ISNULL(pv.[MinStock], 0) AS [MinStock],
            COUNT(*) OVER()     AS [TotalCount]
        FROM [dbo].[Products]         p
        INNER JOIN [dbo].[Brands]         b   ON b.[BrandId]       = p.[BrandId]
        INNER JOIN [dbo].[Categories]     c   ON c.[CategoryId]    = p.[CategoryId]
        LEFT  JOIN [dbo].[SubCategories]  sc  ON sc.[SubCategoryId] = p.[SubCategoryId]
        LEFT  JOIN [dbo].[GenderTypes]    gt  ON gt.[GenderTypeId]  = p.[GenderTypeId]
        LEFT  JOIN [dbo].[ProductImages]  pi_ ON pi_.[ProductId]    = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN (
            SELECT [ProductId], MIN([StockQuantity]) AS [MinStock]
            FROM [dbo].[ProductVariants] WHERE [IsDeleted] = 0 AND [IsActive] = 1
            GROUP BY [ProductId]
        ) pv ON pv.[ProductId] = p.[ProductId]
        WHERE p.[IsDeleted]      = 0
          AND p.[IsActive]       = 1
          AND p.[ApprovalStatus] = 2
          AND p.[CategoryId]     = @CategoryId
          AND (p.[SubCategoryId] = @SubCategoryId OR @SubCategoryId IS NULL)
          AND (p.[BrandId]       = @BrandId       OR @BrandId       IS NULL)
          AND (p.[GenderTypeId]  = @GenderTypeId  OR @GenderTypeId  IS NULL)
          AND (p.[SellingPrice]  >= @MinPrice      OR @MinPrice      IS NULL)
          AND (p.[SellingPrice]  <= @MaxPrice      OR @MaxPrice      IS NULL)
        ORDER BY
            CASE WHEN @SortBy = N'PriceLow'  THEN p.[SellingPrice] END ASC,
            CASE WHEN @SortBy = N'PriceHigh' THEN p.[SellingPrice] END DESC,
            CASE WHEN @SortBy = N'Newest'    THEN p.[PublishedAt]  END DESC,
            p.[SortOrder] ASC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Catalog_Product_Search]...';


GO
CREATE PROCEDURE [dbo].[usp_Catalog_Product_Search]
    @SearchTerm    NVARCHAR(500),
    @CategoryId    INT    = NULL,
    @SubCategoryId INT    = NULL,
    @MenuId        INT    = NULL,
    @BrandId       INT    = NULL,
    @BrandIds      NVARCHAR(500) = NULL,
    @Sizes         NVARCHAR(500) = NULL,
    @Colors        NVARCHAR(500) = NULL,
    @GenderTypeId  TINYINT = NULL,
    @MinPrice      DECIMAL(18,2) = NULL,
    @MaxPrice      DECIMAL(18,2) = NULL,
    @SortBy        NVARCHAR(50)  = N'Relevance',  -- Relevance | PriceLow | PriceHigh | Newest
    @PageNumber    INT  = 1,
    @PageSize      INT  = 20,
    @CallerUserId  INT  = NULL,
    @DatePosted    NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
        DECLARE @SearchPattern NVARCHAR(502) = CASE WHEN @SearchTerm <> N'' THEN N'%' + @SearchTerm + N'%' ELSE N'%' END;

        -- Log search for analytics
        IF @SearchTerm <> N''
            INSERT INTO [dbo].[SearchLogs] ([UserId], [SearchTerm], [ResultCount], [SearchedAt])
            VALUES (@CallerUserId, @SearchTerm, 0, GETUTCDATE());

        DECLARE @SearchLogId BIGINT = SCOPE_IDENTITY();

        DECLARE @BrandIdTbl TABLE (Id INT PRIMARY KEY);
        IF @BrandIds IS NOT NULL AND LEN(@BrandIds) > 0
            INSERT INTO @BrandIdTbl(Id)
            SELECT TRY_CAST(value AS INT) FROM STRING_SPLIT(@BrandIds, ',') WHERE TRY_CAST(value AS INT) IS NOT NULL;

        DECLARE @SizeTbl TABLE (Val NVARCHAR(50));
        IF @Sizes IS NOT NULL AND LEN(@Sizes) > 0
            INSERT INTO @SizeTbl(Val) SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Sizes, ',') WHERE LTRIM(RTRIM(value)) <> N'';

        DECLARE @ColorTbl TABLE (Val NVARCHAR(50));
        IF @Colors IS NOT NULL AND LEN(@Colors) > 0
            INSERT INTO @ColorTbl(Val) SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Colors, ',') WHERE LTRIM(RTRIM(value)) <> N'';

        DECLARE @HasBrandFilter BIT = CASE WHEN EXISTS (SELECT 1 FROM @BrandIdTbl) THEN 1 ELSE 0 END;
        DECLARE @HasSizeFilter  BIT = CASE WHEN EXISTS (SELECT 1 FROM @SizeTbl)    THEN 1 ELSE 0 END;
        DECLARE @HasColorFilter BIT = CASE WHEN EXISTS (SELECT 1 FROM @ColorTbl)   THEN 1 ELSE 0 END;

        -- LIKE-based search (no full-text index required)
        SELECT
            p.[ProductId]           AS [Id],
            p.[ProductName]         AS [Name],
            p.[SlugUrl],
            p.[CategoryId],
            p.[SubCategoryId],
            p.[SellerId],
            p.[MRP],
            p.[SellingPrice],
            CAST(CASE WHEN p.[MRP] > 0 THEN (p.[MRP] - p.[SellingPrice]) * 100.0 / p.[MRP] ELSE 0 END AS DECIMAL(5,1)) AS [DiscountPct],
            p.[GstRate],
            b.[BrandName],
            c.[CategoryName],
            sc.[SubCategoryName],
            pi_.[ImageUrl]           AS [PrimaryImage],
            ISNULL(pv.[MinStock], 0) AS [MinStock],
            COUNT(*) OVER()          AS [TotalCount]
        FROM [dbo].[Products]       p
        INNER JOIN [dbo].[Brands]         b   ON b.[BrandId]       = p.[BrandId]
        INNER JOIN [dbo].[Categories]     c   ON c.[CategoryId]    = p.[CategoryId]
        LEFT  JOIN [dbo].[SubCategories]  sc  ON sc.[SubCategoryId] = p.[SubCategoryId]
        LEFT  JOIN [dbo].[ProductImages]  pi_ ON pi_.[ProductId]   = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN (
            SELECT [ProductId], MIN([StockQuantity]) AS [MinStock]
            FROM [dbo].[ProductVariants] WHERE [IsDeleted] = 0 AND [IsActive] = 1
            GROUP BY [ProductId]
        ) pv ON pv.[ProductId] = p.[ProductId]
        WHERE p.[IsDeleted]      = 0
          AND p.[IsActive]       = 1
          AND p.[ApprovalStatus] = 2
          AND (p.[CategoryId]    = @CategoryId    OR @CategoryId    IS NULL)
          AND (p.[SubCategoryId] = @SubCategoryId OR @SubCategoryId IS NULL)
          AND (c.[MenuId]        = @MenuId        OR @MenuId        IS NULL)
          AND (p.[BrandId]       = @BrandId      OR @BrandId      IS NULL)
          AND (@HasBrandFilter = 0 OR p.[BrandId] IN (SELECT Id FROM @BrandIdTbl))
          AND (p.[GenderTypeId]  = @GenderTypeId OR @GenderTypeId IS NULL)
          AND (p.[SellingPrice]  >= @MinPrice     OR @MinPrice     IS NULL)
          AND (p.[SellingPrice]  <= @MaxPrice     OR @MaxPrice     IS NULL)
          AND (p.[ProductName] LIKE @SearchPattern OR p.[ShortDescription] LIKE @SearchPattern OR p.[Tags] LIKE @SearchPattern OR @SearchTerm = N'')
          AND (@HasSizeFilter  = 0 OR EXISTS (SELECT 1 FROM [dbo].[ProductVariants] v WHERE v.[ProductId] = p.[ProductId] AND v.[IsDeleted] = 0 AND v.[Size]  IN (SELECT Val FROM @SizeTbl)))
          AND (@HasColorFilter = 0 OR EXISTS (SELECT 1 FROM [dbo].[ProductVariants] v WHERE v.[ProductId] = p.[ProductId] AND v.[IsDeleted] = 0 AND v.[Color] IN (SELECT Val FROM @ColorTbl)))
          AND (
              @DatePosted IS NULL
              OR (@DatePosted = N'today'      AND CAST(p.[CreatedAt] AS DATE) = CAST(GETUTCDATE() AS DATE))
              OR (@DatePosted = N'this_week'  AND p.[CreatedAt] >= DATEADD(DAY, -6, CAST(GETUTCDATE() AS DATE)))
              OR (@DatePosted = N'this_month' AND p.[CreatedAt] >= DATEFROMPARTS(YEAR(GETUTCDATE()), MONTH(GETUTCDATE()), 1))
              OR (@DatePosted = N'last_month' AND p.[CreatedAt] >= DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,GETUTCDATE())), MONTH(DATEADD(MONTH,-1,GETUTCDATE())), 1)
                                              AND p.[CreatedAt] <  DATEFROMPARTS(YEAR(GETUTCDATE()), MONTH(GETUTCDATE()), 1))
              OR (@DatePosted = N'older'      AND p.[CreatedAt] <  DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,GETUTCDATE())), MONTH(DATEADD(MONTH,-1,GETUTCDATE())), 1))
          )
        ORDER BY
            CASE WHEN @SortBy = N'PriceLow'  THEN p.[SellingPrice] END ASC,
            CASE WHEN @SortBy = N'PriceHigh' THEN p.[SellingPrice] END DESC,
            -- Default + LATEST/POPULAR: surface recently-modified products first
            CASE WHEN @SortBy IN (N'Newest', N'LATEST', N'POPULAR') THEN COALESCE(p.[UpdatedAt], p.[CreatedAt]) END DESC,
            COALESCE(p.[UpdatedAt], p.[CreatedAt]) DESC,
            p.[ProductId] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

        -- Update result count in search log
        IF @SearchLogId > 0
            UPDATE [dbo].[SearchLogs] SET [ResultCount] = @@ROWCOUNT WHERE [SearchId] = @SearchLogId;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
