            sc.[SizeScale],
            sc.[RequiresGender],
            sc.[RequiresDimensions]
        FROM [dbo].[SubCategories] sc
        WHERE sc.[SubCategoryId] = @SubCategoryId
          AND sc.[IsDeleted]     = 0;
    END TRY
    BEGIN CATCH
