PRINT N'Creating Procedure [dbo].[usp_Commerce_Cart_UpdateQuantity]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Cart_UpdateQuantity]
    @CartId   INT,
    @UserId   INT,
    @Quantity INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Quantity < 1
            THROW 50043, N'Quantity must be at least 1.', 1;

        DECLARE @VariantId INT;
        SELECT @VariantId = [VariantId]
        FROM [dbo].[Cart]
        WHERE [CartId] = @CartId AND [UserId] = @UserId AND [IsDeleted] = 0;

        IF @VariantId IS NULL
            THROW 50044, N'Cart item not found.', 1;

        DECLARE @Stock INT;
        SELECT @Stock = [StockQuantity] FROM [dbo].[ProductVariants] WHERE [VariantId] = @VariantId;

        IF @Stock < @Quantity
            THROW 50045, N'Insufficient stock.', 1;

        UPDATE [dbo].[Cart]
        SET    [Quantity]  = @Quantity,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @UserId
        WHERE  [CartId] = @CartId;

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Coupon_Validate]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Coupon_Validate]
    @CouponCode   NVARCHAR(50),
    @UserId       INT,
    @OrderSubTotal DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @OfferId          INT;
        DECLARE @OfferType        TINYINT;
        DECLARE @DiscountValue    DECIMAL(18,2);
        DECLARE @MinOrderValue    DECIMAL(18,2);
        DECLARE @MaxDiscountCap   DECIMAL(18,2);
        DECLARE @UsageLimitPerUser TINYINT;
        DECLARE @CouponId         INT;

        SELECT
            @CouponId          = cp.[CouponId],
            @OfferId           = o.[OfferId],
            @OfferType         = o.[OfferType],
            @DiscountValue     = o.[DiscountValue],
            @MinOrderValue     = o.[MinOrderValue],
            @MaxDiscountCap    = o.[MaxDiscountCap],
            @UsageLimitPerUser = o.[UsageLimitPerUser]
        FROM [dbo].[Coupons] cp
        INNER JOIN [dbo].[Offers] o ON o.[OfferId] = cp.[OfferId]
        WHERE cp.[CouponCode] = @CouponCode
          AND cp.[IsDeleted]  = 0
          AND cp.[IsActive]   = 1
          AND o.[IsDeleted]   = 0
          AND o.[IsActive]    = 1
          AND o.[StartDate]   <= GETUTCDATE()
          AND o.[EndDate]     >= GETUTCDATE()
          AND (o.[UsageLimitTotal] IS NULL OR o.[CurrentUsageCount] < o.[UsageLimitTotal]);

        IF @CouponId IS NULL
            THROW 50063, N'Invalid or expired coupon code.', 1;

        IF @OrderSubTotal < @MinOrderValue
            THROW 50064, N'Order does not meet the minimum value required for this coupon.', 1;

        DECLARE @UserUsage INT = (
            SELECT COUNT(*) FROM [dbo].[Orders]
            WHERE [UserId] = @UserId AND [CouponId] = @CouponId AND [IsDeleted] = 0
        );
        IF @UserUsage >= @UsageLimitPerUser
            THROW 50065, N'You have already used this coupon the maximum number of times.', 1;

        DECLARE @DiscountAmount DECIMAL(18,2) =
            @OrderSubTotal - [dbo].[fn_CalculateDiscountedPrice](@OrderSubTotal, @OfferType, @DiscountValue, @MaxDiscountCap);

        SELECT
            @CouponId       AS [CouponId],
            @CouponCode     AS [CouponCode],
            @DiscountAmount AS [DiscountAmount],
            @OfferType      AS [OfferType],
            1               AS [IsValid];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Order_Cancel]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Order_Cancel]
    @OrderId            INT,
    @UserId             INT,
    @CancellationReason NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @CurrentStatus TINYINT;
        SELECT @CurrentStatus = [OrderStatus]
        FROM [dbo].[Orders]
        WHERE [OrderId] = @OrderId AND [UserId] = @UserId AND [IsDeleted] = 0;

        IF @CurrentStatus IS NULL
            THROW 50070, N'Order not found.', 1;

        -- Can only cancel Pending or Confirmed orders
        IF @CurrentStatus NOT IN (1, 2)
            THROW 50071, N'Order cannot be cancelled at this stage.', 1;

        BEGIN TRANSACTION;

            UPDATE [dbo].[Orders]
            SET    [OrderStatus]        = 6,   -- Cancelled
                   [CancelledAt]        = GETUTCDATE(),
                   [CancellationReason] = @CancellationReason,
                   [UpdatedAt]          = GETUTCDATE(),
                   [UpdatedBy]          = @UserId
            WHERE  [OrderId] = @OrderId;

            -- Restore stock
            UPDATE pv
            SET    pv.[StockQuantity] = pv.[StockQuantity] + oi.[Quantity],
                   pv.[UpdatedAt]     = GETUTCDATE(),
                   pv.[UpdatedBy]     = @UserId
            FROM [dbo].[ProductVariants] pv
            INNER JOIN [dbo].[OrderItems] oi ON oi.[VariantId] = pv.[VariantId] AND oi.[OrderId] = @OrderId AND oi.[IsDeleted] = 0;

            -- Notification
            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@UserId,
                 N'Order Cancelled',
                 N'Your order has been cancelled.',
                 1, N'Order', @OrderId, 1);

            -- Tracking timeline.
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [Status], [Note], [ChangedBy])
            VALUES (@OrderId, N'CANCELLED',
                    COALESCE(N'Order cancelled by buyer. Reason: ' + @CancellationReason,
                             N'Order cancelled by buyer.'),
                    @UserId);

        COMMIT TRANSACTION;

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Order_GetById]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Order_GetById]
    @OrderId INT,
    @UserId  INT = NULL    -- NULL = admin lookup (no user restriction)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT
            o.[OrderId], o.[OrderNumber], o.[OrderStatus],
            o.[SubTotal], o.[DiscountAmount], o.[CouponDiscount],
            o.[TaxAmount], o.[ShippingCharge], o.[TotalAmount],
            o.[PaymentMode], o.[PaymentStatus], o.[PaymentGatewayRef],
            o.[ExpectedDeliveryDate], o.[DeliveredAt], o.[CancelledAt],
            o.[CancellationReason], o.[CreatedAt] AS [OrderDate],
            -- Address
            ua.[Label]        AS [AddressLabel],
            ua.[AddressLine1], ua.[AddressLine2],
            ua.[City], ua.[State], ua.[PinCode], ua.[Country],
            -- Coupon
            cp.[CouponCode]
        FROM [dbo].[Orders]        o
        INNER JOIN [dbo].[UserAddresses] ua ON ua.[AddressId] = o.[ShippingAddressId]
        LEFT  JOIN [dbo].[Coupons]       cp ON cp.[CouponId]  = o.[CouponId]
        WHERE o.[OrderId]  = @OrderId
          AND o.[IsDeleted] = 0
          AND (@UserId IS NULL OR o.[UserId] = @UserId);

        -- Return order items (incl. per-line fulfilment state)
        SELECT
            oi.[OrderItemId], oi.[ProductId], oi.[VariantId],
            oi.[ProductName], oi.[VariantSnapshot],
            oi.[Quantity], oi.[UnitPrice], oi.[DiscountAmount],
            oi.[TaxAmount], oi.[TotalPrice],
            oi.[CommissionAmount], oi.[SellerEarning],
            oi.[IsReturned], oi.[ReturnReason],
            oi.[OrderStatus]      AS [LineStatus],
            oi.[ConfirmedAt],
            oi.[RejectedAt],
            oi.[RejectionReason],
            b.[BrandName],
            s.[BusinessName] AS [SellerName],
            pi_.[ImageUrl]   AS [ProductImageUrl]
        FROM [dbo].[OrderItems]       oi
        INNER JOIN [dbo].[Brands]         b   ON b.[BrandId]   = oi.[BrandId]
        INNER JOIN [dbo].[Sellers]        s   ON s.[SellerId]  = oi.[SellerId]
        LEFT  JOIN [dbo].[ProductImages]  pi_ ON pi_.[ProductId] = oi.[ProductId]
                                              AND pi_.[IsPrimary] = 1
                                              AND pi_.[IsDeleted] = 0
        WHERE oi.[OrderId]  = @OrderId
          AND oi.[IsDeleted] = 0;

        -- Tracking timeline (append-only). Ordered ascending so the buyer UI
        -- can render the strip left-to-right without re-sorting.
        SELECT
            t.[TrackingId],
            t.[OrderId],
            t.[OrderItemId],
            t.[Status],
            t.[Note],
            t.[ChangedAt],
            t.[ChangedBy]
        FROM [dbo].[OrderTrackings] t
        WHERE t.[OrderId] = @OrderId
        ORDER BY t.[ChangedAt] ASC, t.[TrackingId] ASC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Order_GetByUser]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Order_GetByUser]
    @UserId     INT,
    @OrderStatus TINYINT = NULL,
    @PageNumber INT = 1,
    @PageSize   INT = 10
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            o.[OrderId],
            o.[OrderNumber],
            o.[OrderStatus],
            o.[TotalAmount],
            o.[PaymentMode],
            o.[PaymentStatus],
            o.[ExpectedDeliveryDate],
            o.[DeliveredAt],
            o.[CreatedAt]     AS [OrderDate],
            COUNT(*) OVER()   AS [TotalCount],
            -- Item count and primary image from first item
            oi.[ItemCount],
            oi.[FirstProductName],
            oi.[FirstProductImage]
        FROM [dbo].[Orders] o
        OUTER APPLY (
            SELECT
                COUNT(*)                       AS [ItemCount],
                MAX(x.[ProductName])           AS [FirstProductName],
                MAX(x.[ImageUrl])              AS [FirstProductImage]
            FROM (
                SELECT TOP 1
                    oi2.[ProductName],
                    pi_.[ImageUrl]
                FROM [dbo].[OrderItems] oi2
                LEFT JOIN [dbo].[ProductImages] pi_ ON pi_.[ProductId] = oi2.[ProductId]
                                                    AND pi_.[IsPrimary] = 1
                                                    AND pi_.[IsDeleted] = 0
                WHERE oi2.[OrderId]  = o.[OrderId]
                  AND oi2.[IsDeleted] = 0
                ORDER BY oi2.[OrderItemId]
            ) x,
            (SELECT COUNT(*) AS [ItemCount]
             FROM [dbo].[OrderItems] WHERE [OrderId] = o.[OrderId] AND [IsDeleted] = 0) cnt
        ) oi
        WHERE o.[UserId]     = @UserId
          AND o.[IsDeleted]  = 0
          AND (@OrderStatus IS NULL OR o.[OrderStatus] = @OrderStatus)
        ORDER BY o.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Order_Place]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Order_Place]
    @UserId            INT,
    @ShippingAddressId INT,
    @PaymentMode       TINYINT,      -- 1=COD, 2=Online, 3=Wallet
    @CouponCode        NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Validate address belongs to user
        IF NOT EXISTS (SELECT 1 FROM [dbo].[UserAddresses] WHERE [AddressId] = @ShippingAddressId AND [UserId] = @UserId AND [IsDeleted] = 0)
            THROW 50060, N'Shipping address not found.', 1;

        -- Load active cart into temp table
        CREATE TABLE #CartItems
        (
            CartId     INT, ProductId INT, VariantId INT, SellerId INT, BrandId INT,
            Quantity   INT, UnitPrice DECIMAL(18,2), AdditionalPrice DECIMAL(18,2),
            FinalPrice DECIMAL(18,2), GstRate DECIMAL(5,2),
            ProductName NVARCHAR(300), VariantSku NVARCHAR(150),
            Color NVARCHAR(100), Size NVARCHAR(50), CommissionRate DECIMAL(5,2)
        );

        INSERT INTO #CartItems
        SELECT
            c.[CartId],
            p.[ProductId],
            pv.[VariantId],
            p.[SellerId],
            p.[BrandId],
            c.[Quantity],
            p.[SellingPrice],
            pv.[AdditionalPrice],
            (p.[SellingPrice] + pv.[AdditionalPrice]) AS [FinalPrice],
            p.[GstRate],
            p.[ProductName],
            pv.[VariantSku],
            pv.[Color],
            pv.[Size],
            s.[CommissionRate]
        FROM [dbo].[Cart]              c
        INNER JOIN [dbo].[Products]        p   ON p.[ProductId]  = c.[ProductId]
        INNER JOIN [dbo].[ProductVariants] pv  ON pv.[VariantId] = c.[VariantId]
        INNER JOIN [dbo].[Sellers]         s   ON s.[SellerId]   = p.[SellerId]
        WHERE c.[UserId]       = @UserId
          AND c.[IsDeleted]    = 0
          AND c.[SavedForLater] = 0
          AND p.[IsDeleted]    = 0
          AND p.[IsActive]     = 1
          AND p.[ApprovalStatus] = 2
          AND pv.[IsDeleted]   = 0
          AND pv.[IsActive]    = 1;

        IF NOT EXISTS (SELECT 1 FROM #CartItems)
            THROW 50061, N'Cart is empty or contains no available items.', 1;

        -- Validate stock (row-level lock to prevent overselling)
        IF EXISTS (
            SELECT 1 FROM #CartItems ci
            INNER JOIN [dbo].[ProductVariants] pv WITH (UPDLOCK, ROWLOCK)
                ON pv.[VariantId] = ci.[VariantId]
            WHERE pv.[StockQuantity] < ci.[Quantity]
        )
            THROW 50062, N'One or more items are out of stock.', 1;

        -- Calculate totals
        DECLARE @SubTotal        DECIMAL(18,2) = (SELECT SUM([FinalPrice] * [Quantity]) FROM #CartItems);
        DECLARE @TaxAmount       DECIMAL(18,2) = (SELECT SUM(([FinalPrice] * [Quantity]) * [GstRate] / 100) FROM #CartItems);
        DECLARE @ShippingCharge  DECIMAL(18,2) = CASE WHEN @SubTotal >= 499 THEN 0 ELSE 49 END;
        DECLARE @DiscountAmount  DECIMAL(18,2) = 0;
        DECLARE @CouponDiscount  DECIMAL(18,2) = 0;
        DECLARE @ResolvedCouponId INT          = NULL;

        -- Apply coupon if provided
        IF @CouponCode IS NOT NULL
        BEGIN
            DECLARE @OfferId          INT;
            DECLARE @OfferType        TINYINT;
            DECLARE @DiscountValue    DECIMAL(18,2);
            DECLARE @MinOrderValue    DECIMAL(18,2);
            DECLARE @MaxDiscountCap   DECIMAL(18,2);
            DECLARE @UsageLimitPerUser TINYINT;
            DECLARE @UsageLimitTotal  INT;
            DECLARE @CurrentUsage     INT;

            SELECT
                @ResolvedCouponId  = cp.[CouponId],
                @OfferId           = o.[OfferId],
                @OfferType         = o.[OfferType],
                @DiscountValue     = o.[DiscountValue],
                @MinOrderValue     = o.[MinOrderValue],
                @MaxDiscountCap    = o.[MaxDiscountCap],
                @UsageLimitPerUser = o.[UsageLimitPerUser],
                @UsageLimitTotal   = o.[UsageLimitTotal],
                @CurrentUsage      = o.[CurrentUsageCount]
            FROM [dbo].[Coupons] cp
            INNER JOIN [dbo].[Offers] o ON o.[OfferId] = cp.[OfferId]
            WHERE cp.[CouponCode] = @CouponCode
              AND cp.[IsDeleted]  = 0
              AND cp.[IsActive]   = 1
              AND o.[IsDeleted]   = 0
              AND o.[IsActive]    = 1
              AND o.[StartDate]   <= GETUTCDATE()
              AND o.[EndDate]     >= GETUTCDATE()
              AND (o.[UsageLimitTotal] IS NULL OR o.[CurrentUsageCount] < o.[UsageLimitTotal]);

            IF @ResolvedCouponId IS NULL
                THROW 50063, N'Invalid or expired coupon code.', 1;

            IF @SubTotal < @MinOrderValue
                THROW 50064, N'Order does not meet minimum value for this coupon.', 1;

            -- Check per-user usage
            DECLARE @UserCouponUsage INT = (
                SELECT COUNT(*) FROM [dbo].[Orders]
                WHERE [UserId] = @UserId AND [CouponId] = @ResolvedCouponId AND [IsDeleted] = 0
            );
            IF @UserCouponUsage >= @UsageLimitPerUser
                THROW 50065, N'You have already used this coupon the maximum number of times.', 1;

            -- Calculate coupon discount
            SET @CouponDiscount = [dbo].[fn_CalculateDiscountedPrice](@SubTotal, @OfferType, @DiscountValue, @MaxDiscountCap);
            SET @CouponDiscount = @SubTotal - @CouponDiscount;
        END;

        DECLARE @TotalAmount DECIMAL(18,2) = @SubTotal - @DiscountAmount - @CouponDiscount + @TaxAmount + @ShippingCharge;

        -- Generate order number
        DECLARE @NewOrderId     INT;
        DECLARE @NewOrderNumber NVARCHAR(50);

        BEGIN TRANSACTION;

            -- Insert order
            INSERT INTO [dbo].[Orders]
                ([UserId], [OrderNumber], [OrderStatus], [SubTotal], [DiscountAmount],
                 [CouponId], [CouponDiscount], [TaxAmount], [ShippingCharge], [TotalAmount],
                 [ShippingAddressId], [PaymentMode], [PaymentStatus], [CreatedBy], [UpdatedBy])
            VALUES
                (@UserId, N'PENDING', 1, @SubTotal, @DiscountAmount,
                 @ResolvedCouponId, @CouponDiscount, @TaxAmount, @ShippingCharge, @TotalAmount,
                 @ShippingAddressId, @PaymentMode, 1, @UserId, @UserId);

            SET @NewOrderId = SCOPE_IDENTITY();

            -- Set proper order number (SNS-YYYYMMDD-NNNNN)
            SET @NewOrderNumber = [dbo].[fn_GenerateOrderNumber](@NewOrderId);
            UPDATE [dbo].[Orders] SET [OrderNumber] = @NewOrderNumber WHERE [OrderId] = @NewOrderId;

            -- Open the order's tracking timeline.
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [Status], [Note], [ChangedBy])
            VALUES (@NewOrderId, N'PLACED', N'Order placed by buyer.', @UserId);

            -- Insert order items
            INSERT INTO [dbo].[OrderItems]
                ([OrderId], [ProductId], [VariantId], [SellerId], [BrandId],
                 [ProductName], [VariantSnapshot], [Quantity], [UnitPrice],
                 [TaxAmount], [TotalPrice],
                 [SellerCommissionRate], [CommissionAmount], [SellerEarning],
                 [CreatedBy], [UpdatedBy])
            SELECT
                @NewOrderId,
                ci.[ProductId],
                ci.[VariantId],
                ci.[SellerId],
                ci.[BrandId],
                ci.[ProductName],
                ci.[VariantSku] + ISNULL(N' | ' + ci.[Color], N'') + ISNULL(N' | ' + ci.[Size], N''),
                ci.[Quantity],
                ci.[FinalPrice],
                (ci.[FinalPrice] * ci.[Quantity]) * ci.[GstRate] / 100,
                ci.[FinalPrice] * ci.[Quantity],
                ci.[CommissionRate],
                ROUND(ci.[FinalPrice] * ci.[Quantity] * ci.[CommissionRate] / 100, 2),
                ROUND(ci.[FinalPrice] * ci.[Quantity] - (ci.[FinalPrice] * ci.[Quantity] * ci.[CommissionRate] / 100), 2),
                @UserId,
                @UserId
            FROM #CartItems ci;

            -- Deduct stock
            UPDATE pv
            SET    pv.[StockQuantity] = pv.[StockQuantity] - ci.[Quantity],
                   pv.[UpdatedAt]     = GETUTCDATE(),
                   pv.[UpdatedBy]     = @UserId
            FROM [dbo].[ProductVariants] pv
            INNER JOIN #CartItems ci ON ci.[VariantId] = pv.[VariantId];

            -- Clear cart
            UPDATE [dbo].[Cart]
            SET    [IsDeleted] = 1, [UpdatedAt] = GETUTCDATE(), [UpdatedBy] = @UserId
            WHERE  [UserId] = @UserId AND [IsDeleted] = 0 AND [SavedForLater] = 0;

            -- Increment coupon usage count
            IF @ResolvedCouponId IS NOT NULL
                UPDATE [dbo].[Offers]
                SET    [CurrentUsageCount] = [CurrentUsageCount] + 1
                WHERE  [OfferId] = @OfferId;

            -- Create in-app notification
            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@UserId,
                 N'Order Placed Successfully',
                 N'Your order ' + @NewOrderNumber + N' has been placed. Total: ₹' + CAST(@TotalAmount AS NVARCHAR(20)),
                 1, N'Order', @NewOrderId, 1);

            -- Record an informational ledger entry so the order shows up in the
            -- buyer's wallet transaction history. Wallet balance is only actually
            -- deducted when PaymentMode = 3 (Wallet).
            DECLARE @WalletId INT;
            SELECT @WalletId = [WalletId] FROM [dbo].[Wallets] WHERE [UserId] = @UserId;
            IF @WalletId IS NULL
            BEGIN
                INSERT INTO [dbo].[Wallets] ([UserId], [Balance]) VALUES (@UserId, 0);
                SET @WalletId = SCOPE_IDENTITY();
            END

            DECLARE @PaymentLabel NVARCHAR(20) =
                CASE @PaymentMode
                     WHEN 1 THEN N'COD'
                     WHEN 2 THEN N'Online'
                     WHEN 3 THEN N'Wallet'
                     ELSE N'Other'
                END;

            INSERT INTO [dbo].[WalletTransactions]
                ([WalletId], [UserId], [Amount], [TransactionType],
                 [ReferenceType], [ReferenceId], [Description], [CreatedAt])
            VALUES
                (@WalletId, @UserId, @TotalAmount, 2,    -- 2 = Debit
                 N'Order', @NewOrderId,
                 N'Order ' + @NewOrderNumber + N' (' + @PaymentLabel + N')',
                 GETUTCDATE());

            -- Only actually deduct the wallet balance for wallet-pay orders.
            IF @PaymentMode = 3
                UPDATE [dbo].[Wallets]
                SET [Balance]   = [Balance] - @TotalAmount,
                    [UpdatedAt] = GETUTCDATE()
                WHERE [WalletId] = @WalletId;

        COMMIT TRANSACTION;

        DROP TABLE #CartItems;

        SELECT
            o.[OrderId],
            o.[OrderNumber],
            o.[OrderStatus],
            o.[TotalAmount],
            o.[PaymentMode],
            o.[PaymentStatus],
            o.[CreatedAt] AS [OrderDate]
        FROM [dbo].[Orders] o
        WHERE o.[OrderId] = @NewOrderId;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF OBJECT_ID('tempdb..#CartItems') IS NOT NULL DROP TABLE #CartItems;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Wishlist_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Wishlist_Add]
    @UserId    INT,
    @ProductId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [ProductId] = @ProductId AND [IsDeleted] = 0 AND [IsActive] = 1)
            THROW 50050, N'Product not found.', 1;

        IF EXISTS (SELECT 1 FROM [dbo].[Wishlist] WHERE [UserId] = @UserId AND [ProductId] = @ProductId AND [IsDeleted] = 0)
        BEGIN
            SELECT 1 AS [Success], N'Already in wishlist' AS [Message];
            RETURN;
        END;

        INSERT INTO [dbo].[Wishlist]
            ([UserId], [ProductId], [CreatedBy], [UpdatedBy])
        VALUES
            (@UserId, @ProductId, @UserId, @UserId);

        SELECT 1 AS [Success], N'Added to wishlist' AS [Message];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Wishlist_GetByUser]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Wishlist_GetByUser]
    @UserId     INT,
    @PageNumber INT = 1,
    @PageSize   INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            w.[WishlistId],
            w.[AddedAt],
            p.[ProductId],
            p.[ProductName],
            p.[SlugUrl],
            p.[MRP],
            p.[SellingPrice],
            p.[IsActive]       AS [ProductIsActive],
            b.[BrandName],
            pi_.[ImageUrl]     AS [PrimaryImageUrl],
            ISNULL(pv.[MinStock], 0) AS [MinStock],
            COUNT(*) OVER()    AS [TotalCount]
        FROM [dbo].[Wishlist]          w
        INNER JOIN [dbo].[Products]        p   ON p.[ProductId]  = w.[ProductId] AND p.[IsDeleted]  = 0
        INNER JOIN [dbo].[Brands]          b   ON b.[BrandId]    = p.[BrandId]   AND b.[IsDeleted]  = 0
        LEFT  JOIN [dbo].[ProductImages]   pi_ ON pi_.[ProductId] = p.[ProductId] AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN (
            SELECT [ProductId], MIN([StockQuantity]) AS [MinStock]
            FROM [dbo].[ProductVariants] WHERE [IsDeleted] = 0 AND [IsActive] = 1
            GROUP BY [ProductId]
        ) pv ON pv.[ProductId] = p.[ProductId]
        WHERE w.[UserId]    = @UserId
          AND w.[IsDeleted] = 0
        ORDER BY w.[AddedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Commerce_Wishlist_Remove]...';


GO
CREATE PROCEDURE [dbo].[usp_Commerce_Wishlist_Remove]
    @UserId    INT,
    @ProductId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        UPDATE [dbo].[Wishlist]
        SET    [IsDeleted] = 1,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @UserId
        WHERE  [UserId]    = @UserId
          AND  [ProductId] = @ProductId
          AND  [IsDeleted] = 0;

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Complaint_Create]...';


GO
CREATE PROCEDURE [dbo].[usp_Complaint_Create]
    @UserId    INT,
    @OrderId   INT            = NULL,
    @Category  NVARCHAR(50),
    @Subject   NVARCHAR(300),
    @Body      NVARCHAR(MAX),
    @Source    NVARCHAR(20)   = N'aria'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF LEN(LTRIM(RTRIM(@Subject))) < 3
            THROW 50400, N'Subject must be at least 3 characters.', 1;
        IF LEN(LTRIM(RTRIM(@Body))) < 10
            THROW 50401, N'Please describe the issue (at least 10 characters).', 1;

        -- Defensive: clamp category to the allowed set; coerce unknowns to 'other'.
        DECLARE @Cat NVARCHAR(50) =
            CASE LOWER(LTRIM(RTRIM(@Category)))
                WHEN N'delivery' THEN N'delivery'
                WHEN N'product'  THEN N'product'
                WHEN N'payment'  THEN N'payment'
                WHEN N'account'  THEN N'account'
                ELSE                 N'other'
            END;

        INSERT INTO [dbo].[Complaints]
            ([UserId], [OrderId], [Category], [Subject], [Body], [Source])
        VALUES
            (@UserId, @OrderId, @Cat, @Subject, @Body, @Source);

        DECLARE @NewId INT = SCOPE_IDENTITY();

        -- Notify the buyer so they can find the ticket later.
        INSERT INTO [dbo].[Notifications]
            ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
        VALUES
            (@UserId,
             N'Complaint received',
             N'We logged your complaint (#' + CAST(@NewId AS NVARCHAR(20)) + N'). Our team will review it shortly.',
             4, N'Complaint', @NewId, 1);

        SELECT @NewId AS [ComplaintId];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Complaint_GetByUser]...';


GO
CREATE PROCEDURE [dbo].[usp_Complaint_GetByUser]
    @UserId    INT,
    @Page      INT = 1,
    @PageSize  INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@Page - 1) * @PageSize;

        SELECT
            c.[ComplaintId],
            c.[OrderId],
            o.[OrderNumber],
            c.[Category],
            c.[Subject],
            c.[Body],
            c.[Status],
            c.[AdminNote],
            c.[CreatedAt],
            c.[UpdatedAt],
            COUNT(*) OVER() AS [TotalCount]
        FROM   [dbo].[Complaints] c
        LEFT  JOIN [dbo].[Orders] o ON o.[OrderId] = c.[OrderId]
        WHERE  c.[UserId]    = @UserId
          AND  c.[IsDeleted] = 0
        ORDER BY c.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Customer_Coupon_GetAvailable]...';


GO
CREATE PROCEDURE [dbo].[usp_Customer_Coupon_GetAvailable]
    @UserId INT = NULL    -- nullable so anonymous storefront previews work too
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT
            cp.[CouponId],
            cp.[CouponCode],
            o.[OfferName],
            o.[OfferType],          -- 1 = Flat, 2 = Percentage
            o.[DiscountValue],
            o.[MinOrderValue],
            o.[MaxDiscountCap],
            o.[ApplicableOn],       -- 1=Product, 2=Brand, 3=Category, 4=Cart
            o.[EntityId],
            b.[BrandName],
            o.[StartDate],
            o.[EndDate],
            o.[UsageLimitPerUser],
            -- per-user usage count so the UI can grey out exhausted coupons
            COALESCE((
                SELECT COUNT(*)
                FROM [dbo].[Orders] oh
                WHERE oh.[UserId]   = @UserId
                  AND oh.[CouponId] = cp.[CouponId]
                  AND oh.[IsDeleted] = 0
            ), 0) AS [UsedByUser]
        FROM [dbo].[Coupons] cp
        INNER JOIN [dbo].[Offers] o ON o.[OfferId] = cp.[OfferId]
        LEFT  JOIN [dbo].[Brands] b ON o.[ApplicableOn] = 2 AND b.[BrandId] = o.[EntityId]
        WHERE cp.[IsDeleted] = 0
          AND cp.[IsActive]  = 1
          AND o.[IsActive]   = 1
          AND o.[StartDate] <= GETUTCDATE()
          AND o.[EndDate]   >= GETUTCDATE()
          AND (o.[UsageLimitTotal] IS NULL OR o.[CurrentUsageCount] < o.[UsageLimitTotal])
        ORDER BY o.[EndDate] ASC, cp.[CouponCode] ASC;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Active_GetAll]...';


GO
-- All currently in-flight assignments for this dispatcher — anything that's
-- claimed but not yet terminal. Drives the "Active deliveries" tab in the
-- dispatcher portal.
--
-- Status buckets returned (mirror OrderItems + DeliveryAssignments):
--   10 PickedUp        — at warehouse, not yet left
--   4  Dispatched      — in transit hub-to-hub
--   9  OutForDelivery  — with last-mile courier (this dispatcher)
--   11 DeliveryFailed  — failed attempt, awaiting retry
-- Excludes terminal states: 5 Delivered, 12 RTO.
CREATE PROCEDURE [dbo].[usp_Dispatcher_Active_GetAll]
    @DispatcherId INT,
    @Page         INT = 1,
    @PageSize     INT = 50
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Offset INT = (@Page - 1) * @PageSize;

    SELECT
        da.[AssignmentId],
        da.[Status]                          AS [AssignmentStatus],
        da.[AssignedAt],
        da.[PickedUpAt],
        da.[OutForDeliveryAt],
        da.[AttemptNumber],
        da.[CodAmount],
        oi.[OrderItemId],
        oi.[OrderId],
        o.[OrderNumber],
        oi.[ProductName],
        oi.[VariantSnapshot],
        oi.[Quantity],
        oi.[TotalPrice],
        oi.[OrderStatus],
        w.[Code]                             AS [WarehouseCode],
        w.[Name]                             AS [WarehouseName],
        u.[FirstName] + N' ' + ISNULL(u.[LastName], N'') AS [BuyerName],
        u.[Mobile]                                       AS [BuyerMobile],
        ua.[AddressLine1]                                AS [BuyerAddressLine1],
        ua.[City]                                        AS [BuyerCity],
        ua.[State]                                       AS [BuyerState],
        ua.[PinCode]                                     AS [BuyerPincode],
        o.[PaymentMode],
        o.[PaymentStatus],
        COUNT(*) OVER()                      AS [TotalCount]
    FROM   [dbo].[DeliveryAssignments] da
    INNER JOIN [dbo].[OrderItems]     oi ON oi.[OrderItemId]   = da.[OrderItemId]
    INNER JOIN [dbo].[Orders]          o  ON o.[OrderId]       = oi.[OrderId]
    INNER JOIN [dbo].[Users]           u  ON u.[UserId]        = o.[UserId]
    LEFT  JOIN [dbo].[UserAddresses]   ua ON ua.[AddressId]    = o.[ShippingAddressId]
    INNER JOIN [dbo].[Warehouses]      w  ON w.[WarehouseId]   = da.[WarehouseId]
    WHERE  da.[DispatcherId] = @DispatcherId
      AND  da.[Status] IN (10, 4, 9, 11)
      AND  oi.[IsDeleted]    = 0
    ORDER BY
        -- OFD first (needs immediate action), then by claim age
        CASE da.[Status] WHEN 9 THEN 0 WHEN 11 THEN 1 WHEN 4 THEN 2 ELSE 3 END,
        da.[AssignedAt] DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Delivery_SendOtp]...';


GO
-- Generates a 6-digit delivery OTP for an Out-for-Delivery parcel and pushes
-- it to the buyer via an in-app Notification. The API layer additionally
-- attempts an SMS (graceful — skipped if Twilio isn't configured).
--
-- Returns the OTP + buyer name/mobile so the service can send the SMS. The
-- OTP is NEVER returned to the dispatcher-facing API response — only used
-- server-side for the SMS + stored hashed-in-place for later verification.
CREATE PROCEDURE [dbo].[usp_Dispatcher_Delivery_SendOtp]
    @AssignmentId INT,
    @DispatcherId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Status      TINYINT;
        DECLARE @OrderItemId INT;
        DECLARE @OrderId     INT;
        DECLARE @OrderNumber NVARCHAR(50);
        DECLARE @BuyerId     INT;
        DECLARE @BuyerName   NVARCHAR(200);
        DECLARE @BuyerMobile NVARCHAR(20);
        DECLARE @ProductName NVARCHAR(300);

        SELECT @Status      = da.[Status],
               @OrderItemId = da.[OrderItemId],
               @OrderId     = o.[OrderId],
               @OrderNumber = o.[OrderNumber],
               @BuyerId     = o.[UserId],
               @BuyerName   = u.[FirstName] + N' ' + ISNULL(u.[LastName], N''),
               @BuyerMobile = u.[Mobile],
               @ProductName = oi.[ProductName]
        FROM   [dbo].[DeliveryAssignments] da
        INNER JOIN [dbo].[OrderItems] oi ON oi.[OrderItemId] = da.[OrderItemId]
        INNER JOIN [dbo].[Orders]     o  ON o.[OrderId]      = oi.[OrderId]
        INNER JOIN [dbo].[Users]      u  ON u.[UserId]       = o.[UserId]
        WHERE  da.[AssignmentId] = @AssignmentId
          AND  da.[DispatcherId] = @DispatcherId;

        IF @Status IS NULL
            THROW 50430, N'Assignment not found or not owned by you.', 1;

        IF @Status <> 9
            THROW 50431, N'OTP can only be sent for items that are Out for Delivery.', 1;

        -- 6-digit OTP, 100000–999999
        DECLARE @Otp NVARCHAR(6) =
            RIGHT(N'000000' + CAST(ABS(CHECKSUM(NEWID())) % 1000000 AS NVARCHAR(6)), 6);

        BEGIN TRANSACTION;

            UPDATE [dbo].[DeliveryAssignments]
            SET    [DeliveryOtp]            = @Otp,
                   [DeliveryOtpSentAt]      = GETUTCDATE(),
                   [DeliveryOtpAttempts]    = 0,
                   [DeliveryOtpLockedUntil] = NULL,
                   [UpdatedAt]              = GETUTCDATE()
            WHERE  [AssignmentId] = @AssignmentId;

            -- In-app notification — always delivered, no external dependency.
            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@BuyerId,
                 N'Delivery OTP',
                 N'Your delivery OTP for order ' + @OrderNumber + N' is ' + @Otp +
                 N'. Share it with the delivery agent to receive "' + @ProductName + N'".',
                 2, N'Order', @OrderId, 1);

        COMMIT TRANSACTION;

        SELECT @Otp         AS [Otp],
               @OrderNumber AS [OrderNumber],
               @BuyerName   AS [BuyerName],
               @BuyerMobile AS [BuyerMobile];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Delivery_VerifyOtp]...';


GO
-- Verifies the buyer's delivery OTP and, on success, completes the delivery:
-- moves status 9 → 5 (Delivered) on both DeliveryAssignments + OrderItems,
-- stamps proof (photo URL + GPS), records COD collection, writes a DELIVERED
-- tracking entry + a DeliveryAttempts row, and stamps Orders.DeliveredAt.
--
-- Guards:
--   • assignment must be owned by @DispatcherId and in status 9
--   • not locked (DeliveryOtpLockedUntil in the future)
--   • OTP not expired (sent within last 15 minutes)
--   • OTP matches; 3 wrong attempts → 5-minute lockout (THROW 50436)
CREATE PROCEDURE [dbo].[usp_Dispatcher_Delivery_VerifyOtp]
    @AssignmentId  INT,
    @DispatcherId  INT,
    @Otp           NVARCHAR(6),
    @ProofUrl      NVARCHAR(500) = NULL,
    @GpsLat        DECIMAL(9,6)  = NULL,
    @GpsLng        DECIMAL(9,6)  = NULL,
    @CodCollected  DECIMAL(18,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Status       TINYINT;
        DECLARE @StoredOtp    NVARCHAR(6);
        DECLARE @SentAt       DATETIME2(0);
        DECLARE @Attempts     TINYINT;
        DECLARE @LockedUntil  DATETIME2(0);
        DECLARE @OrderItemId  INT;
        DECLARE @OrderId      INT;
        DECLARE @OrderNumber  NVARCHAR(50);
        DECLARE @ProductName  NVARCHAR(300);
        DECLARE @AttemptNum   TINYINT;

        SELECT @Status      = da.[Status],
               @StoredOtp   = da.[DeliveryOtp],
               @SentAt      = da.[DeliveryOtpSentAt],
               @Attempts    = da.[DeliveryOtpAttempts],
               @LockedUntil = da.[DeliveryOtpLockedUntil],
               @OrderItemId = da.[OrderItemId],
               @AttemptNum  = da.[AttemptNumber],
               @OrderId     = o.[OrderId],
               @OrderNumber = o.[OrderNumber],
               @ProductName = oi.[ProductName]
        FROM   [dbo].[DeliveryAssignments] da WITH (UPDLOCK, ROWLOCK)
        INNER JOIN [dbo].[OrderItems] oi ON oi.[OrderItemId] = da.[OrderItemId]
        INNER JOIN [dbo].[Orders]     o  ON o.[OrderId]      = oi.[OrderId]
        WHERE  da.[AssignmentId] = @AssignmentId
          AND  da.[DispatcherId] = @DispatcherId;

        IF @Status IS NULL
            THROW 50432, N'Assignment not found or not owned by you.', 1;

        IF @Status <> 9
            THROW 50433, N'This item is not out for delivery.', 1;

        IF @StoredOtp IS NULL
            THROW 50434, N'No OTP has been sent. Tap "Send OTP" first.', 1;

        IF @LockedUntil IS NOT NULL AND @LockedUntil > GETUTCDATE()
            THROW 50436, N'Too many wrong attempts. Try again in a few minutes or call the buyer.', 1;

        -- 15-minute expiry
        IF DATEDIFF(MINUTE, @SentAt, GETUTCDATE()) >= 15
            THROW 50435, N'OTP expired. Send a fresh one.', 1;

        -- Wrong OTP path
        IF @StoredOtp <> @Otp
        BEGIN
            DECLARE @NewAttempts TINYINT = @Attempts + 1;
            UPDATE [dbo].[DeliveryAssignments]
            SET    [DeliveryOtpAttempts]    = @NewAttempts,
                   [DeliveryOtpLockedUntil] = CASE WHEN @NewAttempts >= 3
                                                   THEN DATEADD(MINUTE, 5, GETUTCDATE())
                                                   ELSE [DeliveryOtpLockedUntil] END,
                   [UpdatedAt]              = GETUTCDATE()
            WHERE  [AssignmentId] = @AssignmentId;

            -- Forensic log
            INSERT INTO [dbo].[DeliveryAttempts]
                ([AssignmentId], [AttemptNumber], [Outcome], [Notes], [GpsLat], [GpsLng])
            VALUES
                (@AssignmentId, @AttemptNum, N'OTP_FAIL',
                 N'Wrong OTP entered (attempt ' + CAST(@NewAttempts AS NVARCHAR(3)) + N').',
                 @GpsLat, @GpsLng);

            IF @NewAttempts >= 3
                THROW 50436, N'Too many wrong attempts. Locked for 5 minutes — call the buyer to confirm.', 1;
            ELSE
                THROW 50437, N'Incorrect OTP. Please re-check with the buyer.', 1;
        END

        -- Correct OTP → complete delivery
        BEGIN TRANSACTION;

            UPDATE [dbo].[DeliveryAssignments]
            SET    [Status]           = 5,
                   [DeliveredAt]      = GETUTCDATE(),
                   [DeliveryProofUrl] = @ProofUrl,
                   [DeliveryGpsLat]   = @GpsLat,
                   [DeliveryGpsLng]   = @GpsLng,
                   [CodCollected]     = @CodCollected,
                   [CodSettledAt]     = CASE WHEN @CodCollected IS NOT NULL THEN GETUTCDATE() ELSE NULL END,
                   [DeliveryOtp]      = NULL,                 -- one-time use
                   [UpdatedAt]        = GETUTCDATE()
            WHERE  [AssignmentId] = @AssignmentId;

            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus] = 5,
                   [UpdatedAt]   = GETUTCDATE()
            WHERE  [OrderItemId] = @OrderItemId;

            -- Stamp the order header's DeliveredAt (settlement calc reads this).
            UPDATE [dbo].[Orders]
            SET    [DeliveredAt] = COALESCE([DeliveredAt], GETUTCDATE()),
                   [UpdatedAt]   = GETUTCDATE()
            WHERE  [OrderId] = @OrderId;

            -- Live position no longer relevant (defensive — L6 table may not have a row).
            DELETE FROM [dbo].[DispatcherCurrentPositions] WHERE [AssignmentId] = @AssignmentId;

            INSERT INTO [dbo].[DeliveryAttempts]
                ([AssignmentId], [AttemptNumber], [Outcome], [Notes], [GpsLat], [GpsLng])
            VALUES
                (@AssignmentId, @AttemptNum, N'DELIVERED',
                 CASE WHEN @CodCollected IS NOT NULL
                      THEN N'Delivered. COD collected: ' + CAST(@CodCollected AS NVARCHAR(20))
                      ELSE N'Delivered (prepaid).' END,
                 @GpsLat, @GpsLng);

            INSERT INTO [dbo].[OrderTrackings]
                ([OrderId], [OrderItemId], [Status], [Note], [ChangedAt])
            VALUES
                (@OrderId, @OrderItemId, N'DELIVERED',
                 N'"' + @ProductName + N'" delivered to the buyer (OTP verified).', GETUTCDATE());

        COMMIT TRANSACTION;

        SELECT @AssignmentId AS [AssignmentId],
               @OrderItemId  AS [OrderItemId],
               5             AS [Status],
               @OrderNumber  AS [OrderNumber];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_GetProfile]...';


GO
-- Profile lookup for the dispatcher portal. Includes the assigned warehouses
-- inline as a comma-separated string (small list, no need for a second SP).
CREATE PROCEDURE [dbo].[usp_Dispatcher_GetProfile]
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.[DispatcherId],
        d.[UserId],
        d.[EmployeeCode],
        d.[VehicleNumber],
        d.[VehicleType],
        d.[LicenseNumber],
        d.[BaseWarehouseId],
        wb.[Name]                   AS [BaseWarehouseName],
        u.[FirstName],
        u.[LastName],
        u.[Email],
        u.[Mobile],
        d.[JoinedAt],
        d.[IsActive],
        STUFF((
            SELECT N', ' + w.[Code] + N' — ' + w.[Name]
            FROM   [dbo].[DispatcherWarehouseAssignments] dwa
            INNER JOIN [dbo].[Warehouses] w ON w.[WarehouseId] = dwa.[WarehouseId]
            WHERE  dwa.[DispatcherId] = d.[DispatcherId] AND w.[IsDeleted] = 0
            ORDER BY w.[Name]
            FOR XML PATH(''), TYPE
        ).value(N'.', N'NVARCHAR(MAX)'), 1, 2, N'')   AS [AssignedWarehousesLabel]
    FROM   [dbo].[Dispatchers]      d
    INNER JOIN [dbo].[Users]        u  ON u.[UserId]      = d.[UserId]
    LEFT  JOIN [dbo].[Warehouses]   wb ON wb.[WarehouseId] = d.[BaseWarehouseId]
    WHERE  d.[UserId]   = @UserId
      AND  d.[IsDeleted] = 0;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_OutForDelivery_Mark]...';


GO
-- Dispatcher marks a dispatched parcel as Out for Delivery (status 4 → 9).
-- This is the gate that unlocks the delivery-OTP flow: only OFD parcels can
-- have a delivery OTP generated. Moves both DeliveryAssignments.Status and
-- OrderItems.OrderStatus to 9, stamps OutForDeliveryAt, writes an
-- OUT_FOR_DELIVERY tracking entry.
CREATE PROCEDURE [dbo].[usp_Dispatcher_OutForDelivery_Mark]
    @AssignmentId INT,
    @DispatcherId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @CurrentStatus TINYINT;
        DECLARE @OrderItemId   INT;
        DECLARE @OrderId       INT;
        DECLARE @OrderNumber   NVARCHAR(50);
        DECLARE @ProductName   NVARCHAR(300);

        SELECT @CurrentStatus = da.[Status],
               @OrderItemId   = da.[OrderItemId],
               @OrderId       = oi.[OrderId],
               @OrderNumber   = o.[OrderNumber],
               @ProductName   = oi.[ProductName]
        FROM   [dbo].[DeliveryAssignments] da WITH (UPDLOCK, ROWLOCK)
        INNER JOIN [dbo].[OrderItems] oi ON oi.[OrderItemId] = da.[OrderItemId]
        INNER JOIN [dbo].[Orders]     o  ON o.[OrderId]      = oi.[OrderId]
        WHERE  da.[AssignmentId] = @AssignmentId
          AND  da.[DispatcherId] = @DispatcherId;

        IF @CurrentStatus IS NULL
            THROW 50420, N'Assignment not found or not owned by you.', 1;

        IF @CurrentStatus <> 4
            THROW 50421, N'Only Dispatched parcels can be marked Out for Delivery.', 1;

        BEGIN TRANSACTION;

            UPDATE [dbo].[DeliveryAssignments]
            SET    [Status]           = 9,
                   [OutForDeliveryAt] = GETUTCDATE(),
                   [UpdatedAt]        = GETUTCDATE()
            WHERE  [AssignmentId] = @AssignmentId;

            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus] = 9,
                   [UpdatedAt]   = GETUTCDATE()
            WHERE  [OrderItemId] = @OrderItemId;

            INSERT INTO [dbo].[OrderTrackings]
                ([OrderId], [OrderItemId], [Status], [Note], [ChangedAt])
            VALUES
                (@OrderId, @OrderItemId, N'OUT_FOR_DELIVERY',
                 N'"' + @ProductName + N'" is out for delivery.', GETUTCDATE());

        COMMIT TRANSACTION;

        SELECT @AssignmentId AS [AssignmentId],
               @OrderItemId  AS [OrderItemId],
               9             AS [Status],
               @OrderNumber  AS [OrderNumber];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Pickup_Claim]...';


GO
-- Dispatcher claims a packed item at the warehouse — first half of the
-- pickup flow. Moves OrderItems.OrderStatus 3 → 10 (PickedUp), creates a
-- DeliveryAssignment row (the dispatcher's "manifest entry"), writes a
-- PICKED_UP tracking entry, and reserves the item so no other dispatcher
-- can grab it.
--
-- The second half (10 → 4 Dispatched) happens via usp_Dispatcher_Pickup_Confirm
-- when the dispatcher leaves the warehouse with the parcel.
CREATE PROCEDURE [dbo].[usp_Dispatcher_Pickup_Claim]
    @OrderItemId  INT,
    @DispatcherId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @CurrentStatus  TINYINT;
        DECLARE @VariantId      INT;
        DECLARE @OrderId        INT;
        DECLARE @OrderNumber    NVARCHAR(50);
        DECLARE @ProductName    NVARCHAR(300);
        DECLARE @WarehouseId    INT;
        DECLARE @PaymentMode    TINYINT;
        DECLARE @PaymentStatus  TINYINT;
        DECLARE @TotalPrice     DECIMAL(18,2);

        -- Capture current state with a row lock so two dispatchers can't both grab it.
        SELECT @CurrentStatus = oi.[OrderStatus],
               @VariantId     = oi.[VariantId],
               @OrderId       = oi.[OrderId],
               @OrderNumber   = o.[OrderNumber],
               @ProductName   = oi.[ProductName],
               @PaymentMode   = o.[PaymentMode],
               @PaymentStatus = o.[PaymentStatus],
               @TotalPrice    = oi.[TotalPrice]
        FROM   [dbo].[OrderItems] oi WITH (UPDLOCK, ROWLOCK)
        INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
        WHERE  oi.[OrderItemId] = @OrderItemId
          AND  oi.[IsDeleted]   = 0;

        IF @CurrentStatus IS NULL
            THROW 50410, N'Order item not found.', 1;

        IF @CurrentStatus <> 3
            THROW 50411, N'Only Packed items can be picked up.', 1;

        -- Resolve the warehouse where this variant is stocked, restricted to
        -- the dispatcher's assigned warehouses.
        SELECT TOP 1 @WarehouseId = s.[WarehouseId]
        FROM   [dbo].[Stock] s
        INNER JOIN [dbo].[DispatcherWarehouseAssignments] dwa
            ON dwa.[WarehouseId] = s.[WarehouseId] AND dwa.[DispatcherId] = @DispatcherId
        WHERE  s.[VariantId] = @VariantId
        ORDER BY s.[OnHand] DESC, s.[WarehouseId];

        IF @WarehouseId IS NULL
            THROW 50412, N'You are not assigned to this item''s warehouse.', 1;

        -- COD amount snapshot for unpaid COD orders
        DECLARE @CodAmount DECIMAL(18,2) =
            CASE WHEN @PaymentMode = 1 AND @PaymentStatus <> 2 THEN @TotalPrice ELSE NULL END;

        BEGIN TRANSACTION;

            -- 1) Create the assignment row
            INSERT INTO [dbo].[DeliveryAssignments]
                ([OrderItemId], [DispatcherId], [WarehouseId], [Status],
                 [PickedUpAt], [CodAmount])
            VALUES
                (@OrderItemId, @DispatcherId, @WarehouseId, 10,
                 GETUTCDATE(), @CodAmount);

            DECLARE @AssignmentId INT = SCOPE_IDENTITY();

            -- 2) Flip the order item to PickedUp
            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus] = 10,
                   [UpdatedAt]   = GETUTCDATE()
            WHERE  [OrderItemId] = @OrderItemId;

            -- 3) Tracking timeline entry
            INSERT INTO [dbo].[OrderTrackings]
                ([OrderId], [OrderItemId], [Status], [Note], [ChangedAt])
            VALUES
                (@OrderId, @OrderItemId, N'PICKED_UP',
                 N'"' + @ProductName + N'" picked up by dispatcher at the warehouse.',
                 GETUTCDATE());

        COMMIT TRANSACTION;

        SELECT @AssignmentId AS [AssignmentId],
               @OrderItemId  AS [OrderItemId],
               10            AS [OrderStatus],
               @OrderNumber  AS [OrderNumber],
               @WarehouseId  AS [WarehouseId];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Pickup_Confirm]...';


GO
-- Dispatcher confirms all picked-up items left the warehouse — second half of
-- the pickup flow. Bulk transition: every item currently at status 10
-- (PickedUp) claimed BY THIS dispatcher moves to status 4 (Dispatched), the
-- assignment row mirrors the move, and a DISPATCHED tracking entry is written
-- per item.
--
-- Returns the count of items confirmed. Designed for the "I'm leaving the
-- warehouse" button on the dispatcher portal.
CREATE PROCEDURE [dbo].[usp_Dispatcher_Pickup_Confirm]
    @DispatcherId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

            -- Snapshot the items we're confirming for tracking entries.
            DECLARE @Affected TABLE (
                AssignmentId INT,
                OrderItemId  INT,
                OrderId      INT,
                ProductName  NVARCHAR(300)
            );

            INSERT INTO @Affected (AssignmentId, OrderItemId, OrderId, ProductName)
            SELECT da.[AssignmentId], oi.[OrderItemId], oi.[OrderId], oi.[ProductName]
            FROM   [dbo].[DeliveryAssignments] da
            INNER JOIN [dbo].[OrderItems]      oi ON oi.[OrderItemId] = da.[OrderItemId]
            WHERE  da.[DispatcherId] = @DispatcherId
              AND  da.[Status]       = 10
              AND  oi.[OrderStatus]  = 10
              AND  oi.[IsDeleted]    = 0;

            DECLARE @Count INT = (SELECT COUNT(*) FROM @Affected);

            IF @Count = 0
            BEGIN
                ROLLBACK TRANSACTION;
                SELECT 0 AS [Confirmed];
                RETURN;
            END

            -- Flip assignments to Dispatched
            UPDATE da
            SET    da.[Status]    = 4,
                   da.[UpdatedAt] = GETUTCDATE()
            FROM   [dbo].[DeliveryAssignments] da
            INNER JOIN @Affected a ON a.AssignmentId = da.[AssignmentId];

            -- Flip order items to Dispatched
            UPDATE oi
            SET    oi.[OrderStatus] = 4,
                   oi.[UpdatedAt]   = GETUTCDATE()
            FROM   [dbo].[OrderItems] oi
            INNER JOIN @Affected a ON a.OrderItemId = oi.[OrderItemId];

            -- One tracking entry per item
            INSERT INTO [dbo].[OrderTrackings]
                ([OrderId], [OrderItemId], [Status], [Note])
            SELECT a.OrderId, a.OrderItemId, N'DISPATCHED',
                   N'"' + a.ProductName + N'" left the warehouse and is in transit.'
            FROM   @Affected a;

        COMMIT TRANSACTION;

        SELECT @Count AS [Confirmed];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Pickup_GetQueue]...';


GO
-- Pickup queue for the dispatcher portal.
--
-- Returns OrderItems that are:
--   • Currently Packed (status 3) — no dispatcher has claimed them yet, OR
--   • Already claimed by THIS dispatcher (status 10) — so they show as
--     "ready to confirm pickup" in the same list
-- AND located at a warehouse the dispatcher is assigned to.
--
-- Warehouse for an item is resolved via the Stock row (uniquely-keyed by
-- variant+warehouse). For demo seller orders there's exactly one Stock row
-- per variant, so this is a clean 1:1 join. Multi-warehouse scenarios pick
-- the row with the highest OnHand (good enough for the queue display).
CREATE PROCEDURE [dbo].[usp_Dispatcher_Pickup_GetQueue]
    @DispatcherId INT,
    @Page         INT = 1,
    @PageSize     INT = 50
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Offset INT = (@Page - 1) * @PageSize;

    ;WITH MyWarehouses AS (
        SELECT [WarehouseId]
        FROM   [dbo].[DispatcherWarehouseAssignments]
        WHERE  [DispatcherId] = @DispatcherId
    ),
    -- One warehouse per variant (highest stock row).
    VariantWarehouse AS (
        SELECT s.[VariantId], s.[WarehouseId],
               ROW_NUMBER() OVER (PARTITION BY s.[VariantId] ORDER BY s.[OnHand] DESC, s.[WarehouseId]) AS rn
        FROM   [dbo].[Stock] s
        INNER JOIN MyWarehouses mw ON mw.[WarehouseId] = s.[WarehouseId]
    ),
    -- Latest assignment per item (so we know who claimed it, if anyone).
    LatestAssignment AS (
        SELECT da.[OrderItemId], da.[AssignmentId], da.[DispatcherId], da.[Status],
               ROW_NUMBER() OVER (PARTITION BY da.[OrderItemId] ORDER BY da.[AssignedAt] DESC) AS rn
        FROM   [dbo].[DeliveryAssignments] da
    )
    SELECT
        oi.[OrderItemId],
        oi.[OrderId],
        o.[OrderNumber],
        oi.[ProductName],
        oi.[VariantSnapshot],
        oi.[Quantity],
        oi.[TotalPrice],
        oi.[OrderStatus],
        oi.[CreatedAt]                       AS [OrderItemCreatedAt],
        vw.[WarehouseId],
        w.[Code]                             AS [WarehouseCode],
        w.[Name]                             AS [WarehouseName],
        w.[City]                             AS [WarehouseCity],
        o.[PaymentMode],
        o.[PaymentStatus],
        CASE WHEN o.[PaymentMode] = 1 AND o.[PaymentStatus] <> 2
             THEN oi.[TotalPrice] ELSE NULL END AS [CodAmount],
        u.[FirstName] + N' ' + ISNULL(u.[LastName], N'') AS [BuyerName],
        u.[Mobile]                                       AS [BuyerMobile],
        ua.[AddressLine1]                                AS [BuyerAddressLine1],
        ua.[City]                                        AS [BuyerCity],
        ua.[State]                                       AS [BuyerState],
        ua.[PinCode]                                     AS [BuyerPincode],
        la.[AssignmentId],                                 -- non-null if already claimed
        la.[Status]                          AS [AssignmentStatus],
        COUNT(*) OVER ()                                 AS [TotalCount]
    FROM   [dbo].[OrderItems]               oi
    INNER JOIN [dbo].[Orders]                o  ON o.[OrderId]  = oi.[OrderId]
    INNER JOIN [dbo].[Users]                 u  ON u.[UserId]   = o.[UserId]
    LEFT  JOIN [dbo].[UserAddresses]         ua ON ua.[AddressId] = o.[ShippingAddressId]
    INNER JOIN VariantWarehouse              vw ON vw.[VariantId] = oi.[VariantId] AND vw.rn = 1
    INNER JOIN [dbo].[Warehouses]            w  ON w.[WarehouseId] = vw.[WarehouseId]
    LEFT  JOIN LatestAssignment              la ON la.[OrderItemId] = oi.[OrderItemId] AND la.rn = 1
    WHERE  oi.[IsDeleted] = 0
      AND  o.[IsDeleted]  = 0
      -- show unclaimed Packed items, or items already claimed BY THIS dispatcher
      AND  (
            (oi.[OrderStatus] = 3 AND la.[AssignmentId] IS NULL)
         OR (oi.[OrderStatus] = 10 AND la.[DispatcherId] = @DispatcherId)
           )
    ORDER BY
        -- Already-claimed items first (so dispatcher sees what to do next)
        CASE WHEN la.[DispatcherId] = @DispatcherId THEN 0 ELSE 1 END,
        oi.[CreatedAt] ASC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Dispatcher_Register]...';


GO
-- Onboards a Dispatcher. Two paths:
--   (a) Existing user (RoleId already 4) → just upsert Dispatchers row + warehouse assignments
--   (b) New user — caller must have already created the User row with RoleId=4 + PasswordHash
--       (mirrors how Sellers are created via the existing signup flow).
--
-- This SP only manages the Dispatchers profile + warehouse assignments. Pass
-- @WarehouseIdsCsv as e.g. '1,3,5' to assign multiple warehouses in one call.
CREATE PROCEDURE [dbo].[usp_Dispatcher_Register]
    @UserId           INT,
    @EmployeeCode     NVARCHAR(20),
    @VehicleNumber    NVARCHAR(20)   = NULL,
    @VehicleType      NVARCHAR(20)   = NULL,
    @LicenseNumber    NVARCHAR(30)   = NULL,
    @BaseWarehouseId  INT            = NULL,
    @WarehouseIdsCsv  NVARCHAR(MAX)  = NULL,   -- comma-separated warehouse ids
    @CreatedBy        INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- User must exist and carry the Dispatcher role
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[Users] u
            WHERE u.[UserId] = @UserId AND u.[IsDeleted] = 0 AND u.[RoleId] = 4
        )
            THROW 50400, N'User not found or not a Dispatcher.', 1;

        IF EXISTS (
            SELECT 1 FROM [dbo].[Dispatchers]
            WHERE [EmployeeCode] = @EmployeeCode AND [IsDeleted] = 0
              AND [UserId] <> @UserId
        )
            THROW 50401, N'EmployeeCode already in use by another dispatcher.', 1;

        BEGIN TRANSACTION;

            DECLARE @DispatcherId INT;
            SELECT @DispatcherId = [DispatcherId]
            FROM   [dbo].[Dispatchers]
            WHERE  [UserId] = @UserId AND [IsDeleted] = 0;

            IF @DispatcherId IS NULL
            BEGIN
                INSERT INTO [dbo].[Dispatchers]
                    ([UserId], [EmployeeCode], [VehicleNumber], [VehicleType],
                     [LicenseNumber], [BaseWarehouseId], [CreatedBy], [UpdatedBy])
                VALUES
                    (@UserId, @EmployeeCode, @VehicleNumber, @VehicleType,
                     @LicenseNumber, @BaseWarehouseId, @CreatedBy, @CreatedBy);
                SET @DispatcherId = SCOPE_IDENTITY();
            END
            ELSE
            BEGIN
                UPDATE [dbo].[Dispatchers]
                SET    [EmployeeCode]    = @EmployeeCode,
                       [VehicleNumber]   = @VehicleNumber,
                       [VehicleType]     = @VehicleType,
                       [LicenseNumber]   = @LicenseNumber,
                       [BaseWarehouseId] = @BaseWarehouseId,
                       [UpdatedAt]       = GETUTCDATE(),
                       [UpdatedBy]       = @CreatedBy
                WHERE  [DispatcherId] = @DispatcherId;
            END

            -- Warehouse assignments — replace-all semantics (idempotent for admin re-saves).
            IF @WarehouseIdsCsv IS NOT NULL
            BEGIN
                DELETE FROM [dbo].[DispatcherWarehouseAssignments]
                WHERE [DispatcherId] = @DispatcherId;

                INSERT INTO [dbo].[DispatcherWarehouseAssignments]
                    ([DispatcherId], [WarehouseId], [AssignedBy])
                SELECT @DispatcherId, CAST(LTRIM(RTRIM(value)) AS INT), @CreatedBy
                FROM   STRING_SPLIT(@WarehouseIdsCsv, ',')
                WHERE  LTRIM(RTRIM(value)) <> N''
                  AND  EXISTS (SELECT 1 FROM [dbo].[Warehouses] w
                               WHERE w.[WarehouseId] = CAST(LTRIM(RTRIM(value)) AS INT)
                                 AND w.[IsDeleted] = 0);
            END

        COMMIT TRANSACTION;

        SELECT [DispatcherId], [UserId], [EmployeeCode], [VehicleNumber],
               [VehicleType], [LicenseNumber], [BaseWarehouseId], [CreatedAt]
        FROM   [dbo].[Dispatchers]
        WHERE  [DispatcherId] = @DispatcherId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Engagement_ProductViewLog_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Engagement_ProductViewLog_Add]
    @ProductId  INT,
    @UserId     INT            = NULL,
    @SessionId  NVARCHAR(100),
    @IpAddress  NVARCHAR(50)   = NULL,
    @DeviceType NVARCHAR(50)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        INSERT INTO [dbo].[ProductViewLogs]
            ([ProductId], [UserId], [SessionId], [IpAddress], [DeviceType], [ViewedAt])
        VALUES
            (@ProductId, @UserId, @SessionId, @IpAddress, @DeviceType, GETUTCDATE());

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Engagement_RecentlyViewed_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Engagement_RecentlyViewed_Add]
    @UserId    INT,
    @ProductId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        MERGE [dbo].[RecentlyViewed] AS tgt
        USING (SELECT @UserId AS [UserId], @ProductId AS [ProductId]) AS src
            ON tgt.[UserId] = src.[UserId] AND tgt.[ProductId] = src.[ProductId]
        WHEN MATCHED THEN UPDATE SET
            tgt.[ViewedAt] = GETUTCDATE()
        WHEN NOT MATCHED THEN INSERT
            ([UserId], [ProductId], [ViewedAt])
        VALUES
            (@UserId, @ProductId, GETUTCDATE());

        -- Keep only the latest 20 entries per user
        DELETE FROM [dbo].[RecentlyViewed]
        WHERE [UserId] = @UserId
          AND [ViewId] NOT IN (
              SELECT TOP 20 [ViewId]
              FROM [dbo].[RecentlyViewed]
              WHERE [UserId] = @UserId
              ORDER BY [ViewedAt] DESC
          );

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Engagement_RecentlyViewed_GetByUser]...';


GO
CREATE PROCEDURE [dbo].[usp_Engagement_RecentlyViewed_GetByUser]
    @UserId INT,
    @Top    INT = 10
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT TOP (@Top)
            p.[ProductId],
            p.[ProductName],
            p.[SlugUrl],
            p.[SellingPrice],
            p.[MRP],
            pi_.[ImageUrl]  AS [PrimaryImageUrl],
            rv.[ViewedAt]
        FROM [dbo].[RecentlyViewed] rv
        INNER JOIN [dbo].[Products]      p   ON p.[ProductId]  = rv.[ProductId]  AND p.[IsDeleted] = 0
        LEFT  JOIN [dbo].[ProductImages] pi_ ON pi_.[ProductId] = p.[ProductId]
                                             AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        WHERE rv.[UserId] = @UserId
        ORDER BY rv.[ViewedAt] DESC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Engagement_Review_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Engagement_Review_Add]
    @UserId       INT,
    @ProductId    INT,
    @OrderItemId  INT,
    @Rating       TINYINT,
    @Title        NVARCHAR(200)  = NULL,
    @Body         NVARCHAR(2000) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- When OrderItemId is supplied, verify the user actually purchased and received this item.
        -- When NULL, accept the review as-is (open review flow). Reviews remain unapproved until moderation.
        IF @OrderItemId IS NOT NULL
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM [dbo].[OrderItems] oi
                INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
                WHERE oi.[OrderItemId] = @OrderItemId
                  AND o.[UserId]       = @UserId
                  AND oi.[ProductId]   = @ProductId
                  AND o.[OrderStatus]  = 5  -- Delivered
                  AND oi.[IsDeleted]   = 0
                  AND o.[IsDeleted]    = 0
            )
                THROW 50150, N'You can only review products from delivered orders.', 1;

            IF EXISTS (
                SELECT 1 FROM [dbo].[Reviews]
                WHERE [UserId] = @UserId AND [OrderItemId] = @OrderItemId AND [IsDeleted] = 0
            )
                THROW 50151, N'You have already reviewed this item.', 1;
        END
        ELSE
        BEGIN
            -- Open-review flow: one review per (user, product) when no order is attached.
            IF EXISTS (
                SELECT 1 FROM [dbo].[Reviews]
                WHERE [UserId] = @UserId
                  AND [ProductId] = @ProductId
                  AND [OrderItemId] IS NULL
                  AND [IsDeleted] = 0
            )
                THROW 50151, N'You have already reviewed this product.', 1;
        END

        INSERT INTO [dbo].[Reviews]
            ([UserId], [ProductId], [OrderItemId], [Rating], [Title], [Body],
             [IsApproved], [CreatedAt], [CreatedBy], [IsDeleted])
        VALUES
            (@UserId, @ProductId, @OrderItemId, @Rating, @Title, @Body,
             1, GETUTCDATE(), @UserId, 0);

        SELECT SCOPE_IDENTITY() AS [ReviewId];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Engagement_Review_Approve]...';


