            SELECT 1 FROM [dbo].[Reviews]
            WHERE [ReviewId] = @ReviewId AND [IsApproved] = 1 AND [IsDeleted] = 0
        )
            THROW 50160, N'Review not found.', 1;

        UPDATE [dbo].[Reviews]
        SET    [HelpfulCount] = [HelpfulCount] + 1,
               [UpdatedAt]    = GETUTCDATE()
        WHERE  [ReviewId] = @ReviewId;

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
