PRINT N'Creating Procedure [dbo].[usp_Inventory_Stock_ReleaseReservation]...';


GO
-- Releases an Active reservation (or marks it Committed when @CommitToOrderId provided).
-- For Commit: also decrements Stock.OnHand by the reserved quantity (the actual ship/decrement).
CREATE PROCEDURE [dbo].[usp_Inventory_Stock_ReleaseReservation]
    @ReservationId    BIGINT,
    @CommitToOrderId  INT = NULL,   -- when supplied: commit (decrement OnHand) instead of release
    @Reason           NVARCHAR(500) = NULL,
    @ChangedBy        INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @VariantId INT, @WarehouseId INT, @Quantity INT, @Status TINYINT;

        SELECT @VariantId = [VariantId], @WarehouseId = [WarehouseId],
               @Quantity = [Quantity], @Status = [Status]
        FROM   [dbo].[StockReservations] WITH (UPDLOCK, HOLDLOCK)
        WHERE  [ReservationId] = @ReservationId;

        IF @VariantId IS NULL
            THROW 50320, N'Reservation not found.', 1;

        IF @Status <> 1   -- already terminal
        BEGIN
            COMMIT TRANSACTION;
            SELECT @Status AS [Status], 0 AS [Changed];
            RETURN;
        END;

        -- Lock the matching Stock row
        DECLARE @OnHand INT, @Reserved INT;
        SELECT @OnHand = [OnHand], @Reserved = [Reserved]
        FROM   [dbo].[Stock] WITH (UPDLOCK, HOLDLOCK)
        WHERE  [VariantId] = @VariantId AND [WarehouseId] = @WarehouseId;

        IF @CommitToOrderId IS NULL
        BEGIN
            -- Release path: -Reserved
            UPDATE [dbo].[Stock]
            SET    [Reserved]  = [Reserved] - @Quantity,
                   [UpdatedAt] = GETUTCDATE(),
                   [UpdatedBy] = @ChangedBy
            WHERE  [VariantId] = @VariantId AND [WarehouseId] = @WarehouseId;

            UPDATE [dbo].[StockReservations]
            SET    [Status]     = 3,
                   [ReleasedAt] = GETUTCDATE()
            WHERE  [ReservationId] = @ReservationId;

            INSERT INTO [dbo].[StockMovements]
                ([VariantId], [WarehouseId], [MovementType], [QuantityDelta], [ReservedDelta],
                 [Reason], [ReferenceType], [ReferenceId], [ChangedBy])
            VALUES
                (@VariantId, @WarehouseId, 4, 0, -@Quantity,
                 ISNULL(@Reason, N'Release'), N'Reservation', @ReservationId, @ChangedBy);
        END
        ELSE
        BEGIN
            -- Commit path: -Reserved AND -OnHand (the actual decrement)
            UPDATE [dbo].[Stock]
            SET    [OnHand]    = [OnHand]   - @Quantity,
                   [Reserved]  = [Reserved] - @Quantity,
                   [UpdatedAt] = GETUTCDATE(),
                   [UpdatedBy] = @ChangedBy
            WHERE  [VariantId] = @VariantId AND [WarehouseId] = @WarehouseId;

            UPDATE [dbo].[StockReservations]
            SET    [Status]     = 2,
                   [OrderId]    = @CommitToOrderId,
                   [ReleasedAt] = GETUTCDATE()
            WHERE  [ReservationId] = @ReservationId;

            INSERT INTO [dbo].[StockMovements]
                ([VariantId], [WarehouseId], [MovementType], [QuantityDelta], [ReservedDelta],
                 [Reason], [ReferenceType], [ReferenceId], [ChangedBy])
            VALUES
                (@VariantId, @WarehouseId, 5, -@Quantity, -@Quantity,
                 ISNULL(@Reason, N'Ship'), N'Order', @CommitToOrderId, @ChangedBy);

            -- Refresh denormalized cache
            UPDATE pv
            SET    [StockQuantity] = ISNULL(t.[Total], 0),
                   [UpdatedAt]     = GETUTCDATE()
            FROM   [dbo].[ProductVariants] pv
            OUTER APPLY (
                SELECT SUM([OnHand]) AS [Total] FROM [dbo].[Stock] WHERE [VariantId] = @VariantId
            ) t
            WHERE  pv.[VariantId] = @VariantId;
        END;

        COMMIT TRANSACTION;
        SELECT (CASE WHEN @CommitToOrderId IS NULL THEN 3 ELSE 2 END) AS [Status], 1 AS [Changed];

    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Inventory_Stock_Reserve]...';


GO
-- Atomically reserve @Quantity units of a variant at a warehouse.
-- Picks the row under UPDLOCK,HOLDLOCK; fails fast if insufficient availability.
-- Returns the new ReservationId. ExpiresAt is computed from @TtlMinutes.
CREATE PROCEDURE [dbo].[usp_Inventory_Stock_Reserve]
    @VariantId    INT,
    @WarehouseId  INT,
    @Quantity     INT,
    @UserId       INT          = NULL,
    @CartLineId   INT          = NULL,
    @TtlMinutes   INT          = 15,
    @ChangedBy    INT          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Quantity <= 0
            THROW 50310, N'Quantity must be positive.', 1;
        IF @TtlMinutes <= 0
            THROW 50311, N'TtlMinutes must be positive.', 1;

        BEGIN TRANSACTION;

        DECLARE @OnHand INT, @Reserved INT;

        SELECT @OnHand = [OnHand], @Reserved = [Reserved]
        FROM [dbo].[Stock] WITH (UPDLOCK, HOLDLOCK)
        WHERE [VariantId] = @VariantId AND [WarehouseId] = @WarehouseId;

        IF @OnHand IS NULL
            THROW 50312, N'No stock record exists for the given variant/warehouse.', 1;

        IF (@OnHand - @Reserved) < @Quantity
            THROW 50313, N'Insufficient available stock to reserve.', 1;

        UPDATE [dbo].[Stock]
        SET    [Reserved]  = [Reserved] + @Quantity,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @ChangedBy
        WHERE  [VariantId] = @VariantId AND [WarehouseId] = @WarehouseId;

        DECLARE @ExpiresAt DATETIME2(0) = DATEADD(MINUTE, @TtlMinutes, GETUTCDATE());

        INSERT INTO [dbo].[StockReservations]
            ([VariantId], [WarehouseId], [UserId], [CartLineId], [Quantity], [Status], [ExpiresAt])
        VALUES
            (@VariantId, @WarehouseId, @UserId, @CartLineId, @Quantity, 1, @ExpiresAt);

        DECLARE @ReservationId BIGINT = SCOPE_IDENTITY();

        INSERT INTO [dbo].[StockMovements]
            ([VariantId], [WarehouseId], [MovementType], [QuantityDelta], [ReservedDelta],
             [Reason], [ReferenceType], [ReferenceId], [ChangedBy])
        VALUES
            (@VariantId, @WarehouseId, 3, 0, @Quantity,
             N'Reserve', N'Reservation', @ReservationId, @ChangedBy);

        COMMIT TRANSACTION;

        SELECT @ReservationId AS [ReservationId], @ExpiresAt AS [ExpiresAt];

    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Inventory_StockMatrix_Get]...';


GO
-- SKU × Warehouse matrix for the admin/seller inventory page.
-- Returns one row per (Variant, Warehouse) along with totals.
CREATE PROCEDURE [dbo].[usp_Inventory_StockMatrix_Get]
    @SellerId    INT = NULL,
    @WarehouseId INT = NULL,
    @Search      NVARCHAR(200) = NULL,
    @Page        INT = 1,
    @PageSize    INT = 50
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Offset INT = (@Page - 1) * @PageSize;

    ;WITH Filtered AS (
        SELECT
            pv.[VariantId],
            pv.[ProductId],
            pv.[VariantSku],
            pv.[Color],
            pv.[Size],
            pv.[LowStockThreshold],
            p.[ProductName],
            p.[SellerId],
            sl.[BusinessName] AS [SellerName]
        FROM [dbo].[ProductVariants] pv
        INNER JOIN [dbo].[Products] p  ON p.[ProductId] = pv.[ProductId]
        LEFT  JOIN [dbo].[Sellers]  sl ON sl.[SellerId] = p.[SellerId]
        WHERE pv.[IsDeleted] = 0
          AND pv.[IsActive]  = 1
          AND p.[IsDeleted]  = 0
          AND (@SellerId IS NULL OR p.[SellerId] = @SellerId)
          AND (@Search IS NULL
                OR pv.[VariantSku] LIKE N'%' + @Search + N'%'
                OR p.[ProductName] LIKE N'%' + @Search + N'%')
    ),
    PageRows AS (
        SELECT *
        FROM Filtered
        ORDER BY [ProductName], [VariantSku]
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY
    )
    SELECT
        pr.[VariantId],
        pr.[ProductId],
        pr.[VariantSku],
        pr.[ProductName],
        pr.[Color],
        pr.[Size],
        pr.[LowStockThreshold],
        pr.[SellerId],
        pr.[SellerName],
        s.[WarehouseId],
        w.[Code]      AS [WarehouseCode],
        w.[Name]      AS [WarehouseName],
        ISNULL(s.[OnHand],   0)                 AS [OnHand],
        ISNULL(s.[Reserved], 0)                 AS [Reserved],
        ISNULL(s.[OnHand], 0) - ISNULL(s.[Reserved], 0) AS [Available]
    FROM PageRows pr
    LEFT JOIN [dbo].[Stock]      s ON s.[VariantId]   = pr.[VariantId]
                                  AND (@WarehouseId IS NULL OR s.[WarehouseId] = @WarehouseId)
    LEFT JOIN [dbo].[Warehouses] w ON w.[WarehouseId] = s.[WarehouseId] AND w.[IsDeleted] = 0
    ORDER BY pr.[ProductName], pr.[VariantSku], w.[Name];

    SELECT COUNT(1) AS [TotalCount] FROM (
        SELECT pv.[VariantId]
        FROM [dbo].[ProductVariants] pv
        INNER JOIN [dbo].[Products] p ON p.[ProductId] = pv.[ProductId]
        WHERE pv.[IsDeleted] = 0
          AND pv.[IsActive]  = 1
          AND p.[IsDeleted]  = 0
          AND (@SellerId IS NULL OR p.[SellerId] = @SellerId)
          AND (@Search IS NULL
                OR pv.[VariantSku] LIKE N'%' + @Search + N'%'
                OR p.[ProductName] LIKE N'%' + @Search + N'%')
    ) f;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Inventory_Transfer_Initiate]...';


GO
-- Move @Quantity units of a variant from @FromWarehouseId to @ToWarehouseId.
-- Step 1 of 2: decrements From side, marks transfer InTransit. Receive completes it.
CREATE PROCEDURE [dbo].[usp_Inventory_Transfer_Initiate]
    @VariantId       INT,
    @FromWarehouseId INT,
    @ToWarehouseId   INT,
    @Quantity        INT,
    @Reason          NVARCHAR(500) = NULL,
    @InitiatedBy     INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Quantity <= 0
            THROW 50330, N'Quantity must be positive.', 1;
        IF @FromWarehouseId = @ToWarehouseId
            THROW 50331, N'From and To warehouses must differ.', 1;

        BEGIN TRANSACTION;

        DECLARE @OnHand INT, @Reserved INT;

        SELECT @OnHand = [OnHand], @Reserved = [Reserved]
        FROM [dbo].[Stock] WITH (UPDLOCK, HOLDLOCK)
        WHERE [VariantId] = @VariantId AND [WarehouseId] = @FromWarehouseId;

        IF @OnHand IS NULL
            THROW 50332, N'Source warehouse has no stock for this variant.', 1;

        IF (@OnHand - @Reserved) < @Quantity
            THROW 50333, N'Insufficient available stock at source warehouse.', 1;

        UPDATE [dbo].[Stock]
        SET    [OnHand]    = [OnHand] - @Quantity,
               [UpdatedAt] = GETUTCDATE(),
               [UpdatedBy] = @InitiatedBy
        WHERE  [VariantId] = @VariantId AND [WarehouseId] = @FromWarehouseId;

        INSERT INTO [dbo].[StockTransfers]
            ([VariantId], [FromWarehouseId], [ToWarehouseId], [Quantity], [Status], [Reason], [InitiatedBy])
        VALUES
            (@VariantId, @FromWarehouseId, @ToWarehouseId, @Quantity, 1, @Reason, @InitiatedBy);

        DECLARE @TransferId INT = SCOPE_IDENTITY();

        INSERT INTO [dbo].[StockMovements]
            ([VariantId], [WarehouseId], [MovementType], [QuantityDelta], [ReservedDelta],
             [Reason], [ReferenceType], [ReferenceId], [ChangedBy])
        VALUES
            (@VariantId, @FromWarehouseId, 7, -@Quantity, 0,
             ISNULL(@Reason, N'TransferOut'), N'Transfer', @TransferId, @InitiatedBy);

        -- Refresh denormalized cache (totals don't change yet — units in-flight)
        UPDATE pv
        SET    [StockQuantity] = ISNULL(t.[Total], 0),
               [UpdatedAt]     = GETUTCDATE()
        FROM   [dbo].[ProductVariants] pv
        OUTER APPLY (SELECT SUM([OnHand]) AS [Total] FROM [dbo].[Stock] WHERE [VariantId] = @VariantId) t
        WHERE  pv.[VariantId] = @VariantId;

        COMMIT TRANSACTION;
        SELECT @TransferId AS [TransferId];

    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Inventory_Transfer_Receive]...';


GO
-- Step 2 of 2: marks the transfer Received and credits the destination warehouse.
CREATE PROCEDURE [dbo].[usp_Inventory_Transfer_Receive]
    @TransferId  INT,
    @ReceivedBy  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @VariantId INT, @ToWh INT, @Qty INT, @Status TINYINT;

        SELECT @VariantId = [VariantId], @ToWh = [ToWarehouseId],
               @Qty = [Quantity], @Status = [Status]
        FROM [dbo].[StockTransfers] WITH (UPDLOCK, HOLDLOCK)
        WHERE [TransferId] = @TransferId;

        IF @VariantId IS NULL
            THROW 50340, N'Transfer not found.', 1;

        IF @Status <> 1
            THROW 50341, N'Transfer is not in transit.', 1;

        -- Lock or create destination stock row
        DECLARE @StockId INT;
        SELECT @StockId = [StockId]
        FROM [dbo].[Stock] WITH (UPDLOCK, HOLDLOCK)
        WHERE [VariantId] = @VariantId AND [WarehouseId] = @ToWh;

        IF @StockId IS NULL
        BEGIN
            INSERT INTO [dbo].[Stock] ([VariantId], [WarehouseId], [OnHand], [Reserved], [UpdatedBy])
            VALUES (@VariantId, @ToWh, @Qty, 0, @ReceivedBy);
        END
        ELSE
        BEGIN
            UPDATE [dbo].[Stock]
            SET    [OnHand]    = [OnHand] + @Qty,
                   [UpdatedAt] = GETUTCDATE(),
                   [UpdatedBy] = @ReceivedBy
            WHERE  [StockId] = @StockId;
        END;

        UPDATE [dbo].[StockTransfers]
        SET    [Status]     = 2,
               [ReceivedBy] = @ReceivedBy,
               [ReceivedAt] = GETUTCDATE()
        WHERE  [TransferId] = @TransferId;

        INSERT INTO [dbo].[StockMovements]
            ([VariantId], [WarehouseId], [MovementType], [QuantityDelta], [ReservedDelta],
             [Reason], [ReferenceType], [ReferenceId], [ChangedBy])
        VALUES
            (@VariantId, @ToWh, 8, @Qty, 0,
             N'TransferIn', N'Transfer', @TransferId, @ReceivedBy);

        UPDATE pv
        SET    [StockQuantity] = ISNULL(t.[Total], 0),
               [UpdatedAt]     = GETUTCDATE()
        FROM   [dbo].[ProductVariants] pv
        OUTER APPLY (SELECT SUM([OnHand]) AS [Total] FROM [dbo].[Stock] WHERE [VariantId] = @VariantId) t
        WHERE  pv.[VariantId] = @VariantId;

        COMMIT TRANSACTION;
        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Inventory_Warehouse_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Inventory_Warehouse_GetAll]
    @SellerId INT = NULL,           -- NULL = all (admin view)
    @IncludeInactive BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        w.[WarehouseId],
        w.[Code],
        w.[Name],
        w.[SellerId],
        s.[BusinessName]    AS [SellerName],
        w.[AddressLine1],
        w.[AddressLine2],
        w.[City],
        w.[State],
        w.[PinCode],
        w.[Country],
        w.[IsActive],
        w.[CreatedAt]
    FROM [dbo].[Warehouses] w
    LEFT JOIN [dbo].[Sellers] s ON s.[SellerId] = w.[SellerId]
    WHERE w.[IsDeleted] = 0
      AND (@SellerId IS NULL OR w.[SellerId] = @SellerId OR w.[SellerId] IS NULL)
      AND (@IncludeInactive = 1 OR w.[IsActive] = 1)
    ORDER BY w.[SellerId], w.[Name];
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Notification_GetByUser]...';


GO
CREATE PROCEDURE [dbo].[usp_Notification_GetByUser]
    @UserId     INT,
    @IsRead     BIT = NULL,
    @PageNumber INT = 1,
    @PageSize   INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            n.[NotificationId],
            n.[Title],
            n.[Body],
            n.[NotificationType],
            n.[EntityId],
            n.[EntityType],
            n.[IsRead],
            n.[ReadAt],
            n.[CreatedAt],
            COUNT(*) OVER()                                     AS [TotalCount],
            SUM(CASE WHEN n.[IsRead] = 0 THEN 1 ELSE 0 END)
                OVER()                                          AS [UnreadCount]
        FROM [dbo].[Notifications] n
        WHERE n.[UserId]    = @UserId
          AND n.[IsDeleted] = 0
          AND (@IsRead IS NULL OR n.[IsRead] = @IsRead)
        ORDER BY n.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Notification_MarkRead]...';


GO
CREATE PROCEDURE [dbo].[usp_Notification_MarkRead]
    @UserId         INT,
    @NotificationId INT = NULL  -- NULL = mark all as read
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        UPDATE [dbo].[Notifications]
        SET    [IsRead]  = 1,
               [ReadAt]  = GETUTCDATE()
        WHERE  [UserId]    = @UserId
          AND  [IsDeleted] = 0
          AND  [IsRead]    = 0
          AND  (@NotificationId IS NULL OR [NotificationId] = @NotificationId);

        SELECT @@ROWCOUNT AS [UpdatedCount];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Notification_Send]...';


GO
CREATE PROCEDURE [dbo].[usp_Notification_Send]
    @UserId           INT,
    @Title            NVARCHAR(200),
    @Body             NVARCHAR(1000),
    @NotificationType TINYINT       = NULL,
    @EntityId         INT           = NULL,
    @EntityType       NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        INSERT INTO [dbo].[Notifications]
            ([UserId], [Title], [Body], [NotificationType],
             [EntityId], [EntityType], [IsRead],
             [CreatedAt], [IsDeleted])
        VALUES
            (@UserId, @Title, @Body, @NotificationType,
             @EntityId, @EntityType, 0,
             GETUTCDATE(), 0);

        SELECT SCOPE_IDENTITY() AS [NotificationId];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Order_CancelByBuyer]...';


GO
CREATE PROCEDURE [dbo].[usp_Order_CancelByBuyer]
    @OrderId INT,
    @UserId INT,
    @CancellationReason NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentStatus TINYINT;
    DECLARE @OrderUserId INT;

    -- Validate: order exists and belongs to user
    SELECT @CurrentStatus = OrderStatus, @OrderUserId = UserId
    FROM [dbo].[Orders]
    WHERE OrderId = @OrderId AND IsDeleted = 0;

    IF @CurrentStatus IS NULL
    BEGIN
        RAISERROR('Order not found', 16, 1);
        RETURN;
    END;

    IF @OrderUserId <> @UserId
    BEGIN
        RAISERROR('Unauthorized: Order does not belong to this user', 16, 1);
        RETURN;
    END;

    -- Validate: order must be Pending (1) or Confirmed (2)
    -- Cannot cancel if seller has progressed to Processing (3) or beyond
    IF @CurrentStatus > 2
    BEGIN
        RAISERROR('Cannot cancel order after seller has confirmed. Please contact support.', 16, 1);
        RETURN;
    END;

    BEGIN TRANSACTION;

    -- Update order status to Cancelled (6)
    UPDATE [dbo].[Orders]
    SET
        OrderStatus = 6,
        CancelledAt = GETUTCDATE(),
        CancellationReason = @CancellationReason,
        UpdatedAt = GETUTCDATE(),
        UpdatedBy = @UserId
    WHERE OrderId = @OrderId;

    -- Tracking timeline entry.
    INSERT INTO [dbo].[OrderTrackings] ([OrderId], [Status], [Note], [ChangedBy])
    VALUES (@OrderId, N'CANCELLED',
            COALESCE(N'Order cancelled by buyer. Reason: ' + @CancellationReason,
                     N'Order cancelled by buyer.'),
            @UserId);

    COMMIT TRANSACTION;

    -- Return updated order
    SELECT
        OrderId, UserId, OrderNumber, OrderStatus, TotalAmount,
        ShippingAddressId, PaymentMode, ExpectedDeliveryDate,
        CancelledAt, CancellationReason, CreatedAt
    FROM [dbo].[Orders]
    WHERE OrderId = @OrderId;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Pricing_Offer_Create]...';


GO
CREATE PROCEDURE [dbo].[usp_Pricing_Offer_Create]
    @OfferName        NVARCHAR(200),
    @OfferType        TINYINT,        -- 1=Flat, 2=Percentage, 3=BOGO
    @DiscountValue    DECIMAL(18,2),
    @MaxDiscountCap   DECIMAL(18,2)   = NULL,
    @MinOrderValue    DECIMAL(18,2)   = 0.00,
    @ApplicableOn     TINYINT         = 4,  -- 1=Product, 2=Category, 3=Brand, 4=All
    @EntityId         INT             = NULL,
    @StartDate        DATE,
    @EndDate          DATE,
    @UsageLimitTotal  INT             = NULL,
    @CreatedBy        INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @StartDate > @EndDate
            THROW 50170, N'StartDate must be before EndDate.', 1;

        IF @OfferType NOT IN (1, 2, 3)
            THROW 50171, N'Invalid offer type. Must be 1 (Flat), 2 (Percentage), or 3 (BOGO).', 1;

        INSERT INTO [dbo].[Offers]
            ([OfferName], [OfferType], [DiscountValue], [MaxDiscountCap],
             [MinOrderValue], [ApplicableOn], [EntityId],
             [StartDate], [EndDate], [UsageLimitTotal], [CurrentUsageCount],
             [IsActive], [CreatedAt], [CreatedBy], [IsDeleted])
        VALUES
            (@OfferName, @OfferType, @DiscountValue, @MaxDiscountCap,
             @MinOrderValue, @ApplicableOn, @EntityId,
             @StartDate, @EndDate, @UsageLimitTotal, 0,
             1, GETUTCDATE(), @CreatedBy, 0);

        SELECT SCOPE_IDENTITY() AS [OfferId];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Pricing_Offer_GetActive]...';


GO
CREATE PROCEDURE [dbo].[usp_Pricing_Offer_GetActive]
    @ProductId  INT = NULL,
    @CategoryId INT = NULL,
    @BrandId    INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Today DATE = CAST(GETUTCDATE() AS DATE);

        SELECT
            o.[OfferId],
            o.[OfferName],
            o.[OfferType],
            o.[DiscountValue],
            o.[MaxDiscountCap],
            o.[MinOrderValue],
            o.[ApplicableOn],
            o.[EntityId],
            o.[StartDate],
            o.[EndDate],
            o.[UsageLimitTotal],
            o.[CurrentUsageCount]
        FROM [dbo].[Offers] o
        WHERE o.[IsDeleted] = 0
          AND o.[IsActive]  = 1
          AND o.[StartDate] <= @Today
          AND o.[EndDate]   >= @Today
          AND (o.[UsageLimitTotal] IS NULL OR o.[CurrentUsageCount] < o.[UsageLimitTotal])
          AND (
              @ProductId  IS NULL
           OR @CategoryId IS NULL
           OR @BrandId    IS NULL
           OR (o.[ApplicableOn] = 1 AND o.[EntityId] = @ProductId)
           OR (o.[ApplicableOn] = 2 AND o.[EntityId] = @CategoryId)
           OR (o.[ApplicableOn] = 3 AND o.[EntityId] = @BrandId)
           OR  o.[ApplicableOn] = 4
          )
        ORDER BY o.[DiscountValue] DESC;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Pricing_OffersMaster_Get]...';


GO
CREATE PROCEDURE [dbo].[usp_Pricing_OffersMaster_Get]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Today DATE = CAST(GETUTCDATE() AS DATE);

        -- Result set #1: storefront coupons (joined with their backing offer)
        SELECT
            c.[CouponCode],
            o.[OfferName],
            o.[OfferType],
            o.[DiscountValue],
            o.[MinOrderValue],
            o.[MaxDiscountCap],
            o.[EndDate]
        FROM [dbo].[Coupons] c
        INNER JOIN [dbo].[Offers] o ON o.[OfferId] = c.[OfferId]
        WHERE c.[IsDeleted] = 0
          AND c.[IsActive]  = 1
          AND o.[IsDeleted] = 0
          AND o.[IsActive]  = 1
          AND o.[StartDate] <= @Today
          AND o.[EndDate]   >= @Today
        ORDER BY o.[DiscountValue] DESC;

        -- Result set #2: payment / bank offers (informational)
        SELECT
            [BankOfferId],
            [Title],
            [Description],
            [MinSpend],
            [MaxDiscount],
            [TermsUrl],
            [SortOrder]
        FROM [dbo].[BankOffers]
        WHERE [IsDeleted] = 0
          AND [IsActive]  = 1
        ORDER BY [SortOrder] ASC, [BankOfferId] ASC;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seed_CategoryUpdates]...';


GO
CREATE PROCEDURE [dbo].[usp_Seed_CategoryUpdates]
AS
BEGIN
    SET NOCOUNT ON;

    -- Get category IDs
    DECLARE @MenCategoryId INT = (SELECT CategoryId FROM Categories WHERE CategoryName = 'Men' AND IsDeleted = 0)
DECLARE @WomenCategoryId INT = (SELECT CategoryId FROM Categories WHERE CategoryName = 'Women' AND IsDeleted = 0)
DECLARE @KidsCategoryId INT = (SELECT CategoryId FROM Categories WHERE CategoryName = 'Kids' AND IsDeleted = 0)
DECLARE @BrandId INT = 1  -- Default brand
DECLARE @SellerId INT = 1  -- Default seller
DECLARE @CurrentDate DATETIME2 = GETUTCDATE()

-- ============================================================
-- STEP 1: Remove incorrect subcategories
-- ============================================================
-- Remove "Dresses" from Men if it exists
UPDATE SubCategories SET IsDeleted = 1, UpdatedAt = @CurrentDate
WHERE CategoryId = @MenCategoryId AND SubCategoryName IN ('Dresses', 'Skirts', 'Sarees', 'Lehengas')

-- ============================================================
-- STEP 2: Add/Verify WOMEN Subcategories
-- ============================================================
IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Casual Wear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Casual Wear', 'women-casual-wear', 'https://via.placeholder.com/50?text=CasualWear', 1, 1, 'Women Casual Wear', 'Shop women casual wear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Formal Wear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Formal Wear', 'women-formal-wear', 'https://via.placeholder.com/50?text=FormalWear', 2, 1, 'Women Formal Wear', 'Shop women formal wear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Indian & Festive Wear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Indian & Festive Wear', 'women-indian-festive-wear', 'https://via.placeholder.com/50?text=IndianWear', 3, 1, 'Women Indian & Festive Wear', 'Shop women Indian & festive wear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Innerewear & Sleepwear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Innerewear & Sleepwear', 'women-innerwear-sleepwear', 'https://via.placeholder.com/50?text=Innerwear', 4, 0, 'Women Innerwear & Sleepwear', 'Shop women innerwear & sleepwear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Footwear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Footwear', 'women-footwear', 'https://via.placeholder.com/50?text=Footwear', 5, 1, 'Women Footwear', 'Shop women shoes & footwear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Accessories' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Accessories', 'women-accessories', 'https://via.placeholder.com/50?text=Accessories', 6, 1, 'Women Accessories', 'Shop women accessories', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @WomenCategoryId AND SubCategoryName = 'Winterwear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@WomenCategoryId, 'Winterwear', 'women-winterwear', 'https://via.placeholder.com/50?text=Winterwear', 7, 1, 'Women Winterwear', 'Shop women winterwear', 1)

-- ============================================================
-- STEP 3: Add/Verify KIDS Subcategories
-- ============================================================
IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @KidsCategoryId AND SubCategoryName = 'Boys Wear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@KidsCategoryId, 'Boys Wear', 'kids-boys-wear', 'https://via.placeholder.com/50?text=BoysWear', 1, 1, 'Kids Boys Wear', 'Shop boys clothing', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @KidsCategoryId AND SubCategoryName = 'Girls Wear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@KidsCategoryId, 'Girls Wear', 'kids-girls-wear', 'https://via.placeholder.com/50?text=GirlsWear', 2, 1, 'Kids Girls Wear', 'Shop girls clothing', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @KidsCategoryId AND SubCategoryName = 'Innerwear & Sleepwear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@KidsCategoryId, 'Innerwear & Sleepwear', 'kids-innerwear-sleepwear', 'https://via.placeholder.com/50?text=Innerwear', 3, 0, 'Kids Innerwear & Sleepwear', 'Shop kids innerwear & sleepwear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @KidsCategoryId AND SubCategoryName = 'Footwear' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@KidsCategoryId, 'Footwear', 'kids-footwear', 'https://via.placeholder.com/50?text=KidsFootwear', 4, 1, 'Kids Footwear', 'Shop kids shoes & footwear', 1)

IF NOT EXISTS (SELECT 1 FROM SubCategories WHERE CategoryId = @KidsCategoryId AND SubCategoryName = 'Accessories' AND IsDeleted = 0)
    INSERT INTO SubCategories (CategoryId, SubCategoryName, SlugUrl, IconUrl, SortOrder, IsFeatured, MetaTitle, MetaDescription, IsActive)
    VALUES (@KidsCategoryId, 'Accessories', 'kids-accessories', 'https://via.placeholder.com/50?text=KidsAccessories', 5, 1, 'Kids Accessories', 'Shop kids accessories', 1)

-- ============================================================
-- STEP 4: Add Sample Products for Women Category
-- ============================================================
