PRINT N'Creating Procedure [dbo].[usp_Seller_Analytics_Aggregate]...';


GO
-- Called by a scheduled job (e.g., SQL Agent) nightly to populate SellerAnalyticsDaily.
CREATE PROCEDURE [dbo].[usp_Seller_Analytics_Aggregate]
    @AggregateDate DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SET @AggregateDate = COALESCE(@AggregateDate, CAST(DATEADD(DAY, -1, GETUTCDATE()) AS DATE));

        BEGIN TRANSACTION;

            MERGE [dbo].[SellerAnalyticsDaily] AS tgt
            USING (
                SELECT
                    oi.[SellerId],
                    @AggregateDate                  AS [AnalyticsDate],
                    COUNT(DISTINCT o.[OrderId])     AS [TotalOrders],
                    SUM(oi.[TotalPrice])            AS [TotalRevenue],
                    SUM(oi.[CommissionAmount])      AS [TotalCommission],
                    SUM(oi.[SellerEarning])         AS [TotalEarnings],
                    ISNULL(pv.[TotalViews], 0)      AS [TotalProductViews],
                    ISNULL(pv.[UniqueVisitors], 0)  AS [TotalUniqueVisitors]
                FROM [dbo].[OrderItems] oi
                INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
                LEFT JOIN (
                    SELECT
                        p.[SellerId],
                        COUNT(*)                          AS [TotalViews],
                        COUNT(DISTINCT pvl.[SessionId])   AS [UniqueVisitors]
                    FROM [dbo].[ProductViewLogs] pvl
                    INNER JOIN [dbo].[Products] p ON p.[ProductId] = pvl.[ProductId]
                    WHERE CAST(pvl.[ViewedAt] AS DATE) = @AggregateDate
                    GROUP BY p.[SellerId]
                ) pv ON pv.[SellerId] = oi.[SellerId]
                WHERE oi.[IsDeleted]  = 0
                  AND o.[IsDeleted]   = 0
                  AND o.[OrderStatus] NOT IN (6, 7)
                  AND CAST(o.[CreatedAt] AS DATE) = @AggregateDate
                GROUP BY oi.[SellerId], pv.[TotalViews], pv.[UniqueVisitors]
            ) AS src
            ON tgt.[SellerId] = src.[SellerId] AND tgt.[AnalyticsDate] = src.[AnalyticsDate]
            WHEN MATCHED THEN UPDATE SET
                tgt.[TotalOrders]         = src.[TotalOrders],
                tgt.[TotalRevenue]        = src.[TotalRevenue],
                tgt.[TotalCommission]     = src.[TotalCommission],
                tgt.[TotalEarnings]       = src.[TotalEarnings],
                tgt.[TotalProductViews]   = src.[TotalProductViews],
                tgt.[TotalUniqueVisitors] = src.[TotalUniqueVisitors],
                tgt.[UpdatedAt]           = GETUTCDATE()
            WHEN NOT MATCHED THEN INSERT
                ([SellerId], [AnalyticsDate], [TotalOrders], [TotalRevenue],
                 [TotalCommission], [TotalEarnings], [TotalProductViews], [TotalUniqueVisitors])
            VALUES
                (src.[SellerId], src.[AnalyticsDate], src.[TotalOrders], src.[TotalRevenue],
                 src.[TotalCommission], src.[TotalEarnings], src.[TotalProductViews], src.[TotalUniqueVisitors]);

        COMMIT TRANSACTION;

        SELECT @@ROWCOUNT AS [UpsertedRows];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_BankAccount_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_BankAccount_Add]
    @SellerId           INT,
    @AccountHolderName  NVARCHAR(200),
    @BankName           NVARCHAR(100),
    @AccountNumber      NVARCHAR(50),
    @IfscCode           NVARCHAR(20),
    @BranchName         NVARCHAR(200) = NULL,
    @IsPrimary          BIT = 0,
    @CreatedBy          INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Mandatory-primary rule: every seller must have exactly one primary
        -- bank account so settlement payouts have an unambiguous destination.
        -- If this is the seller's first bank account, force IsPrimary = 1
        -- regardless of what the caller asked. Defends against UI bypass.
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[SellerBankAccounts]
            WHERE [SellerId] = @SellerId AND [IsDeleted] = 0
        )
            SET @IsPrimary = 1;

        IF @IsPrimary = 1
            UPDATE [dbo].[SellerBankAccounts]
            SET    [IsPrimary] = 0,
                   [UpdatedAt] = GETUTCDATE(),
                   [UpdatedBy] = @CreatedBy
            WHERE  [SellerId] = @SellerId AND [IsDeleted] = 0;

        INSERT INTO [dbo].[SellerBankAccounts]
            ([SellerId], [AccountHolderName], [BankName], [AccountNumber], [IfscCode], [BranchName],
             [IsPrimary], [IsVerified], [CreatedBy], [UpdatedBy])
        VALUES
            (@SellerId, @AccountHolderName, @BankName, @AccountNumber, @IfscCode, @BranchName,
             @IsPrimary, 0, @CreatedBy, @CreatedBy);

        DECLARE @NewId INT = SCOPE_IDENTITY();
        COMMIT TRANSACTION;

        SELECT [BankAccountId], [SellerId], [AccountHolderName], [BankName],
               [AccountNumber], [IfscCode], [BranchName], [IsPrimary], [IsVerified], [CreatedAt]
        FROM   [dbo].[SellerBankAccounts]
        WHERE  [BankAccountId] = @NewId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_BankAccount_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_BankAccount_GetAll]
    @SellerId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT [BankAccountId], [SellerId], [AccountHolderName], [BankName],
           [AccountNumber], [IfscCode], [BranchName], [IsPrimary], [IsVerified],
           [VerifiedAt], [CreatedAt], [UpdatedAt]
    FROM   [dbo].[SellerBankAccounts]
    WHERE  [SellerId] = @SellerId AND [IsDeleted] = 0
    ORDER  BY [IsPrimary] DESC, [CreatedAt] DESC;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_BankAccount_SetPrimary]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_BankAccount_SetPrimary]
    @BankAccountId INT,
    @SellerId      INT,
    @UpdatedBy     INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[SellerBankAccounts]
            WHERE [BankAccountId] = @BankAccountId AND [SellerId] = @SellerId AND [IsDeleted] = 0)
            THROW 50092, N'Bank account not found for seller.', 1;

        UPDATE [dbo].[SellerBankAccounts]
        SET    [IsPrimary] = 0, [UpdatedAt] = GETUTCDATE(), [UpdatedBy] = @UpdatedBy
        WHERE  [SellerId] = @SellerId AND [IsDeleted] = 0;

        UPDATE [dbo].[SellerBankAccounts]
        SET    [IsPrimary] = 1, [UpdatedAt] = GETUTCDATE(), [UpdatedBy] = @UpdatedBy
        WHERE  [BankAccountId] = @BankAccountId;

        COMMIT TRANSACTION;

        SELECT [BankAccountId], [IsPrimary]
        FROM   [dbo].[SellerBankAccounts]
        WHERE  [BankAccountId] = @BankAccountId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Dashboard_GetAnalytics]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Dashboard_GetAnalytics]
    @SellerId INT,
    @FromDate DATE = NULL,
    @ToDate   DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @FromDate = COALESCE(@FromDate, DATEADD(DAY, -29, CAST(GETUTCDATE() AS DATE)));
    SET @ToDate   = COALESCE(@ToDate,   CAST(GETUTCDATE() AS DATE));

    DECLARE @TotalRevenue DECIMAL(18,2) = 0;
    DECLARE @TotalOrders INT = 0;
    DECLARE @TotalUnitsSold INT = 0;
    DECLARE @AverageOrderValue DECIMAL(18,2) = 0;
    DECLARE @NewOrders INT = 0;
    DECLARE @ProcessingOrders INT = 0;
    DECLARE @ShippedOrders INT = 0;
    DECLARE @DeliveredOrders INT = 0;
    DECLARE @CancelledOrders INT = 0;

    -- Revenue / orders / units — restricted to Delivered + Paid line items so
    -- this number aligns with what SellerSettlements gross sales actually pay
    -- out. Uses TotalPrice (post-discount, incl. tax) so the basis matches
    -- usp_Seller_Settlement_Calculate exactly.
    SELECT @TotalRevenue   = ISNULL(SUM(oi.[TotalPrice]), 0),
           @TotalOrders    = COUNT(DISTINCT oi.[OrderId]),
           @TotalUnitsSold = ISNULL(SUM(oi.[Quantity]), 0)
    FROM   [dbo].[OrderItems] oi
    INNER  JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
    WHERE  oi.[SellerId]     = @SellerId
       AND oi.[IsDeleted]    = 0
       AND oi.[IsReturned]   = 0
       AND o.[IsDeleted]     = 0
       AND o.[OrderStatus]   = 5   -- Delivered
       AND o.[PaymentStatus] = 2   -- Paid
       AND CAST(o.[CreatedAt] AS DATE) BETWEEN @FromDate AND @ToDate;

    -- Average order value
    SET @AverageOrderValue = CASE
        WHEN @TotalOrders > 0 THEN @TotalRevenue / @TotalOrders
        ELSE 0
    END;

    -- Orders by status (current status, regardless of date)
    SELECT @NewOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0 AND o.[OrderStatus] = 1;

    SELECT @ProcessingOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0 AND o.[OrderStatus] = 3;

    SELECT @ShippedOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0 AND o.[OrderStatus] = 4;

    SELECT @DeliveredOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0 AND o.[OrderStatus] = 5;

    SELECT @CancelledOrders = COUNT(DISTINCT oi.[OrderId])
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON oi.[OrderId] = o.[OrderId]
    WHERE oi.[SellerId] = @SellerId AND oi.[IsDeleted] = 0 AND o.[OrderStatus] = 6;

    -- Return single result set with all analytics
    SELECT
        @FromDate AS [FromDate],
        @ToDate AS [ToDate],
        @TotalRevenue AS [TotalRevenue],
        @TotalOrders AS [TotalOrders],
        @TotalUnitsSold AS [TotalUnitsSold],
        @AverageOrderValue AS [AverageOrderValue],
        @NewOrders AS [NewOrders],
        @ProcessingOrders AS [ProcessingOrders],
        @ShippedOrders AS [ShippedOrders],
        @DeliveredOrders AS [DeliveredOrders],
        @CancelledOrders AS [CancelledOrders];
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Document_Upload]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Document_Upload]
    @SellerId      INT,
    @DocumentType  TINYINT,
    @DocumentUrl   NVARCHAR(500),
    @UploadedBy    INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS (SELECT 1 FROM [dbo].[Sellers] WHERE [SellerId] = @SellerId AND [IsDeleted] = 0)
        THROW 50090, N'Seller not found.', 1;

    INSERT INTO [dbo].[SellerDocuments]
        ([SellerId], [DocumentType], [DocumentUrl], [IsVerified], [CreatedBy], [UpdatedBy])
    VALUES
        (@SellerId, @DocumentType, @DocumentUrl, 0, @UploadedBy, @UploadedBy);

    SELECT [DocumentId], [SellerId], [DocumentType], [DocumentUrl], [IsVerified], [CreatedAt]
    FROM   [dbo].[SellerDocuments]
    WHERE  [DocumentId] = SCOPE_IDENTITY();
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Document_Verify]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Document_Verify]
    @DocumentId  INT,
    @VerifiedBy  INT,
    @IsVerified  BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS (SELECT 1 FROM [dbo].[SellerDocuments] WHERE [DocumentId] = @DocumentId AND [IsDeleted] = 0)
        THROW 50091, N'Document not found.', 1;

    UPDATE [dbo].[SellerDocuments]
    SET    [IsVerified] = @IsVerified,
           [VerifiedBy] = @VerifiedBy,
           [UpdatedAt]  = GETUTCDATE(),
           [UpdatedBy]  = @VerifiedBy
    WHERE  [DocumentId] = @DocumentId;

    SELECT [DocumentId], [SellerId], [DocumentType], [DocumentUrl], [IsVerified], [VerifiedBy], [UpdatedAt]
    FROM   [dbo].[SellerDocuments]
    WHERE  [DocumentId] = @DocumentId;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_GetProfile]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_GetProfile]
    @SellerId INT = NULL,
    @UserId   INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        SELECT
            s.[SellerId],
            s.[UserId],
            s.[BusinessName],
            s.[GstNumber],
            s.[PanNumber],
            s.[BankName],
            s.[BankIfscCode],
            s.[ApprovalStatus],
            s.[CommissionRate],
            s.[IsActive],
            u.[Email],
            u.[FirstName],
            u.[LastName],
            u.[Mobile],
            u.[ProfileImageUrl],
            ua.[AddressLine1],
            ua.[City],
            ua.[State],
            ua.[PinCode]
        FROM [dbo].[Sellers]       s
        INNER JOIN [dbo].[Users]         u  ON u.[UserId]    = s.[UserId]
        LEFT  JOIN [dbo].[UserAddresses] ua ON ua.[AddressId] = s.[BusinessAddressId]
        WHERE s.[IsDeleted] = 0
          AND (s.[SellerId] = @SellerId OR @SellerId IS NULL)
          AND (s.[UserId]   = @UserId   OR @UserId   IS NULL);

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Onboarding_AdvanceStage]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Onboarding_AdvanceStage]
    @SellerId    INT,
    @Stage       NVARCHAR(50),     -- 'business', 'bank', 'pickup', 'documents', 'agreement', 'complete'
    @CompletedBy INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS (SELECT 1 FROM [dbo].[Sellers] WHERE [SellerId] = @SellerId AND [IsDeleted] = 0)
        THROW 50090, N'Seller not found.', 1;

    UPDATE [dbo].[Sellers]
    SET    [OnboardingCompleted] = CASE WHEN @Stage = N'complete' THEN 1 ELSE [OnboardingCompleted] END,
           [UpdatedAt]           = GETUTCDATE(),
           [UpdatedBy]           = @CompletedBy
    WHERE  [SellerId] = @SellerId;

    SELECT [SellerId],
           [OnboardingCompleted],
           [ApprovalStatus],
           @Stage AS [Stage]
    FROM   [dbo].[Sellers]
    WHERE  [SellerId] = @SellerId;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Order_Cancel]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Order_Cancel]
    @OrderId            INT,
    @SellerId           INT,
    @CancellationReason NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Verify the seller owns at least one item in this order
        IF NOT EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems] oi
            INNER JOIN [dbo].[ProductVariants] pv ON pv.[VariantId] = oi.[VariantId]
            INNER JOIN [dbo].[Products] p         ON p.[ProductId]  = pv.[ProductId]
            WHERE oi.[OrderId] = @OrderId
              AND p.[SellerId] = @SellerId
              AND oi.[IsDeleted] = 0
        )
            THROW 50090, N'Order not found or you do not have permission to cancel it.', 1;

        DECLARE @CurrentStatus  TINYINT;
        DECLARE @BuyerUserId    INT;
        DECLARE @PaymentMode    TINYINT;
        DECLARE @TotalAmount    DECIMAL(18,2);
        DECLARE @OrderNumber    NVARCHAR(50);

        SELECT
            @CurrentStatus = [OrderStatus],
            @BuyerUserId   = [UserId],
            @PaymentMode   = [PaymentMode],
            @TotalAmount   = [TotalAmount],
            @OrderNumber   = [OrderNumber]
        FROM [dbo].[Orders]
        WHERE [OrderId] = @OrderId AND [IsDeleted] = 0;

        IF @CurrentStatus IS NULL
            THROW 50091, N'Order not found.', 1;

        -- Seller can cancel Pending (1), Confirmed (2), or Processing (3) orders
        IF @CurrentStatus NOT IN (1, 2, 3)
            THROW 50092, N'Order cannot be cancelled at this stage.', 1;

        BEGIN TRANSACTION;

            -- Cancel the order
            UPDATE [dbo].[Orders]
            SET    [OrderStatus]        = 6,
                   [CancelledAt]        = GETUTCDATE(),
                   [CancellationReason] = @CancellationReason,
                   [UpdatedAt]          = GETUTCDATE(),
                   [UpdatedBy]          = @SellerId
            WHERE  [OrderId] = @OrderId;

            -- Restore stock
            UPDATE pv
            SET    pv.[StockQuantity] = pv.[StockQuantity] + oi.[Quantity],
                   pv.[UpdatedAt]     = GETUTCDATE(),
                   pv.[UpdatedBy]     = @SellerId
            FROM [dbo].[ProductVariants] pv
            INNER JOIN [dbo].[OrderItems] oi ON oi.[VariantId] = pv.[VariantId]
                AND oi.[OrderId] = @OrderId
                AND oi.[IsDeleted] = 0;

            -- Credit wallet if payment was online (PaymentMode = 2)
            IF @PaymentMode = 2
            BEGIN
                MERGE [dbo].[Wallets] AS target
                USING (SELECT @BuyerUserId AS [UserId]) AS source ON target.[UserId] = source.[UserId]
                WHEN MATCHED THEN
                    UPDATE SET [Balance] = [Balance] + @TotalAmount, [UpdatedAt] = GETUTCDATE()
                WHEN NOT MATCHED THEN
                    INSERT ([UserId], [Balance], [CreatedAt], [UpdatedAt])
                    VALUES (@BuyerUserId, @TotalAmount, GETUTCDATE(), GETUTCDATE());

                DECLARE @WalletId INT;
                SELECT @WalletId = [WalletId] FROM [dbo].[Wallets] WHERE [UserId] = @BuyerUserId;

                INSERT INTO [dbo].[WalletTransactions]
                    ([WalletId], [UserId], [Amount], [TransactionType],
                     [ReferenceType], [ReferenceId], [Description], [CreatedAt])
                VALUES
                    (@WalletId, @BuyerUserId, @TotalAmount, 1,
                     N'OrderRefund', @OrderId,
                     N'Refund for cancelled order #' + @OrderNumber,
                     GETUTCDATE());
            END;

            -- Notify buyer
            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@BuyerUserId,
                 N'Order Cancelled by Seller',
                 CASE WHEN @PaymentMode = 2
                      THEN N'Your order #' + @OrderNumber + N' has been cancelled by the seller. The amount of ₹' + CAST(@TotalAmount AS NVARCHAR(20)) + N' has been refunded to your wallet.'
                      ELSE N'Your order #' + @OrderNumber + N' has been cancelled by the seller.'
                 END,
                 1, N'Order', @OrderId, 1);

            -- Tracking timeline entry.
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [Status], [Note], [ChangedBy])
            VALUES (@OrderId, N'CANCELLED',
                    COALESCE(N'Order cancelled by seller. Reason: ' + @CancellationReason,
                             N'Order cancelled by seller.'),
                    @SellerId);

        COMMIT TRANSACTION;

        -- Return order details for email
        SELECT
            @BuyerUserId  AS [BuyerUserId],
            @OrderNumber  AS [OrderNumber],
            @TotalAmount  AS [TotalAmount],
            @PaymentMode  AS [PaymentMode];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Order_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Order_GetAll]
    @SellerId    INT,
    @OrderStatus TINYINT = NULL,
    @FromDate    DATE    = NULL,
    @ToDate      DATE    = NULL,
    @PageNumber  INT = 1,
    @PageSize    INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            o.[OrderId],
            o.[OrderNumber],
            o.[OrderStatus],
            o.[TotalAmount],
            o.[PaymentMode],
            o.[PaymentStatus],
            o.[CreatedAt]    AS [OrderDate],
            u.[FirstName],
            u.[LastName],
            u.[Email],
            oi.[OrderItemId],
            oi.[ProductName],
            oi.[VariantSnapshot],
            oi.[Quantity],
            oi.[TotalPrice],
            oi.[SellerEarning],
            pi_.[ImageUrl]   AS [ProductImageUrl],
            COUNT(*) OVER()  AS [TotalCount]
        FROM [dbo].[OrderItems]       oi
        INNER JOIN [dbo].[Orders]         o  ON o.[OrderId]  = oi.[OrderId]  AND o.[IsDeleted]  = 0
        INNER JOIN [dbo].[Users]          u  ON u.[UserId]   = o.[UserId]
        LEFT  JOIN [dbo].[ProductImages]  pi_ ON pi_.[ProductId] = oi.[ProductId]
                                              AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        WHERE oi.[SellerId]  = @SellerId
          AND oi.[IsDeleted] = 0
          AND (@OrderStatus IS NULL OR o.[OrderStatus] = @OrderStatus)
          AND (@FromDate     IS NULL OR CAST(o.[CreatedAt] AS DATE) >= @FromDate)
          AND (@ToDate       IS NULL OR CAST(o.[CreatedAt] AS DATE) <= @ToDate)
        ORDER BY o.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Order_UpdateStatus]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Order_UpdateStatus]
    @OrderId     INT,
    @SellerId    INT,
    @NewStatus   TINYINT,   -- 3=Processing, 4=Shipped, 5=Delivered
    @UpdatedBy   INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Validate the order contains items from this seller
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[OrderItems] oi
            INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
            WHERE oi.[OrderId] = @OrderId AND oi.[SellerId] = @SellerId
              AND oi.[IsDeleted] = 0 AND o.[IsDeleted] = 0
        )
            THROW 50090, N'Order not found or does not belong to this seller.', 1;

        -- Sellers can only move status forward (no cancellation via this SP)
        IF @NewStatus NOT IN (3, 4, 5)
            THROW 50091, N'Invalid status transition. Sellers may set Processing, Shipped, or Delivered.', 1;

        DECLARE @DeliveredAt DATETIME2(0) = CASE WHEN @NewStatus = 5 THEN GETUTCDATE() ELSE NULL END;

        UPDATE [dbo].[Orders]
        SET    [OrderStatus]  = @NewStatus,
               [DeliveredAt] = COALESCE(@DeliveredAt, [DeliveredAt]),
               [UpdatedAt]   = GETUTCDATE(),
               [UpdatedBy]   = @UpdatedBy
        WHERE  [OrderId] = @OrderId;

        SELECT 1 AS [Success];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_Confirm]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_Confirm]
    @OrderItemId  INT,
    @SellerId     INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Ownership + state guard. Only "Placed" lines (status 1) can be confirmed.
        IF NOT EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [SellerId]    = @SellerId
              AND [IsDeleted]   = 0
        )
            THROW 50300, N'Order item not found or not owned by seller.', 1;

        IF EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [OrderStatus] <> 1
        )
            THROW 50301, N'Only newly placed items can be confirmed.', 1;

        BEGIN TRANSACTION;

            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus]  = 2,                  -- Confirmed
                   [ConfirmedAt]  = GETUTCDATE(),
                   [UpdatedAt]    = GETUTCDATE()
            WHERE  [OrderItemId]  = @OrderItemId;

            -- Buyer notification
            DECLARE @OrderId       INT;
            DECLARE @OrderNumber   NVARCHAR(50);
            DECLARE @BuyerId       INT;
            DECLARE @ProductName   NVARCHAR(300);

            SELECT @OrderId    = o.[OrderId],
                   @OrderNumber= o.[OrderNumber],
                   @BuyerId    = o.[UserId],
                   @ProductName= oi.[ProductName]
            FROM   [dbo].[OrderItems] oi
            INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
            WHERE  oi.[OrderItemId] = @OrderItemId;

            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@BuyerId,
                 N'Order Confirmed',
                 N'The seller has confirmed "' + @ProductName + N'" in order ' + @OrderNumber + N'.',
                 2, N'Order', @OrderId, 1);

            -- Append CONFIRMED entry to the order's tracking timeline.
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [OrderItemId], [Status], [Note])
            VALUES (@OrderId, @OrderItemId, N'CONFIRMED', N'Seller confirmed "' + @ProductName + N'".');

        COMMIT TRANSACTION;

        SELECT @OrderItemId AS [OrderItemId], 2 AS [OrderStatus], @OrderNumber AS [OrderNumber];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_GetLabelData]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_GetLabelData]
    @OrderItemId  INT,
    @SellerId     INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Authorize: seller can only generate labels for their own items, and only
        -- after the line has been confirmed (or further along the lifecycle).
        IF NOT EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [SellerId]    = @SellerId
              AND [IsDeleted]   = 0
        )
            THROW 50310, N'Order item not found or not owned by seller.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [OrderStatus] IN (2, 3, 4, 5)   -- Confirmed, Packed, Dispatched, Delivered
        )
            THROW 50311, N'Label is only available after the item is confirmed.', 1;

        SELECT
            oi.[OrderItemId],
            oi.[OrderStatus]          AS [LineStatus],
            o.[OrderId],
            o.[OrderNumber],
            o.[CreatedAt]             AS [OrderDate],
            o.[PaymentMode],
            o.[PaymentStatus],
            -- Line totals
            oi.[ProductName],
            oi.[VariantSnapshot],
            oi.[Quantity],
            oi.[UnitPrice],
            oi.[TaxAmount],
            oi.[TotalPrice],
            pv.[VariantSku],
            pv.[Color],
            pv.[Size],
            pv.[Weight]               AS [VariantWeightGm],
            -- Code128 + QR payloads
            CONCAT(N'SNS-', oi.[OrderItemId], N'-', ISNULL(pv.[VariantSku], N'X')) AS [BarcodeValue],
            CONCAT(N'/seller/orders/items/', oi.[OrderItemId])                    AS [QrPayload],
            -- Buyer (masked phone — keep last 4)
            (u.[FirstName] + N' ' + ISNULL(u.[LastName], N''))                    AS [BuyerName],
            CASE
                WHEN LEN(u.[Mobile]) >= 4
                    THEN N'XXXXXX' + RIGHT(u.[Mobile], 4)
                ELSE u.[Mobile]
            END                                                                   AS [BuyerPhoneMasked],
            ua.[AddressLine1],
            ua.[AddressLine2],
            ua.[City]    AS [BuyerCity],
            ua.[State]   AS [BuyerState],
            ua.[PinCode] AS [BuyerPincode],
            ua.[Country] AS [BuyerCountry],
            -- Seller (FROM panel)
            s.[BusinessName]      AS [SellerBusinessName],
            s.[GstNumber]         AS [SellerGstNumber],
            s.[SupportPhone]      AS [SellerSupportPhone],
            s.[SupportEmail]      AS [SellerSupportEmail],
            s.[LogoUrl]           AS [SellerLogoUrl],
            s.[PickupAddressLine1] AS [SellerAddressLine1],
            s.[PickupAddressLine2] AS [SellerAddressLine2],
            s.[PickupCity]        AS [SellerCity],
            s.[PickupState]       AS [SellerState],
            s.[PickupPincode]     AS [SellerPincode]
        FROM   [dbo].[OrderItems] oi
        INNER JOIN [dbo].[Orders]          o   ON o.[OrderId]   = oi.[OrderId]
        INNER JOIN [dbo].[Users]           u   ON u.[UserId]    = o.[UserId]
        INNER JOIN [dbo].[UserAddresses]   ua  ON ua.[AddressId] = o.[ShippingAddressId]
        INNER JOIN [dbo].[Sellers]         s   ON s.[SellerId]  = oi.[SellerId]
        LEFT  JOIN [dbo].[ProductVariants] pv  ON pv.[VariantId] = oi.[VariantId]
        WHERE  oi.[OrderItemId] = @OrderItemId;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_GetQueue]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_GetQueue]
    @SellerId    INT,
    @StatusFilter NVARCHAR(20) = N'all',   -- 'placed' | 'confirmed' | 'rejected' | 'fulfilled' | 'all'
    @Page         INT = 1,
    @PageSize     INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@Page - 1) * @PageSize;

        SELECT
            oi.[OrderItemId],
            oi.[OrderId],
            o.[OrderNumber],
            oi.[ProductId],
            oi.[VariantId],
            oi.[ProductName],
            oi.[VariantSnapshot],
            oi.[Quantity],
            oi.[UnitPrice],
            oi.[TotalPrice],
            oi.[OrderStatus],
            oi.[CreatedAt],
            oi.[ConfirmedAt],
            oi.[RejectedAt],
            oi.[RejectionReason],
            o.[PaymentMode],
            o.[PaymentStatus],
            u.[FirstName] + N' ' + ISNULL(u.[LastName], N'') AS [BuyerName],
            u.[Mobile] AS [BuyerMobile],
            ua.[City]    AS [BuyerCity],
            ua.[PinCode] AS [BuyerPincode],
            (SELECT TOP 1 pi.[ImageUrl]
                FROM   [dbo].[ProductImages] pi
                WHERE  pi.[ProductId] = oi.[ProductId]
                  AND  pi.[IsDeleted] = 0
                ORDER BY pi.[IsPrimary] DESC, pi.[SortOrder] ASC) AS [PrimaryImageUrl],
            COUNT(*) OVER() AS [TotalCount]
        FROM   [dbo].[OrderItems] oi
        INNER JOIN [dbo].[Orders]        o  ON o.[OrderId] = oi.[OrderId]
        INNER JOIN [dbo].[Users]         u  ON u.[UserId]  = o.[UserId]
        LEFT  JOIN [dbo].[UserAddresses] ua ON ua.[AddressId] = o.[ShippingAddressId]
        WHERE  oi.[SellerId]  = @SellerId
          AND  oi.[IsDeleted] = 0
          AND (
                @StatusFilter = N'all'
             OR (@StatusFilter = N'placed'    AND oi.[OrderStatus] = 1)
             OR (@StatusFilter = N'confirmed' AND oi.[OrderStatus] = 2)
             OR (@StatusFilter = N'rejected'  AND oi.[OrderStatus] = 8)
             OR (@StatusFilter = N'fulfilled' AND oi.[OrderStatus] IN (3, 4, 9, 5))
              )
        ORDER BY
            CASE oi.[OrderStatus] WHEN 1 THEN 0 ELSE 1 END,  -- pending first
            oi.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_GetQueueCounts]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_GetQueueCounts]
    @SellerId INT
AS
/*
  Returns the per-tab counts for the seller fulfilment queue in a single row.
  Bucket mapping mirrors usp_Seller_OrderItem_GetQueue:
    placed    → OrderStatus = 1
    confirmed → OrderStatus = 2
    rejected  → OrderStatus = 8
    fulfilled → OrderStatus IN (3, 4, 5)   -- Packed | Dispatched | Delivered
    all       → every non-deleted line for this seller (no status filter)

  One SELECT, one index scan on IX_OrderItems_SellerQueue. Designed to be
  polled every 30s by the UI without putting load on the box.
*/
BEGIN
    SET NOCOUNT ON;

    SELECT
        SUM(CASE WHEN oi.[OrderStatus] = 1              THEN 1 ELSE 0 END) AS [Placed],
        SUM(CASE WHEN oi.[OrderStatus] = 2              THEN 1 ELSE 0 END) AS [Confirmed],
        SUM(CASE WHEN oi.[OrderStatus] = 8              THEN 1 ELSE 0 END) AS [Rejected],
        SUM(CASE WHEN oi.[OrderStatus] IN (3, 4, 9, 5)  THEN 1 ELSE 0 END) AS [Fulfilled],
        COUNT(*)                                                            AS [All]
    FROM [dbo].[OrderItems] oi
    WHERE oi.[SellerId]  = @SellerId
      AND oi.[IsDeleted] = 0;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_Reject]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_Reject]
    @OrderItemId  INT,
    @SellerId     INT,
    @Reason       NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Reason IS NULL OR LEN(LTRIM(RTRIM(@Reason))) < 10
            THROW 50302, N'Rejection reason must be at least 10 characters.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [SellerId]    = @SellerId
              AND [IsDeleted]   = 0
        )
            THROW 50300, N'Order item not found or not owned by seller.', 1;

        -- Only un-dispatched lines can be rejected (statuses 1 Placed or 2 Confirmed).
        IF EXISTS (
            SELECT 1
            FROM [dbo].[OrderItems]
            WHERE [OrderItemId] = @OrderItemId
              AND [OrderStatus] NOT IN (1, 2)
        )
            THROW 50303, N'This item can no longer be rejected.', 1;

        DECLARE @VariantId      INT;
        DECLARE @Quantity       INT;
        DECLARE @TotalPrice     DECIMAL(18,2);
        DECLARE @OrderId        INT;
        DECLARE @OrderNumber    NVARCHAR(50);
        DECLARE @BuyerId        INT;
        DECLARE @ProductName    NVARCHAR(300);
        DECLARE @PaymentMode    TINYINT;
        DECLARE @PaymentStatus  TINYINT;

        SELECT @VariantId     = oi.[VariantId],
               @Quantity      = oi.[Quantity],
               @TotalPrice    = oi.[TotalPrice],
               @OrderId       = o.[OrderId],
               @OrderNumber   = o.[OrderNumber],
               @BuyerId       = o.[UserId],
               @ProductName   = oi.[ProductName],
               @PaymentMode   = o.[PaymentMode],
               @PaymentStatus = o.[PaymentStatus]
        FROM   [dbo].[OrderItems] oi
        INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
        WHERE  oi.[OrderItemId] = @OrderItemId;

        BEGIN TRANSACTION;

            -- 1) Flip the line to Rejected with reason
            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus]         = 8,                       -- Rejected
                   [RejectedAt]          = GETUTCDATE(),
                   [RejectedBySellerId]  = @SellerId,
                   [RejectionReason]     = @Reason,
                   [UpdatedAt]           = GETUTCDATE()
            WHERE  [OrderItemId] = @OrderItemId;

            -- 2) Restock the variant
            UPDATE [dbo].[ProductVariants]
            SET    [StockQuantity] = [StockQuantity] + @Quantity,
                   [UpdatedAt]     = GETUTCDATE()
            WHERE  [VariantId] = @VariantId;

            -- 3) If buyer already paid, credit their wallet for this line
            IF @PaymentStatus = 2 AND @TotalPrice > 0
            BEGIN
                DECLARE @WalletId   INT;
                DECLARE @NewBalance DECIMAL(18,2);

                MERGE [dbo].[Wallets] AS target
                USING (SELECT @BuyerId AS [UserId]) AS source ON target.[UserId] = source.[UserId]
                WHEN MATCHED THEN
                    UPDATE SET [Balance] = [Balance] + @TotalPrice, [UpdatedAt] = GETUTCDATE()
                WHEN NOT MATCHED THEN
                    INSERT ([UserId], [Balance]) VALUES (@BuyerId, @TotalPrice);

                SELECT @WalletId = [WalletId] FROM [dbo].[Wallets] WHERE [UserId] = @BuyerId;

                INSERT INTO [dbo].[WalletTransactions]
                    ([WalletId], [UserId], [Amount], [TransactionType],
                     [ReferenceType], [ReferenceId], [Description], [CreatedAt])
                VALUES
                    (@WalletId, @BuyerId, @TotalPrice, 1,        -- Credit (refund)
                     N'OrderRefund', @OrderId,
                     N'Refund for rejected item in order ' + @OrderNumber,
                     GETUTCDATE());
            END

            -- 4) Buyer notification with the reason
            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@BuyerId,
                 N'Item Cancelled by Seller',
                 N'"' + @ProductName + N'" in order ' + @OrderNumber + N' was cancelled. Reason: ' + @Reason,
                 3, N'Order', @OrderId, 1);

            -- 5) If every line on the parent order is now rejected/cancelled, mark the order itself cancelled.
            IF NOT EXISTS (
                SELECT 1 FROM [dbo].[OrderItems]
                WHERE [OrderId]   = @OrderId
                  AND [IsDeleted] = 0
                  AND [OrderStatus] NOT IN (6, 8)
            )
                UPDATE [dbo].[Orders]
                SET    [OrderStatus] = 6,                          -- Cancelled
                       [UpdatedAt]   = GETUTCDATE()
                WHERE  [OrderId] = @OrderId;

            -- 6) Tracking timeline — record the rejection (with the seller's reason
            --    in the note column for buyer visibility).
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [OrderItemId], [Status], [Note])
            VALUES (@OrderId, @OrderItemId, N'REJECTED',
                    N'"' + @ProductName + N'" cancelled by seller. Reason: ' + @Reason);

        COMMIT TRANSACTION;

        SELECT @OrderItemId AS [OrderItemId], 8 AS [OrderStatus], @OrderNumber AS [OrderNumber];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_OrderItem_UpdateStatus]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_OrderItem_UpdateStatus]
    @OrderItemId  INT,
    @SellerId     INT,
    @NewStatus    TINYINT       -- 3 Packed | 4 Dispatched | 9 OutForDelivery | 5 Delivered
AS
/*
  Forward-only line-item progression for the seller fulfilment console.

  Allowed transitions (current → next):
      2 (Confirmed)        → 3 (Packed)
      3 (Packed)           → 4 (Dispatched)
      4 (Dispatched)       → 9 (OutForDelivery)
      9 (OutForDelivery)   → 5 (Delivered)

  Any other (current, next) pair raises 50306. Backward moves are blocked.
  Caller ownership is enforced — only the seller who owns the line may move it.

  Side effects:
    - When the line reaches 5 (Delivered), Orders.DeliveredAt is stamped if the
      order has any delivered child item (so Settlement_Calculate's date filter
      keeps working at the order header level).
    - Buyer notification is fired on every successful transition.
*/
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @CurrentStatus TINYINT;
        DECLARE @OrderId       INT;
        DECLARE @OrderNumber   NVARCHAR(50);
        DECLARE @BuyerId       INT;
        DECLARE @ProductName   NVARCHAR(300);

        SELECT @CurrentStatus = oi.[OrderStatus],
               @OrderId       = o.[OrderId],
               @OrderNumber   = o.[OrderNumber],
               @BuyerId       = o.[UserId],
               @ProductName   = oi.[ProductName]
        FROM   [dbo].[OrderItems] oi
        INNER JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
        WHERE  oi.[OrderItemId] = @OrderItemId
          AND  oi.[SellerId]    = @SellerId
          AND  oi.[IsDeleted]   = 0;

        IF @CurrentStatus IS NULL
            THROW 50305, N'Order item not found or not owned by seller.', 1;

        -- Whitelist forward transitions.
        DECLARE @Allowed BIT = 0;
        IF (@CurrentStatus = 2 AND @NewStatus = 3) SET @Allowed = 1;
        IF (@CurrentStatus = 3 AND @NewStatus = 4) SET @Allowed = 1;
        IF (@CurrentStatus = 4 AND @NewStatus = 9) SET @Allowed = 1;
        IF (@CurrentStatus = 9 AND @NewStatus = 5) SET @Allowed = 1;

        IF @Allowed = 0
            THROW 50306, N'Invalid transition. Items move Confirmed → Packed → Dispatched → Out for Delivery → Delivered, one step at a time.', 1;

        BEGIN TRANSACTION;

            UPDATE [dbo].[OrderItems]
            SET    [OrderStatus] = @NewStatus,
                   [UpdatedAt]   = GETUTCDATE()
            WHERE  [OrderItemId] = @OrderItemId;

            -- Stamp Orders.DeliveredAt the moment ANY child line is marked
            -- Delivered (settlement calc reads this date).
            IF @NewStatus = 5
            BEGIN
                UPDATE [dbo].[Orders]
                SET    [DeliveredAt] = COALESCE([DeliveredAt], GETUTCDATE()),
                       [UpdatedAt]   = GETUTCDATE()
                WHERE  [OrderId] = @OrderId;
            END

            DECLARE @StatusLabel NVARCHAR(40) =
                CASE @NewStatus
                    WHEN 3 THEN N'Packed'
                    WHEN 4 THEN N'Dispatched'
                    WHEN 9 THEN N'Out for Delivery'
                    WHEN 5 THEN N'Delivered'
                END;

            -- Machine-friendly status code mirrors the UI label map
            -- (PACKED / DISPATCHED / OUT_FOR_DELIVERY / DELIVERED).
            DECLARE @StatusCode NVARCHAR(40) =
                CASE @NewStatus
                    WHEN 3 THEN N'PACKED'
                    WHEN 4 THEN N'DISPATCHED'
                    WHEN 9 THEN N'OUT_FOR_DELIVERY'
                    WHEN 5 THEN N'DELIVERED'
                END;

            INSERT INTO [dbo].[Notifications]
                ([UserId], [Title], [Body], [NotificationType], [EntityType], [EntityId], [Channel])
            VALUES
                (@BuyerId,
                 N'Order Update: ' + @StatusLabel,
                 N'"' + @ProductName + N'" in order ' + @OrderNumber + N' is now ' + @StatusLabel + N'.',
                 2, N'Order', @OrderId, 1);

            -- Append the transition to the order's tracking timeline.
            INSERT INTO [dbo].[OrderTrackings] ([OrderId], [OrderItemId], [Status], [Note])
            VALUES (@OrderId, @OrderItemId, @StatusCode,
                    N'"' + @ProductName + N'" marked ' + @StatusLabel + N'.');

        COMMIT TRANSACTION;

        SELECT @OrderItemId AS [OrderItemId],
               @NewStatus   AS [OrderStatus],
               @OrderNumber AS [OrderNumber];
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
