PRINT N'Creating Procedure [dbo].[usp_Seller_PerformanceScore_Recompute]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_PerformanceScore_Recompute]
    @SellerId     INT,
    @SnapshotDate DATE = NULL,
    @WindowDays   INT  = 30
AS
/*
  Computes a rolling-window performance snapshot for a seller and upserts the row for
  (@SellerId, @SnapshotDate). Composite score weights:
    on-time dispatch    40%
    1 - cancellation %  20%
    1 - return %        20%
    avg rating / 5      20%
*/
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @SnapshotDate = COALESCE(@SnapshotDate, CAST(GETUTCDATE() AS DATE));
    DECLARE @WindowStart DATE = DATEADD(DAY, -@WindowDays, @SnapshotDate);

    DECLARE @OrdersTotal     INT = 0;
    DECLARE @OrdersDelivered INT = 0;
    DECLARE @OrdersCancelled INT = 0;
    DECLARE @OrdersReturned  INT = 0;
    DECLARE @OnTimePct       DECIMAL(5,2) = 0;
    DECLARE @CancelPct       DECIMAL(5,2) = 0;
    DECLARE @ReturnPct       DECIMAL(5,2) = 0;
    DECLARE @AvgRating       DECIMAL(3,2) = 0;

    SELECT @OrdersTotal     = COUNT(DISTINCT oi.[OrderId]),
           @OrdersDelivered = COUNT(DISTINCT CASE WHEN o.[OrderStatus] = 5 THEN oi.[OrderId] END),
           @OrdersCancelled = COUNT(DISTINCT CASE WHEN o.[OrderStatus] = 6 THEN oi.[OrderId] END),
           @OrdersReturned  = COUNT(DISTINCT CASE WHEN oi.[IsReturned] = 1 THEN oi.[OrderId] END)
    FROM   [dbo].[OrderItems] oi
    INNER  JOIN [dbo].[Orders] o ON o.[OrderId] = oi.[OrderId]
    WHERE  oi.[SellerId]   = @SellerId
       AND oi.[IsDeleted]  = 0
       AND o.[IsDeleted]   = 0
       AND CAST(o.[CreatedAt] AS DATE) BETWEEN @WindowStart AND @SnapshotDate;

    IF @OrdersTotal > 0
    BEGIN
        SET @CancelPct = CAST(@OrdersCancelled AS DECIMAL(9,2)) * 100 / @OrdersTotal;
        SET @ReturnPct = CAST(@OrdersReturned  AS DECIMAL(9,2)) * 100 / @OrdersTotal;
        SET @OnTimePct =
            CASE WHEN @OrdersDelivered = 0 THEN 0
                 ELSE CAST(@OrdersDelivered AS DECIMAL(9,2)) * 100 / NULLIF(@OrdersTotal - @OrdersCancelled, 0)
            END;
    END

    SELECT @AvgRating = COALESCE(AVG(CAST(r.[Rating] AS DECIMAL(3,2))), 0)
    FROM   [dbo].[Reviews] r
    INNER  JOIN [dbo].[Products] p ON p.[ProductId] = r.[ProductId]
    WHERE  p.[SellerId]  = @SellerId
       AND r.[IsDeleted] = 0
       AND CAST(r.[CreatedAt] AS DATE) BETWEEN @WindowStart AND @SnapshotDate;

    DECLARE @Composite DECIMAL(5,2) =
          (@OnTimePct                 * 0.40)
        + ((100 - @CancelPct)         * 0.20)
        + ((100 - @ReturnPct)         * 0.20)
        + ((@AvgRating * 20)          * 0.20);

    DECLARE @Tier NVARCHAR(20) =
        CASE
            WHEN @Composite >= 90 THEN N'Platinum'
            WHEN @Composite >= 80 THEN N'Gold'
            WHEN @Composite >= 70 THEN N'Silver'
            ELSE N'Bronze'
        END;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (
            SELECT 1 FROM [dbo].[SellerPerformanceScores]
            WHERE [SellerId] = @SellerId AND [SnapshotDate] = @SnapshotDate
        )
            UPDATE [dbo].[SellerPerformanceScores]
            SET    [WindowDays]        = @WindowDays,
                   [OrdersTotal]       = @OrdersTotal,
                   [OrdersDelivered]   = @OrdersDelivered,
                   [OrdersCancelled]   = @OrdersCancelled,
                   [OrdersReturned]    = @OrdersReturned,
                   [OnTimeDispatchPct] = @OnTimePct,
                   [CancellationPct]   = @CancelPct,
                   [ReturnPct]         = @ReturnPct,
                   [AvgRating]         = @AvgRating,
                   [CompositeScore]    = @Composite,
                   [Tier]              = @Tier
            WHERE  [SellerId] = @SellerId AND [SnapshotDate] = @SnapshotDate;
        ELSE
            INSERT INTO [dbo].[SellerPerformanceScores]
                ([SellerId], [SnapshotDate], [WindowDays],
                 [OrdersTotal], [OrdersDelivered], [OrdersCancelled], [OrdersReturned],
                 [OnTimeDispatchPct], [CancellationPct], [ReturnPct], [AvgRating],
                 [CompositeScore], [Tier])
            VALUES
                (@SellerId, @SnapshotDate, @WindowDays,
                 @OrdersTotal, @OrdersDelivered, @OrdersCancelled, @OrdersReturned,
                 @OnTimePct, @CancelPct, @ReturnPct, @AvgRating,
                 @Composite, @Tier);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT [PerformanceScoreId], [SellerId], [SnapshotDate], [WindowDays],
           [OrdersTotal], [OrdersDelivered], [OrdersCancelled], [OrdersReturned],
           [OnTimeDispatchPct], [CancellationPct], [ReturnPct], [AvgRating],
           [CompositeScore], [Tier], [CreatedAt]
    FROM   [dbo].[SellerPerformanceScores]
    WHERE  [SellerId] = @SellerId AND [SnapshotDate] = @SnapshotDate;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Product_Create]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Product_Create]
    @SellerId           INT,
    @BrandId            INT            = 1,
    @CategoryId         INT,
    @SubCategoryId      INT            = NULL,
    @GenderTypeId       TINYINT        = NULL,
    @ProductName        NVARCHAR(200),
    @ShortDescription   NVARCHAR(500)  = NULL,
    @LongDescription    NVARCHAR(MAX)  = NULL,
    @Sku                NVARCHAR(100),
    @SlugUrl            NVARCHAR(300),
    @MRP                DECIMAL(18,2),
    @SellingPrice       DECIMAL(18,2),
    @CostPrice          DECIMAL(18,2)  = NULL,
    @Tags               NVARCHAR(500)  = NULL,
    @Material           NVARCHAR(200)  = NULL,
    @CareInstructions   NVARCHAR(500)  = NULL,
    @FitType            NVARCHAR(50)   = NULL,
    @CountryOfOrigin    NVARCHAR(100)  = NULL,
    @WarrantyInfo       NVARCHAR(500)  = NULL,
    @DeliveryInfo       NVARCHAR(500)  = NULL,
    @LengthCm           DECIMAL(8,2)   = NULL,
    @WidthCm            DECIMAL(8,2)   = NULL,
    @HeightCm           DECIMAL(8,2)   = NULL,
    @WeightGm           DECIMAL(10,2)  = NULL,
    @CreatedBy          INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM [dbo].[Sellers] WHERE [SellerId] = @SellerId AND [IsDeleted] = 0)
            THROW 50100, N'Seller not found.', 1;

        IF EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [Sku] = @Sku AND [IsDeleted] = 0)
            THROW 50101, N'A product with this SKU already exists.', 1;

        IF EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SlugUrl] = @SlugUrl AND [IsDeleted] = 0)
            THROW 50102, N'A product with this slug already exists.', 1;

        INSERT INTO [dbo].[Products]
            ([SellerId], [BrandId], [CategoryId], [SubCategoryId], [GenderTypeId],
             [ProductName], [ShortDescription], [LongDescription], [Sku], [SlugUrl],
             [MRP], [SellingPrice], [CostPrice], [Tags], [ApprovalStatus],
             [Material], [CareInstructions], [FitType], [CountryOfOrigin], [WarrantyInfo], [DeliveryInfo],
             [LengthCm], [WidthCm], [HeightCm], [WeightGm],
             [CreatedAt], [CreatedBy], [IsDeleted])
        VALUES
            (@SellerId, @BrandId, @CategoryId, @SubCategoryId, @GenderTypeId,
             @ProductName, @ShortDescription, @LongDescription, @Sku, @SlugUrl,
             @MRP, @SellingPrice, @CostPrice, @Tags, 2,  -- ApprovalStatus=2 (Approved) — visible to buyers immediately
             @Material, @CareInstructions, @FitType, @CountryOfOrigin, @WarrantyInfo, @DeliveryInfo,
             @LengthCm, @WidthCm, @HeightCm, @WeightGm,
             GETUTCDATE(), @CreatedBy, 0);

        SELECT SCOPE_IDENTITY() AS [ProductId];

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_Product_GetAll]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Product_GetAll]
    @SellerId        INT,
    @ApprovalStatus  TINYINT = NULL,  -- 1=Pending, 2=Approved, 3=Rejected
    @SearchTerm      NVARCHAR(200) = NULL,
    @PageNumber      INT = 1,
    @PageSize        INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        SELECT
            p.[ProductId]                                                          AS [Id],
            p.[ProductName]                                                        AS [Name],
            p.[MRP],
            p.[SellingPrice],
            CASE WHEN p.[MRP] > 0
                 THEN ROUND((p.[MRP] - p.[SellingPrice]) * 100.0 / p.[MRP], 0)
                 ELSE 0 END                                                        AS [DiscountPct],
            ISNULL(SUM(pv.[StockQuantity]), 0)                                     AS [StockQuantity],
            ISNULL(MIN(pv.[LowStockThreshold]), 0)                                 AS [LowStockThreshold],
            pi_.[ImageUrl]                                                         AS [PrimaryImage],
            CASE WHEN p.[ApprovalStatus] = 2 THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END AS [IsApproved],
            p.[CreatedAt],
            COUNT(*)        OVER()                                                 AS [TotalCount]
        FROM [dbo].[Products]         p
        INNER JOIN [dbo].[Brands]      b   ON b.[BrandId]    = p.[BrandId]
        INNER JOIN [dbo].[Categories]  c   ON c.[CategoryId] = p.[CategoryId]
        LEFT  JOIN [dbo].[ProductImages] pi_ ON pi_.[ProductId] = p.[ProductId]
                                              AND pi_.[IsPrimary] = 1 AND pi_.[IsDeleted] = 0
        LEFT  JOIN [dbo].[ProductVariants] pv ON pv.[ProductId] = p.[ProductId] AND pv.[IsDeleted] = 0
        WHERE p.[SellerId]  = @SellerId
          AND p.[IsDeleted] = 0
          AND (@ApprovalStatus IS NULL OR p.[ApprovalStatus] = @ApprovalStatus)
          AND (@SearchTerm    IS NULL  OR p.[ProductName] LIKE N'%' + @SearchTerm + N'%'
                                      OR p.[Sku] LIKE N'%' + @SearchTerm + N'%')
        GROUP BY
            p.[ProductId], p.[ProductName],
            p.[MRP], p.[SellingPrice], p.[ApprovalStatus],
            p.[CreatedAt], pi_.[ImageUrl]
        ORDER BY p.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_ProductDisabledOptions_Set]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_ProductDisabledOptions_Set]
    @ProductId       INT,
    @SellerId        INT,
    @DisabledJson    NVARCHAR(MAX),    -- [{"optionId":12},{"optionId":15}]
    @CurrentUserId   INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Authorize: seller can only touch their own product
        IF NOT EXISTS (
            SELECT 1 FROM [dbo].[Products]
            WHERE [ProductId] = @ProductId
              AND [SellerId]  = @SellerId
              AND [IsDeleted] = 0
        )
            THROW 50221, 'Product not found or not owned by seller.', 1;

        BEGIN TRANSACTION;

        DECLARE @Incoming TABLE ([OptionId] INT NOT NULL PRIMARY KEY);
        INSERT INTO @Incoming ([OptionId])
        SELECT DISTINCT [OptionId]
        FROM OPENJSON(@DisabledJson)
        WITH ([OptionId] INT '$.optionId');

        -- Delete flags no longer in the incoming list
        DELETE d
        FROM [dbo].[ProductDisabledVariantOptions] d
        WHERE d.[ProductId] = @ProductId
          AND d.[OptionId] NOT IN (SELECT [OptionId] FROM @Incoming);

        -- Insert new flags
        INSERT INTO [dbo].[ProductDisabledVariantOptions] ([ProductId], [OptionId], [CreatedBy])
        SELECT @ProductId, i.[OptionId], @CurrentUserId
        FROM @Incoming i
        WHERE NOT EXISTS (
            SELECT 1 FROM [dbo].[ProductDisabledVariantOptions] existing
            WHERE existing.[ProductId] = @ProductId
              AND existing.[OptionId]  = i.[OptionId]
        );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Seller_ProductImage_Add]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_ProductImage_Add]
    @ProductId  INT,
    @ImageUrl   NVARCHAR(500),
    @IsPrimary  BIT = 0,
    @SortOrder  INT = 0,
    @ImageSlot  NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [ProductId] = @ProductId AND [IsDeleted] = 0)
            THROW 50200, N'Product not found.', 1;

        -- Demote any existing primary if this one is being set primary.
        IF @IsPrimary = 1
        BEGIN
            UPDATE [dbo].[ProductImages]
               SET [IsPrimary] = 0,
                   [UpdatedAt] = GETUTCDATE()
             WHERE [ProductId] = @ProductId
               AND [IsPrimary] = 1
               AND [IsDeleted] = 0;
        END;

        INSERT INTO [dbo].[ProductImages]
            ([ProductId], [ImageUrl], [IsPrimary], [SortOrder], [ImageSlot])
        VALUES
            (@ProductId, @ImageUrl, @IsPrimary, @SortOrder, @ImageSlot);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS [ImageId];
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
