PRINT N'Creating Procedure [dbo].[usp_Seller_Warehouse_Upsert]...';


GO
CREATE PROCEDURE [dbo].[usp_Seller_Warehouse_Upsert]
    @SellerWarehouseId INT = NULL,
    @SellerId          INT,
    @Name              NVARCHAR(200),
    @ContactName       NVARCHAR(200) = NULL,
    @ContactPhone      NVARCHAR(20)  = NULL,
    @AddressLine1      NVARCHAR(300),
    @AddressLine2      NVARCHAR(300) = NULL,
    @City              NVARCHAR(100),
    @State             NVARCHAR(100),
    @Pincode           NVARCHAR(10),
    @IsPrimary         BIT = 0,
    @UpdatedBy         INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @IsPrimary = 1
            UPDATE [dbo].[SellerWarehouses]
            SET    [IsPrimary] = 0, [UpdatedAt] = GETUTCDATE(), [UpdatedBy] = @UpdatedBy
            WHERE  [SellerId] = @SellerId AND [IsDeleted] = 0;

        IF @SellerWarehouseId IS NULL
        BEGIN
            INSERT INTO [dbo].[SellerWarehouses]
                ([SellerId], [Name], [ContactName], [ContactPhone], [AddressLine1], [AddressLine2],
                 [City], [State], [Pincode], [IsPrimary], [CreatedBy], [UpdatedBy])
            VALUES
                (@SellerId, @Name, @ContactName, @ContactPhone, @AddressLine1, @AddressLine2,
                 @City, @State, @Pincode, @IsPrimary, @UpdatedBy, @UpdatedBy);

            SET @SellerWarehouseId = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            UPDATE [dbo].[SellerWarehouses]
            SET    [Name] = @Name,
                   [ContactName] = @ContactName,
                   [ContactPhone] = @ContactPhone,
                   [AddressLine1] = @AddressLine1,
                   [AddressLine2] = @AddressLine2,
                   [City] = @City,
                   [State] = @State,
                   [Pincode] = @Pincode,
                   [IsPrimary] = @IsPrimary,
                   [UpdatedAt] = GETUTCDATE(),
                   [UpdatedBy] = @UpdatedBy
            WHERE  [SellerWarehouseId] = @SellerWarehouseId AND [SellerId] = @SellerId;
        END

        COMMIT TRANSACTION;

        SELECT [SellerWarehouseId], [SellerId], [Name], [AddressLine1], [City], [State], [Pincode], [IsPrimary]
        FROM   [dbo].[SellerWarehouses]
        WHERE  [SellerWarehouseId] = @SellerWarehouseId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_SellerOrder_UpdateStatus]...';


GO
CREATE PROCEDURE [dbo].[usp_SellerOrder_UpdateStatus]
    @OrderId INT,
    @SellerId INT,
    @NewStatus TINYINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentStatus TINYINT;
    DECLARE @SellerHasItems BIT;
    DECLARE @OrderUserId INT;

    -- Validate: order exists
    SELECT @CurrentStatus = OrderStatus, @OrderUserId = UserId
    FROM [dbo].[Orders]
    WHERE OrderId = @OrderId AND IsDeleted = 0;

    IF @CurrentStatus IS NULL
    BEGIN
        RAISERROR('Order not found', 16, 1);
        RETURN;
    END;

    -- Validate: seller has items in this order
    SELECT @SellerHasItems = COUNT(*)
    FROM [dbo].[OrderItems]
    WHERE OrderId = @OrderId AND SellerId = @SellerId AND IsDeleted = 0;

    IF @SellerHasItems = 0
    BEGIN
        RAISERROR('Unauthorized: You did not sell items in this order', 16, 1);
        RETURN;
    END;

    -- Validate: status transition is valid
    -- Valid: 1→2, 2→3, 3→4, 4→5, anything→6
    IF @NewStatus NOT IN (1, 2, 3, 4, 5, 6)
    BEGIN
        RAISERROR('Invalid order status', 16, 1);
        RETURN;
    END;

    IF @NewStatus <> 6 AND @NewStatus <= @CurrentStatus
    BEGIN
        RAISERROR('Cannot revert order status. Only forward progression or cancellation allowed.', 16, 1);
        RETURN;
    END;

    BEGIN TRANSACTION;

    -- Update order status
    UPDATE [dbo].[Orders]
    SET
        OrderStatus = @NewStatus,
        UpdatedAt = GETUTCDATE(),
        UpdatedBy = @SellerId
    WHERE OrderId = @OrderId;

    -- If delivered, set delivery timestamp
    IF @NewStatus = 5
    BEGIN
        UPDATE [dbo].[Orders]
        SET DeliveredAt = GETUTCDATE()
        WHERE OrderId = @OrderId AND DeliveredAt IS NULL;
    END;

    COMMIT TRANSACTION;

    -- Return updated order
    SELECT
        OrderId, UserId, OrderNumber, OrderStatus, TotalAmount,
        ShippingAddressId, PaymentMode, ExpectedDeliveryDate,
        DeliveredAt, CreatedAt, UpdatedAt
    FROM [dbo].[Orders]
    WHERE OrderId = @OrderId;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Wallet_Credit]...';


GO
CREATE PROCEDURE [dbo].[usp_Wallet_Credit]
    @UserId         INT,
    @Amount         DECIMAL(18,2),
    @ReferenceType  NVARCHAR(50)  = NULL,
    @ReferenceId    INT           = NULL,
    @Description    NVARCHAR(300) = N'Wallet credit'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @Amount <= 0
            THROW 50080, N'Credit amount must be greater than zero.', 1;

        BEGIN TRANSACTION;

            -- Upsert wallet row
            MERGE [dbo].[Wallets] AS target
            USING (SELECT @UserId AS [UserId]) AS source ON target.[UserId] = source.[UserId]
            WHEN MATCHED THEN
                UPDATE SET
                    [Balance]   = [Balance] + @Amount,
                    [UpdatedAt] = GETUTCDATE()
            WHEN NOT MATCHED THEN
                INSERT ([UserId], [Balance], [CreatedAt], [UpdatedAt])
                VALUES (@UserId, @Amount, GETUTCDATE(), GETUTCDATE());

            DECLARE @WalletId    INT;
            DECLARE @NewBalance  DECIMAL(18,2);

            SELECT @WalletId = [WalletId], @NewBalance = [Balance]
            FROM [dbo].[Wallets]
            WHERE [UserId] = @UserId;

            -- Record transaction
            INSERT INTO [dbo].[WalletTransactions]
                ([WalletId], [UserId], [Amount], [TransactionType],
                 [ReferenceType], [ReferenceId], [Description], [CreatedAt])
            VALUES
                (@WalletId, @UserId, @Amount, 1,
                 @ReferenceType, @ReferenceId, @Description, GETUTCDATE());

        COMMIT TRANSACTION;

        SELECT @NewBalance AS [NewBalance], @WalletId AS [WalletId];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Wallet_GetBalance]...';


GO
CREATE PROCEDURE [dbo].[usp_Wallet_GetBalance]
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        -- Return existing wallet or default 0 balance if none exists
        SELECT
            ISNULL(w.[WalletId], 0)         AS [WalletId],
            @UserId                          AS [UserId],
            ISNULL(w.[Balance], 0.00)        AS [Balance],
            ISNULL(w.[UpdatedAt], GETUTCDATE()) AS [UpdatedAt]
        FROM (SELECT 1 AS [x]) AS [dummy]
        LEFT JOIN [dbo].[Wallets] w ON w.[UserId] = @UserId;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
GO
PRINT N'Creating Procedure [dbo].[usp_Wallet_GetTransactions]...';


GO
CREATE PROCEDURE [dbo].[usp_Wallet_GetTransactions]
    @UserId   INT,
    @Page     INT = 1,
    @PageSize INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@Page - 1) * @PageSize;

        SELECT
            wt.[TransactionId],
            wt.[Amount],
            wt.[TransactionType],
            wt.[ReferenceType],
            wt.[ReferenceId],
            wt.[Description],
            wt.[CreatedAt],
            COUNT(*) OVER() AS [TotalCount]
        FROM [dbo].[WalletTransactions] wt
        WHERE wt.[UserId] = @UserId
        ORDER BY wt.[CreatedAt] DESC
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH;
END;
